 AND rr.canonical_preimage=ready.canonical_preimage AND rr.revision_sha256=ready.revision_sha256;
 IF NOT FOUND THEN RAISE EXCEPTION 'EVENT43_ROOT_CAS_LOST';END IF;
 IF NOT EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness rr WHERE singleton
 AND canonical_preimage=candidate_text AND revision_sha256='9a82654dfee11bd3e27975e50b2b327221f387fcfc4e320c6f8415ca5fedff68' AND observed_revision_sha256=revision_sha256
 AND state=ready.state AND scope=ready.scope AND staff_guards_verified=ready.staff_guards_verified
