 EXECUTE $helper_ddl$CREATE OR REPLACE FUNCTION ninja_book_internal.append_legacy_narrative_binding_v1(p_template uuid,p_version uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO ''
AS $function$
DECLARE t public.nb_templates;nv public.nb_template_versions;previous_nv public.nb_template_versions;
 predecessor public.nb_mechanical_bindings;existing public.nb_mechanical_bindings;
 mt public.nb_mechanical_templates;mv public.nb_mechanical_versions;created public.nb_mechanical_bindings;
 narrative_hash text;previous_hash text;mechanical_hash text;receipt jsonb;
BEGIN
 -- Only the existing Admin approval's definer or an explicit postgres migration
 -- can invoke this helper. It accepts no actor identity or client mechanics.
 IF current_user IS DISTINCT FROM 'postgres' THEN RAISE EXCEPTION 'NB_LEGACY_BINDING_OWNER_REQUIRED' USING ERRCODE='42501';END IF;
 IF p_template IS NULL OR p_version IS NULL THEN RAISE EXCEPTION 'NB_LEGACY_BINDING_ARGUMENT' USING ERRCODE='22023';END IF;
 SELECT * INTO t FROM public.nb_templates WHERE id=p_template FOR UPDATE;
 SELECT * INTO nv FROM public.nb_template_versions WHERE id=p_version AND template_id=p_template FOR UPDATE;
 IF t.id IS NULL OR nv.id IS NULL OR t.deactivated_at IS NOT NULL
  OR t.lifecycle_state IS DISTINCT FROM 'approved' OR t.current_version_id IS DISTINCT FROM nv.id
  OR nv.review_state IS DISTINCT FROM 'approved' OR nv.approved_at IS NULL
 THEN RAISE EXCEPTION 'NB_LEGACY_BINDING_APPROVAL_SCOPE' USING ERRCODE='55000';END IF;
 -- First versions and the separate custom-NPC producer retain their own path.
 IF nv.supersedes_version_id IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO previous_nv FROM public.nb_template_versions
  WHERE id=nv.supersedes_version_id AND template_id=t.id FOR SHARE;
 IF previous_nv.id IS NULL OR previous_nv.approved_at IS NULL
  OR previous_nv.approved_at>=nv.approved_at OR previous_nv.version_no>=nv.version_no
  OR previous_nv.review_state NOT IN('approved','inactive')
 THEN RAISE EXCEPTION 'NB_LEGACY_BINDING_LINEAGE' USING ERRCODE='55000';END IF;
 SELECT * INTO predecessor FROM public.nb_mechanical_bindings
  WHERE narrative_version_id=previous_nv.id AND narrative_template_id=t.id FOR SHARE;
 IF predecessor.id IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO mv FROM public.nb_mechanical_versions WHERE id=predecessor.mechanical_version_id
  AND template_id=predecessor.mechanical_template_id FOR SHARE;
 IF mv.id IS NULL THEN RAISE EXCEPTION 'NB_LEGACY_BINDING_MECHANICAL_MISSING' USING ERRCODE='55000';END IF;
 IF mv.profile_kind IS DISTINCT FROM 'legacy' THEN RETURN NULL;END IF;
 -- A custom-mechanics review is not a legacy narrative-only successor.
 IF EXISTS(SELECT 1 FROM png_builder_internal.npc_combat_draft_heads h
  WHERE h.narrative_template_id=t.id AND h.narrative_version_id=nv.id AND h.combat)
 THEN RETURN NULL;END IF;
 SELECT * INTO mt FROM public.nb_mechanical_templates WHERE id=predecessor.mechanical_template_id FOR SHARE;
 IF predecessor.lifecycle_state IS DISTINCT FROM 'approved'
  OR mt.id IS NULL OR mt.lifecycle_state IS DISTINCT FROM 'approved' OR mt.active IS DISTINCT FROM TRUE
  OR mt.current_version_id IS DISTINCT FROM mv.id OR mv.review_state IS DISTINCT FROM 'approved'
  OR nv.mechanical_template_id IS DISTINCT FROM previous_nv.mechanical_template_id
 THEN RAISE EXCEPTION 'NB_LEGACY_BINDING_MECHANICAL_SCOPE' USING ERRCODE='55000';END IF;
 narrative_hash:=ninja_book_internal.json_hash(jsonb_build_object('schema_version',nv.schema_version,
  'skeleton',nv.skeleton,'knowledge_boundary',nv.knowledge_boundary,'fallback_profile',nv.fallback_profile,
  'mechanical_template_id',nv.mechanical_template_id));
 previous_hash:=ninja_book_internal.json_hash(jsonb_build_object('schema_version',previous_nv.schema_version,
  'skeleton',previous_nv.skeleton,'knowledge_boundary',previous_nv.knowledge_boundary,'fallback_profile',previous_nv.fallback_profile,
  'mechanical_template_id',previous_nv.mechanical_template_id));
 -- Exactly the live immutable mechanical seal's preimage; no regeneration.
 mechanical_hash:=ninja_book_internal.json_hash(jsonb_build_object('schema_version',mv.schema_version,
  'rank',mv.rank,'archetype',mv.archetype,'base_per_stat',mv.base_per_stat,'allocated_points',mv.allocated_points,
  'innata',mv.innata,'stats',mv.stats,'vita_max',mv.vita_max,'chakra_max',mv.chakra_max,
  'abilities',mv.abilities,'generation',mv.generation));
 IF narrative_hash IS DISTINCT FROM nv.content_sha256 OR previous_hash IS DISTINCT FROM previous_nv.content_sha256
  OR mechanical_hash IS DISTINCT FROM mv.content_sha256
 THEN RAISE EXCEPTION 'NB_LEGACY_BINDING_CONTENT_HASH' USING ERRCODE='55000';END IF;
 SELECT * INTO existing FROM public.nb_mechanical_bindings WHERE narrative_version_id=nv.id FOR UPDATE;
 IF existing.id IS NOT NULL THEN
  IF (existing.narrative_template_id,existing.mechanical_template_id,existing.mechanical_version_id,existing.lifecycle_state,existing.active)
    IS DISTINCT FROM(t.id,predecessor.mechanical_template_id,predecessor.mechanical_version_id,'approved'::text,FALSE)
  THEN RAISE EXCEPTION 'NB_LEGACY_BINDING_SUCCESSOR_CONFLICT' USING ERRCODE='40001';END IF;
  created:=existing;
 ELSE
  INSERT INTO public.nb_mechanical_bindings(narrative_template_id,narrative_version_id,
   mechanical_template_id,mechanical_version_id,lifecycle_state,active)
  VALUES(t.id,nv.id,predecessor.mechanical_template_id,predecessor.mechanical_version_id,'approved',FALSE)
  RETURNING * INTO created;
 END IF;
 IF created.id IS NULL OR created.id=predecessor.id OR created.narrative_version_id IS DISTINCT FROM nv.id
  OR created.active IS DISTINCT FROM FALSE OR created.control_version<1
 THEN RAISE EXCEPTION 'NB_LEGACY_BINDING_APPEND_DRIFT' USING ERRCODE='55000';END IF;
 receipt:=jsonb_build_object('schema_version','nb-legacy-narrative-binding-succession/1',
  'binding_id',created.id,'previous_binding_id',predecessor.id,'template_id',t.id,
  'narrative_version_id',nv.id,'previous_narrative_version_id',previous_nv.id,
  'narrative_content_sha256',narrative_hash,'previous_narrative_content_sha256',previous_hash,
  'mechanical_template_id',mv.template_id,'mechanical_version_id',mv.id,'mechanical_content_sha256',mechanical_hash,
  'active',FALSE,'lifecycle_state','approved','replayed',existing.id IS NOT NULL);
 RETURN receipt;
END
$function$;$helper_ddl$;
 EXECUTE 'REVOKE ALL ON FUNCTION ninja_book_internal.append_legacy_narrative_binding_v1(uuid,uuid) FROM PUBLIC,anon,authenticated,service_role';
 EXECUTE 'GRANT EXECUTE ON FUNCTION ninja_book_internal.append_legacy_narrative_binding_v1(uuid,uuid) TO postgres';
 EXECUTE $approve_ddl$CREATE OR REPLACE FUNCTION public.nb_admin_template_approve(p_template uuid, p_expected_control_version bigint, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; t public.nb_templates%rowtype; v public.nb_template_versions%rowtype; h text; prior jsonb; response jsonb; binding_receipt43 jsonb;
begin
  actor:=ninja_book_internal.require_staff(true);
  h:=ninja_book_internal.json_hash(pg_catalog.jsonb_build_object('template',p_template,'expected',p_expected_control_version));
  prior:=ninja_book_internal.replay_get(p_request_key,'nb_admin_template_approve',h); if prior is not null then return prior; end if;
  select * into t from public.nb_templates where id=p_template for update;
  if not found then raise exception using errcode='P0001',message='NB_NOT_FOUND'; end if;
  if t.control_version<>p_expected_control_version then raise exception using errcode='P0001',message='NB_STALE_CONTROL_VERSION'; end if;
  if not ((t.current_version_id is null and t.lifecycle_state='review') or
          (t.current_version_id is not null and t.lifecycle_state='approved')) then
    raise exception using errcode='P0001',message='NB_INVALID_TRANSITION'; end if;
  select * into v from public.nb_template_versions where template_id=p_template and review_state='review' order by version_no desc limit 1 for update;
  if not found or not ninja_book_internal.skeleton_complete(v.skeleton,v.knowledge_boundary,v.fallback_profile) then
    raise exception using errcode='P0001',message='NB_INCOMPLETE_SKELETON'; end if;
  update public.nb_template_versions set review_state='approved',approved_by=actor,approved_at=clock_timestamp(),
    control_version=control_version+1,updated_at=clock_timestamp() where id=v.id;
  update public.nb_template_versions set review_state='inactive',control_version=control_version+1,updated_at=clock_timestamp()
    where template_id=p_template and review_state='approved' and id<>v.id;
  update public.nb_templates set lifecycle_state='approved',current_version_id=v.id,control_version=control_version+1,updated_at=clock_timestamp()
    where id=t.id returning * into t;
  binding_receipt43:=ninja_book_internal.append_legacy_narrative_binding_v1(t.id,v.id);
  response:=pg_catalog.jsonb_build_object('template_id',t.id,'version_id',v.id,'version_no',v.version_no,
    'control_version',t.control_version,'state','approved');
  IF binding_receipt43 IS NOT NULL THEN response:=response||jsonb_build_object('binding_succession',binding_receipt43);END IF;
  return ninja_book_internal.replay_put(p_request_key,'nb_admin_template_approve',h,response,actor);
end $function$
