 EXECUTE $source_7$CREATE OR REPLACE FUNCTION public.nb_admin_template_approve(p_template uuid, p_expected_control_version bigint, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; t public.nb_templates%rowtype; v public.nb_template_versions%rowtype; h text; prior jsonb; response jsonb; binding_receipt43 jsonb;media_adoption43 jsonb;
begin
  actor:=ninja_book_internal.require_staff(true);
  h:=ninja_book_internal.json_hash(pg_catalog.jsonb_build_object('template',p_template,'expected',p_expected_control_version));
  prior:=ninja_book_internal.replay_get(p_request_key,'nb_admin_template_approve',h); if prior is not null then return prior; end if;
  select * into t from public.nb_templates where id=p_template for update;
  if not found then raise exception using errcode='P0001',message='NB_NOT_FOUND'; end if;
  if t.control_version<>p_expected_control_version then raise exception using errcode='P0001',message='NB_STALE_CONTROL_VERSION'; end if;
  if not ((t.current_version_id is null and t.lifecycle_state='review') or
          (t.current_version_id is not null and t.lifecycle_state='approved')) then
    raise exception using errcode='P0001',message='NB_INVALID_TRANSITION'; end if;
  select * into v from public.nb_template_versions where template_id=p_template and review_state='review' order by version_no desc limit 1 for update;
  if not found or not ninja_book_internal.skeleton_complete(v.skeleton,v.knowledge_boundary,v.fallback_profile) then
    raise exception using errcode='P0001',message='NB_INCOMPLETE_SKELETON'; end if;
  update public.nb_template_versions set review_state='approved',approved_by=actor,approved_at=clock_timestamp(),
    control_version=control_version+1,updated_at=clock_timestamp() where id=v.id;
  update public.nb_template_versions set review_state='inactive',control_version=control_version+1,updated_at=clock_timestamp()
    where template_id=p_template and review_state='approved' and id<>v.id;
  update public.nb_templates set lifecycle_state='approved',current_version_id=v.id,control_version=control_version+1,updated_at=clock_timestamp()
    where id=t.id returning * into t;
  binding_receipt43:=ninja_book_internal.append_legacy_narrative_binding_v1(t.id,v.id);
  media_adoption43:=ninja_book_internal.append_legacy_media_adoption_v1(t.id,v.id,p_request_key,actor);
  response:=pg_catalog.jsonb_build_object('template_id',t.id,'version_id',v.id,'version_no',v.version_no,
    'control_version',t.control_version,'state','approved');
