BEGIN
 q:=mission_generic_owner.manual_staff_template_policy_v1(p_session);
 -- Exact reviewed Revision3 source only. Preserve the sealed editor document;
 -- the returned empty director overlays no authoring field in director_context.
 IF q->'source_scope' = $source44${"PG_count":2,"PNG_count":2,"mission_id":"6d6c216a-222d-4cba-b2fc-f3e0c199c195","plan_sha256":"015787d9ac4614de079c29313b40ff39a53864292c0b5b3b446ba19e018d022c","definition_id":"6dd07cf0-0b43-4fb8-ab2e-41da8bad85a9","source_sha256":"b20f51e697b2cb4b8f11e222bf53f399eb82e6761a04c8f093b1d6a3c77e256e","plan_version_id":"f44192bc-6a83-4def-9086-bbf4089c8fe5","definition_sha256":"79f4062d34f45a593b4a8e83d46618b479d6124cd826b63dded5a968a29ea5eb"}$source44$::jsonb THEN
  SELECT * INTO STRICT b FROM mission_generic_owner.run_bindings WHERE master_session_id=p_session;
  SELECT * INTO STRICT run FROM public.mission_run_state WHERE master_session_id=p_session;
  IF b.snapshot_sha256 IS DISTINCT FROM mission_internal.fingerprint(b.snapshot)
   OR b.snapshot->>'creation_sha256' IS DISTINCT FROM mission_internal.fingerprint(b.snapshot->'creation')
   OR b.snapshot#>>'{creation,document_sha256}' IS DISTINCT FROM mission_internal.fingerprint(b.snapshot#>'{creation,document}')
   OR b.snapshot#>>'{creation,document_sha256}' IS DISTINCT FROM '1808bbdb655d0531991fbf8c5c2479016d0c6e7dda7bf64e7eab2e965c8cefe9'
   OR b.snapshot#>'{definition,scenes}' IS DISTINCT FROM b.snapshot#>'{creation,document,plan,definition,scenes}'
  THEN RAISE EXCEPTION 'MC_CONTEXT_DRIFT' USING ERRCODE='40001';END IF;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b.snapshot#>'{definition,scenes}') x WHERE x->>'step_key'=p_step)
  THEN RAISE EXCEPTION 'MC_CONTEXT_STEP_SCOPE' USING ERRCODE='22023';END IF;
  sc:=mission_generic_owner.scene(p_session,p_step);
  SELECT coalesce(jsonb_agg(jsonb_build_object(
   'trigger_key',t.value->>'trigger_key','transition_key',t.value->>'transition_key',
   'destination_step_key',tr.to_step_key,
   'scope',CASE WHEN jsonb_array_length(mission_generic_owner.scene(p_session,tr.to_step_key)->'encounters')>0
     THEN 'combat_entry' ELSE 'world_event' END) ORDER BY t.value->>'trigger_key'),'[]'::jsonb)
   INTO routes
  FROM jsonb_array_elements(sc->'triggers') t(value)
  JOIN public.mission_plan_transitions tr ON tr.plan_version_id=run.plan_version_id
   AND tr.from_step_key=p_step AND tr.transition_key=t.value->>'transition_key'
  WHERE t.value->>'source_kind'='player_choice' AND t.value->>'fact_code'='player_choice_confirmed';
  RETURN jsonb_build_object('schema_version','c1266-frozen-phase-context/1','director','{}'::jsonb,
   'route',null,'routes',routes);
 END IF;
 IF q IS NULL THEN
 IF p_session IS DISTINCT FROM '44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid THEN RETURN NULL;END IF;
 q:=mission_generic_owner.manual_staff_scope_v1(p_session);
