 SELECT jsonb_agg(jsonb_build_object('oid',pr.oid::bigint,'signature',e->>'signature','owner',pg_get_userbyid(pr.proowner),'acl',pr.proacl::text,'config',to_jsonb(pr.proconfig),'secdef',pr.prosecdef,'volatility',pr.provolatile::text,'language',lang.lanname,'source_md5',md5(pr.prosrc),'ddl_md5',md5(pg_get_functiondef(pr.oid))) ORDER BY pr.oid) INTO observed_headers FROM jsonb_array_elements(after_headers)e LEFT JOIN pg_proc pr ON pr.oid=to_regprocedure(e->>'signature') LEFT JOIN pg_language lang ON lang.oid=pr.prolang;
 IF observed_headers IS DISTINCT FROM after_headers THEN RAISE EXCEPTION 'PROOF53_RESULT_ABI_DRIFT';END IF;
 UPDATE mission_factory_owner.editor_release_readiness SET canonical_preimage=candidate_text,revision_sha256='1c96f0ff7ad03aa74d2b16a15f0f9dd5e777f8ef704c2201cc932e24debc2647',
  observed_revision_sha256='1c96f0ff7ad03aa74d2b16a15f0f9dd5e777f8ef704c2201cc932e24debc2647',client_build='mission-factory-admin/2:1c96f0ff7ad03aa74d2b16a15f0f9dd5e777f8ef704c2201cc932e24debc2647',independent_review_ref='/private/tmp/tus-c1266-recover46-20261027/output50/proof53/INDEPENDENT_MATERIAL_REVIEW.json',updated_at=clock_timestamp()
 WHERE singleton AND revision_sha256=ready.revision_sha256 AND canonical_preimage=ready.canonical_preimage;
 IF NOT FOUND THEN RAISE EXCEPTION 'PROOF53_ROOT_CAS_LOST';END IF;
 SELECT jsonb_build_object(
