  AND br.revision_sha256=br.observed_revision_sha256
  AND br.revision_sha256=encode(extensions.digest(convert_to(br.canonical_preimage,'UTF8'),'sha256'),'hex')
  AND br.canonical_preimage::jsonb#>'{config,c1266_director_incomplete_recovery}'='{"schema_version":"c1266-director-incomplete-recovery/1","enabled":true,"master_session_id":"4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4","old_work_id":"48df8786-3b66-4b44-a1bd-c92473ee5e55","old_payload_sha256":"58d06c515d3ea564a71075b69596d9823e4453688e50b64d7c061ca3f7a648ca","raw_sha256":"f2918095e64fabbd6910ec8566b2e2ccb8193be4ac5d6c0fc3fa8b1477d55c88","successor_work_id":"4fb5ea83-f90a-4b76-a6f5-722641d9da43","max_successors":1,"target_output_tokens":32000}'::jsonb) THEN
  DECLARE b50_spent numeric;b50_total numeric;b50_holds numeric;b50_global_holds numeric;b50_calls bigint;b50_counts bigint;b50_gen bigint;b50_new numeric;
  BEGIN
   SELECT coalesce(sum(coalesce(q.charged_usd,q.reserved_usd)),0),
    coalesce(sum(coalesce(q.charged_usd,q.reserved_usd)) FILTER(WHERE q.scope_id=p_session),0),count(*),
