 EXECUTE $ddl_278279$CREATE OR REPLACE FUNCTION public.mission_generic_input_count_start_v1(p_work uuid, p_lease uuid, p_payload_text text, p_payload_sha text)
 RETURNS jsonb
 LANGUAGE plpgsql
