AS $function$
DECLARE w mission_generic_owner.work_items;r mission_narrative_internal.dispatch_receipts;a mission_generic_owner.dispatch_admissions;pol mission_narrative_internal.runtime_policy;payload jsonb;projection jsonb;snap jsonb;details jsonb;old_details jsonb;measurement uuid:=gen_random_uuid();request_limit integer;count_quota jsonb;count_ticket uuid;count_staff boolean;c5_proof jsonb;campaign_budget jsonb;campaign_proof jsonb;
BEGIN
 perform mission_ai_board_owner.service_only();
