     IF r32_proof IS NOT NULL AND r32_proof->'published'='false'::jsonb
      AND r32_proof#>>'{applied,child_work_id}'=w.id::text
      AND r32_proof#>>'{applied,child_contract_sha256}'=public.combat_v2_sha256(r32_narrative)
      AND r32_proof#>>'{applied,child_payload_sha256}'=w.payload_sha256
      AND r32_proof#>'{applied,child_request}'=r32_request
      AND r32_proof#>>'{applied,adoption_release_sha256}'=r32_narrative->>'release_sha256'
      AND r32_history=r32_narrative#>'{source_attestation,execution_authority}'
      AND r32_history->>'schema_version'='c1266-work-execution-attestation/3'
      AND r32_history->>'release_sha256'=r32_narrative->>'release_sha256'
      AND r32_history->>'execution_context'=c5_proof->>'execution_context'
      AND r32_history->'admission'=c5_proof->'admission'
      AND r32_history->>'binding_sha256'=c5_proof->>'binding_sha256'
      AND r32_history->>'financial_qualification_sha256'=c5_proof->>'financial_qualification_sha256'
      AND r32_history->>'c7_budget_qualification_sha256'=c5_proof->>'c7_budget_qualification_sha256'
      AND r32_count=1 AND mission_factory_owner.keys_exact_v2(r32_owner,
       ARRAY['schema_version','actor_user_id','work_id','request_sha256','envelope_sha256','provider_timeout_ms'])
      AND r32_owner->>'schema_version'='mission-generic-async-owner/1'
      AND r32_owner->>'actor_user_id'=r32_proof->>'owner_user_id'
      AND r32_owner->>'work_id'=w.id::text
      AND r32_owner->>'request_sha256'=public.combat_v2_sha256(r32_request)
      AND r32_owner->>'envelope_sha256'=r32_receipt.envelope_sha256
      AND r32_receipt.master_session_id=w.master_session_id AND r32_receipt.authority_receipt_id=w.id
      AND r32_receipt.request_key=w.request_key
      AND r32_receipt.request_fingerprint=mission_internal.fingerprint(r32_request)
      AND r32_receipt.authority_sha256=r32_receipt.envelope_sha256
      AND r32_receipt.envelope_sha256=public.combat_v2_sha256(r32_receipt.envelope)
      AND r32_receipt.envelope->'narrative_admission'=r32_narrative
     THEN
      manual_retained_continuation:=true;
     END IF;
    END IF;
   END;
   END IF;
   IF manual_q IS NULL OR c5_proof IS NULL OR c5_proof->>'runtime_authorized' IS DISTINCT FROM 'true'
    OR c5_proof->>'execution_context' IS DISTINCT FROM 'staff_mission'
    OR c5_proof->'admission' IS DISTINCT FROM jsonb_build_object('schema_version','c1266-staff-admission-authority/3','kind','staff_finite','resource_scope','staff_simulation','finite_admission_sha256',public.combat_v2_sha256(manual_q),'admission_id',manual_q->>'start_receipt_id','location_id',manual_q->>'location_id')
    OR a.c7_budget_qualification_sha256 IS DISTINCT FROM manual_q->>'budget_qualification_sha256'
    OR manual_sealed IS NULL OR manual_sealed->>'schema_version' IS DISTINCT FROM 'c1266-work-execution-attestation/3'
