        AND ra.details->>'fixed_runtime_sha256'='2f2f9f992b5d82ffc28888bf7338708aac0166c6e850225953112895a6743eca')) THEN RETURN true;END IF;
  END IF;
  IF source_row.superseded_reason='staff_failed_director_validation_retry' AND EXISTS(SELECT 1 FROM mission_generic_owner.work_items cp24_work
 JOIN mission_generic_owner.unified_source_windows cp24_source ON cp24_source.id=cp24_work.authority_receipt_id
 JOIN mission_narrative_internal.dispatch_receipts cp24_dispatch ON cp24_dispatch.id=cp24_work.dispatch_receipt_id
