BEGIN
 IF p_work IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO w FROM mission_generic_owner.work_items WHERE id=p_work;
 IF NOT FOUND OR w.kind IS DISTINCT FROM 'narration' OR w.payload->>'schema_version' IS DISTINCT FROM 'mission-generic-narration/4'
 OR w.payload->>'mode' IS DISTINCT FROM 'unified' OR w.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.payload)
