   OR cfg->>'master_session_id' IS DISTINCT FROM w.master_session_id::text OR cfg->>'old_work_id' IS DISTINCT FROM w.id::text
   OR cfg->>'payload_sha256' IS DISTINCT FROM w.payload_sha256 OR cfg->'max_successors' IS DISTINCT FROM '1'::jsonb
  THEN RETURN NULL;END IF;
 END IF;
 child_id:=mission_ai_service_owner.uuid5(w.id,'mission-writer-count-reissue/1:work');
 child_event:=mission_ai_service_owner.uuid5(w.id,'mission-writer-count-reissue/1:event');
 child_key:=mission_ai_service_owner.uuid5(w.id,'mission-writer-count-reissue/1:request');
 SELECT * INTO b FROM mission_generic_owner.unified_batches WHERE id=w.authority_receipt_id AND master_session_id=w.master_session_id;
 SELECT * INTO dw FROM mission_generic_owner.work_items WHERE id=b.decision_work_id;
 SELECT * INTO sw FROM mission_generic_owner.unified_source_windows WHERE id=b.source_window_id AND work_id=dw.id;
 IF b.id IS NULL OR b.retired_at IS NOT NULL OR b.payload IS DISTINCT FROM w.payload OR b.payload_sha256 IS DISTINCT FROM w.payload_sha256
 OR b.decision_sha256 IS DISTINCT FROM public.combat_v2_sha256(b.decision)
 OR b.step_key IS DISTINCT FROM w.step_key OR b.run_control_version IS DISTINCT FROM w.run_control_version
 OR dw.id IS NULL OR dw.kind IS DISTINCT FROM 'director' OR dw.state IS DISTINCT FROM 'completed'
 OR dw.finalized_at IS NULL OR dw.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(dw.payload)
 OR dw.result->'ok' IS DISTINCT FROM 'true'::jsonb
 OR NOT(dw.result_sha256=public.combat_v2_sha256(dw.result) OR EXISTS(
  SELECT 1 FROM mission_narrative_internal.dispatch_audit fin WHERE fin.receipt_id=dw.dispatch_receipt_id AND fin.event_code='generic_finalized'
   AND fin.details->>'work_id'=dw.id::text AND fin.details->>'receipt_id'=dw.receipt_id::text
   AND fin.details->>'state'='completed' AND fin.details->>'result_sha256'=dw.result_sha256
   AND fin.details->>'result_jsonb_sha256'=public.combat_v2_sha256(dw.result)))
 OR dw.master_session_id IS DISTINCT FROM w.master_session_id OR sw.id IS NULL
