 OR (w.payload->'director_proposal') IS DISTINCT FROM (b.decision-'role_disposition'-'current_projection')
 OR w.payload->'role_disposition' IS DISTINCT FROM b.decision->'role_disposition'
 OR w.payload->'current_projection' IS DISTINCT FROM b.decision->'current_projection'
 OR w.payload->'role_interpretation' IS DISTINCT FROM b.decision->'role_interpretation'
