 SELECT count(*) INTO n FROM mission_narrative_internal.dispatch_audit WHERE receipt_id=w.dispatch_receipt_id AND event_code='staff_writer_count_overflow_reissued_v1';
 IF n>1 THEN RETURN NULL;END IF;
 IF n=0 AND mission_generic_owner.c1266_role_work_attest_v2(b.writer_work_id) IS NULL THEN RETURN NULL;END IF;
 IF n=1 THEN
  SELECT * INTO au FROM mission_narrative_internal.dispatch_audit WHERE receipt_id=w.dispatch_receipt_id AND event_code='staff_writer_count_overflow_reissued_v1';
  IF NOT mission_factory_owner.keys_exact_v2(au.details,ARRAY['schema_version','master_session_id','old_work_id','old_receipt_id','old_result_sha256','old_payload_sha256','old_dispatch_sha256','batch_id','batch_decision_sha256','decision_work_id','decision_result_sha256','decision_result_jsonb_sha256','source_window_id','source_window_sha256','role_ids_sha256','owner_user_id','successor_work_id','successor_event_id','successor_request_key','count_terminal_proof','count_terminal_proof_sha256','role_attestation','role_attestation_sha256','fixed_release_sha256'])
  OR au.details->>'schema_version' IS DISTINCT FROM 'mission-writer-count-reissue-audit/1'
  OR (au.details->>'master_session_id',au.details->>'old_work_id',au.details->>'old_receipt_id',au.details->>'old_result_sha256',au.details->>'old_payload_sha256')
    IS DISTINCT FROM (w.master_session_id::text,w.id::text,w.receipt_id::text,w.result_sha256,w.payload_sha256)
  OR (au.details->>'batch_id',au.details->>'batch_decision_sha256',au.details->>'decision_work_id',au.details->>'decision_result_sha256',au.details->>'decision_result_jsonb_sha256',au.details->>'source_window_id',au.details->>'source_window_sha256',au.details->>'role_ids_sha256')
    IS DISTINCT FROM (b.id::text,b.decision_sha256,dw.id::text,dw.result_sha256,public.combat_v2_sha256(dw.result),sw.id::text,sw.source_sha256,public.combat_v2_sha256(to_jsonb(sw.role_ids)))
  OR (au.details->>'successor_work_id',au.details->>'successor_event_id',au.details->>'successor_request_key')
    IS DISTINCT FROM (child_id::text,child_event::text,child_key::text)
  OR w.state IS DISTINCT FROM 'failed' OR w.finalized_at IS NULL OR w.receipt_id IS NULL
  OR w.result_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.result)
  OR w.result->>'schema_version' IS DISTINCT FROM 'c1266-count-terminal-failure/1'
  OR w.result->>'failure_code' IS DISTINCT FROM 'MISSION_INPUT_COUNT_OVERFLOW'
  OR au.details->>'count_terminal_proof_sha256' IS DISTINCT FROM public.combat_v2_sha256(au.details->'count_terminal_proof')
  OR au.details->>'role_attestation_sha256' IS DISTINCT FROM public.combat_v2_sha256(au.details->'role_attestation')
  OR (au.details#>>'{role_attestation,work_id}',au.details#>>'{role_attestation,decision_work_id}',au.details#>>'{role_attestation,source_window_id}',au.details#>>'{role_attestation,source_revision}')
    IS DISTINCT FROM (w.id::text,dw.id::text,sw.id::text,sw.context->>'source_revision')
  OR au.details#>'{role_attestation,role_roster}' IS DISTINCT FROM dw.payload->'role_roster'
  THEN RETURN NULL;END IF;
  cp:=au.details->'count_terminal_proof';
  IF cp->>'schema_version' IS DISTINCT FROM 'c1266-count-terminal-proof/1'
  OR (cp->>'work_id',cp->>'master_session_id',cp->>'event_id',cp->>'request_key',cp->>'dispatch_receipt_id',cp->>'failure_code')
    IS DISTINCT FROM (w.id::text,w.master_session_id::text,w.event_id::text,w.request_key::text,w.dispatch_receipt_id::text,'MISSION_INPUT_COUNT_OVERFLOW')
  OR cp->>'count_ticket' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  THEN RETURN NULL;END IF;
  SELECT to_jsonb(x) INTO ticket FROM staff_ai_quota_private.calls x WHERE id=(cp->>'count_ticket')::uuid;
  SELECT * INTO dr FROM mission_narrative_internal.dispatch_receipts WHERE id=w.dispatch_receipt_id;
  IF ticket IS NULL OR cp->>'count_ticket_sha256' IS DISTINCT FROM public.combat_v2_sha256(ticket)
