  SELECT * INTO ch FROM mission_generic_owner.work_items WHERE id=child_id;
  IF ch.id IS NULL OR b.writer_work_id IS DISTINCT FROM ch.id OR ch.master_session_id IS DISTINCT FROM w.master_session_id
