  OR ch.event_id IS DISTINCT FROM child_event OR ch.request_key IS DISTINCT FROM child_key
  OR ch.dedupe_key IS DISTINCT FROM 'writer-count-reissue/1:'||w.id::text
  OR ch.step_key IS DISTINCT FROM w.step_key OR ch.run_control_version IS DISTINCT FROM w.run_control_version
  OR ch.definition_sha256 IS DISTINCT FROM w.definition_sha256 OR ch.payload IS DISTINCT FROM w.payload OR ch.payload_sha256 IS DISTINCT FROM w.payload_sha256
  THEN RETURN NULL;END IF;
  owner_id:=(au.details->>'owner_user_id')::uuid;lineage:=true;
  published:=b.state='published' AND b.published_at IS NOT NULL AND ch.state='completed' AND ch.finalized_at IS NOT NULL
   AND ch.receipt_id IS NOT NULL AND ch.result->'ok'='true'::jsonb AND ch.message_id=b.message_id AND b.message_id IS NOT NULL
   AND(ch.result_sha256=public.combat_v2_sha256(ch.result) OR EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit cf
     WHERE cf.receipt_id=ch.dispatch_receipt_id AND cf.event_code='generic_finalized' AND cf.details->>'work_id'=ch.id::text
      AND cf.details->>'receipt_id'=ch.receipt_id::text AND cf.details->>'state'='completed'
      AND cf.details->>'result_sha256'=ch.result_sha256 AND cf.details->>'result_jsonb_sha256'=public.combat_v2_sha256(ch.result)))
   AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_segment_publications_v4 p JOIN public.messages m ON m.id=p.message_id
     WHERE p.work_id=ch.id AND p.batch_id=b.id AND p.message_id=b.message_id AND sw.consumed_message_id=m.id
      AND p.source_revision=sw.context->>'source_revision' AND m.kind='fato' AND m.character_id IS NULL
      AND m.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND m.recipient_user IS NULL AND m.body=ch.result->>'text'
