   OR mission_generic_owner.role_source_revision_v1(w.master_session_id) IS DISTINCT FROM sw.context->>'source_revision'
   OR (NOT lineage AND b.writer_work_id IS DISTINCT FROM w.id) THEN RETURN NULL;END IF;
 END IF;
 req:=jsonb_build_object('schema_version','mission-generic-request/1','master_session_id',w.master_session_id,
  'event_id',child_event,'request_key',child_key,'expected_revision',w.revision);
 RETURN jsonb_build_object('schema_version','mission-writer-count-reissue-proof/1','master_session_id',w.master_session_id,
