CREATE OR REPLACE FUNCTION mission_generic_owner.writer_count_reissue_proof_v1(p_work uuid,p_user uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE w mission_generic_owner.work_items;ch mission_generic_owner.work_items;dw mission_generic_owner.work_items;
 b mission_generic_owner.unified_batches;sw mission_generic_owner.unified_source_windows;rs public.mission_run_state;
 au mission_narrative_internal.dispatch_audit;dr mission_narrative_internal.dispatch_receipts;
 cp jsonb;cfg jsonb;owner_id uuid;child_id uuid;child_event uuid;child_key uuid;ticket jsonb;
 n integer;published boolean:=false;req jsonb;lineage boolean:=false;
BEGIN
 IF p_work IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO w FROM mission_generic_owner.work_items WHERE id=p_work;
 IF NOT FOUND OR w.kind IS DISTINCT FROM 'narration' OR w.payload->>'schema_version' IS DISTINCT FROM 'mission-generic-narration/4'
 OR w.payload->>'mode' IS DISTINCT FROM 'unified' OR w.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.payload)
 OR w.message_id IS NOT NULL OR w.authorization_id IS NOT NULL OR w.dispatch_id IS NOT NULL
 OR w.state NOT IN('claimed','failed') THEN RETURN NULL;END IF;
 IF p_user IS NOT NULL THEN
  SELECT rr.canonical_preimage::jsonb#>'{config,c1266_writer_count_reissue46}' INTO cfg
   FROM mission_factory_owner.editor_release_readiness rr WHERE singleton AND state='enabled' AND scope='staff' AND revision_sha256=observed_revision_sha256;
  IF NOT mission_factory_owner.keys_exact_v2(cfg,ARRAY['schema_version','enabled','ordinary_public_enabled','master_session_id','old_work_id','payload_sha256','max_successors'])
   OR cfg->>'schema_version' IS DISTINCT FROM 'mission-writer-count-reissue-policy/1'
   OR cfg->'enabled' IS DISTINCT FROM 'true'::jsonb OR cfg->'ordinary_public_enabled' IS DISTINCT FROM 'false'::jsonb
   OR cfg->>'master_session_id' IS DISTINCT FROM w.master_session_id::text OR cfg->>'old_work_id' IS DISTINCT FROM w.id::text
   OR cfg->>'payload_sha256' IS DISTINCT FROM w.payload_sha256 OR cfg->'max_successors' IS DISTINCT FROM '1'::jsonb
  THEN RETURN NULL;END IF;
 END IF;
 child_id:=mission_ai_service_owner.uuid5(w.id,'mission-writer-count-reissue/1:work');
 child_event:=mission_ai_service_owner.uuid5(w.id,'mission-writer-count-reissue/1:event');
 child_key:=mission_ai_service_owner.uuid5(w.id,'mission-writer-count-reissue/1:request');
 SELECT * INTO b FROM mission_generic_owner.unified_batches WHERE id=w.authority_receipt_id AND master_session_id=w.master_session_id;
 SELECT * INTO dw FROM mission_generic_owner.work_items WHERE id=b.decision_work_id;
 SELECT * INTO sw FROM mission_generic_owner.unified_source_windows WHERE id=b.source_window_id AND work_id=dw.id;
 IF b.id IS NULL OR b.retired_at IS NOT NULL OR b.payload IS DISTINCT FROM w.payload OR b.payload_sha256 IS DISTINCT FROM w.payload_sha256
 OR b.decision_sha256 IS DISTINCT FROM public.combat_v2_sha256(b.decision)
 OR b.step_key IS DISTINCT FROM w.step_key OR b.run_control_version IS DISTINCT FROM w.run_control_version
 OR dw.id IS NULL OR dw.kind IS DISTINCT FROM 'director' OR dw.state IS DISTINCT FROM 'completed'
 OR dw.finalized_at IS NULL OR dw.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(dw.payload)
 OR dw.result->'ok' IS DISTINCT FROM 'true'::jsonb
 OR NOT(dw.result_sha256=public.combat_v2_sha256(dw.result) OR EXISTS(
  SELECT 1 FROM mission_narrative_internal.dispatch_audit fin WHERE fin.receipt_id=dw.dispatch_receipt_id AND fin.event_code='generic_finalized'
   AND fin.details->>'work_id'=dw.id::text AND fin.details->>'receipt_id'=dw.receipt_id::text
   AND fin.details->>'state'='completed' AND fin.details->>'result_sha256'=dw.result_sha256
   AND fin.details->>'result_jsonb_sha256'=public.combat_v2_sha256(dw.result)))
 OR dw.master_session_id IS DISTINCT FROM w.master_session_id OR sw.id IS NULL
 OR sw.master_session_id IS DISTINCT FROM w.master_session_id OR sw.source_sha256 IS DISTINCT FROM dw.payload_sha256
 OR sw.context IS DISTINCT FROM dw.payload->'context' OR sw.definition_sha256 IS DISTINCT FROM w.definition_sha256
 OR w.payload->>'source_revision' IS DISTINCT FROM sw.context->>'source_revision'
 OR (w.payload->'director_proposal') IS DISTINCT FROM (b.decision-'role_disposition'-'current_projection')
 OR w.payload->'role_disposition' IS DISTINCT FROM b.decision->'role_disposition'
 OR w.payload->'current_projection' IS DISTINCT FROM b.decision->'current_projection'
 OR w.payload->'role_interpretation' IS DISTINCT FROM b.decision->'role_interpretation'
 OR b.writer_work_id IS NULL OR b.writer_work_id NOT IN(w.id,child_id)
 THEN RETURN NULL;END IF;
 SELECT count(*) INTO n FROM mission_narrative_internal.dispatch_audit WHERE receipt_id=w.dispatch_receipt_id AND event_code='staff_writer_count_overflow_reissued_v1';
 IF n>1 THEN RETURN NULL;END IF;
 IF n=0 AND mission_generic_owner.c1266_role_work_attest_v2(b.writer_work_id) IS NULL THEN RETURN NULL;END IF;
 IF n=1 THEN
  SELECT * INTO au FROM mission_narrative_internal.dispatch_audit WHERE receipt_id=w.dispatch_receipt_id AND event_code='staff_writer_count_overflow_reissued_v1';
  IF NOT mission_factory_owner.keys_exact_v2(au.details,ARRAY['schema_version','master_session_id','old_work_id','old_receipt_id','old_result_sha256','old_payload_sha256','old_dispatch_sha256','batch_id','batch_decision_sha256','decision_work_id','decision_result_sha256','decision_result_jsonb_sha256','source_window_id','source_window_sha256','role_ids_sha256','owner_user_id','successor_work_id','successor_event_id','successor_request_key','count_terminal_proof','count_terminal_proof_sha256','role_attestation','role_attestation_sha256','fixed_release_sha256'])
  OR au.details->>'schema_version' IS DISTINCT FROM 'mission-writer-count-reissue-audit/1'
  OR (au.details->>'master_session_id',au.details->>'old_work_id',au.details->>'old_receipt_id',au.details->>'old_result_sha256',au.details->>'old_payload_sha256')
    IS DISTINCT FROM (w.master_session_id::text,w.id::text,w.receipt_id::text,w.result_sha256,w.payload_sha256)
  OR (au.details->>'batch_id',au.details->>'batch_decision_sha256',au.details->>'decision_work_id',au.details->>'decision_result_sha256',au.details->>'decision_result_jsonb_sha256',au.details->>'source_window_id',au.details->>'source_window_sha256',au.details->>'role_ids_sha256')
    IS DISTINCT FROM (b.id::text,b.decision_sha256,dw.id::text,dw.result_sha256,public.combat_v2_sha256(dw.result),sw.id::text,sw.source_sha256,public.combat_v2_sha256(to_jsonb(sw.role_ids)))
  OR (au.details->>'successor_work_id',au.details->>'successor_event_id',au.details->>'successor_request_key')
    IS DISTINCT FROM (child_id::text,child_event::text,child_key::text)
  OR w.state IS DISTINCT FROM 'failed' OR w.finalized_at IS NULL OR w.receipt_id IS NULL
  OR w.result_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.result)
  OR w.result->>'schema_version' IS DISTINCT FROM 'c1266-count-terminal-failure/1'
  OR w.result->>'failure_code' IS DISTINCT FROM 'MISSION_INPUT_COUNT_OVERFLOW'
  OR au.details->>'count_terminal_proof_sha256' IS DISTINCT FROM public.combat_v2_sha256(au.details->'count_terminal_proof')
  OR au.details->>'role_attestation_sha256' IS DISTINCT FROM public.combat_v2_sha256(au.details->'role_attestation')
  OR (au.details#>>'{role_attestation,work_id}',au.details#>>'{role_attestation,decision_work_id}',au.details#>>'{role_attestation,source_window_id}',au.details#>>'{role_attestation,source_revision}')
    IS DISTINCT FROM (w.id::text,dw.id::text,sw.id::text,sw.context->>'source_revision')
  OR au.details#>'{role_attestation,role_roster}' IS DISTINCT FROM dw.payload->'role_roster'
  THEN RETURN NULL;END IF;
  cp:=au.details->'count_terminal_proof';
  IF cp->>'schema_version' IS DISTINCT FROM 'c1266-count-terminal-proof/1'
  OR (cp->>'work_id',cp->>'master_session_id',cp->>'event_id',cp->>'request_key',cp->>'dispatch_receipt_id',cp->>'failure_code')
    IS DISTINCT FROM (w.id::text,w.master_session_id::text,w.event_id::text,w.request_key::text,w.dispatch_receipt_id::text,'MISSION_INPUT_COUNT_OVERFLOW')
  OR cp->>'count_ticket' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  THEN RETURN NULL;END IF;
  SELECT to_jsonb(x) INTO ticket FROM staff_ai_quota_private.calls x WHERE id=(cp->>'count_ticket')::uuid;
  SELECT * INTO dr FROM mission_narrative_internal.dispatch_receipts WHERE id=w.dispatch_receipt_id;
  IF ticket IS NULL OR cp->>'count_ticket_sha256' IS DISTINCT FROM public.combat_v2_sha256(ticket)
  OR au.details->>'old_dispatch_sha256' IS DISTINCT FROM public.combat_v2_sha256(to_jsonb(dr))
  OR NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit x WHERE x.receipt_id=w.dispatch_receipt_id AND x.event_code='c1266_count_terminal'
    AND x.details->>'work_id'=w.id::text AND x.details->>'receipt_id'=w.receipt_id::text AND x.details->>'result_sha256'=w.result_sha256
    AND x.details->>'count_ticket_sha256'=cp->>'count_ticket_sha256')
  THEN RETURN NULL;END IF;
  SELECT * INTO ch FROM mission_generic_owner.work_items WHERE id=child_id;
  IF ch.id IS NULL OR b.writer_work_id IS DISTINCT FROM ch.id OR ch.master_session_id IS DISTINCT FROM w.master_session_id
  OR ch.kind IS DISTINCT FROM 'narration' OR ch.authority_receipt_id IS DISTINCT FROM b.id
  OR ch.event_id IS DISTINCT FROM child_event OR ch.request_key IS DISTINCT FROM child_key
  OR ch.dedupe_key IS DISTINCT FROM 'writer-count-reissue/1:'||w.id::text
  OR ch.step_key IS DISTINCT FROM w.step_key OR ch.run_control_version IS DISTINCT FROM w.run_control_version
  OR ch.definition_sha256 IS DISTINCT FROM w.definition_sha256 OR ch.payload IS DISTINCT FROM w.payload OR ch.payload_sha256 IS DISTINCT FROM w.payload_sha256
  THEN RETURN NULL;END IF;
  owner_id:=(au.details->>'owner_user_id')::uuid;lineage:=true;
  published:=b.state='published' AND b.published_at IS NOT NULL AND ch.state='completed' AND ch.finalized_at IS NOT NULL
   AND ch.receipt_id IS NOT NULL AND ch.result->'ok'='true'::jsonb AND ch.message_id=b.message_id AND b.message_id IS NOT NULL
   AND(ch.result_sha256=public.combat_v2_sha256(ch.result) OR EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit cf
     WHERE cf.receipt_id=ch.dispatch_receipt_id AND cf.event_code='generic_finalized' AND cf.details->>'work_id'=ch.id::text
      AND cf.details->>'receipt_id'=ch.receipt_id::text AND cf.details->>'state'='completed'
      AND cf.details->>'result_sha256'=ch.result_sha256 AND cf.details->>'result_jsonb_sha256'=public.combat_v2_sha256(ch.result)))
   AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_segment_publications_v4 p JOIN public.messages m ON m.id=p.message_id
     WHERE p.work_id=ch.id AND p.batch_id=b.id AND p.message_id=b.message_id AND sw.consumed_message_id=m.id
      AND p.source_revision=sw.context->>'source_revision' AND m.kind='fato' AND m.character_id IS NULL
      AND m.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND m.recipient_user IS NULL AND m.body=ch.result->>'text'
      AND encode(extensions.digest(convert_to(m.body,'UTF8'),'sha256'),'hex')=p.final_text_sha256);
  IF p_user IS NULL THEN RETURN jsonb_build_object('schema_version','mission-writer-count-reissue-proof/1','master_session_id',w.master_session_id,'old_work_id',w.id,
    'successor_work_id',child_id,'count_terminal_proof',cp,'audit_sha256',public.combat_v2_sha256(au.details),'published',published);END IF;
 ELSE
  IF p_user IS NULL THEN RETURN NULL;END IF;
  cp:=mission_generic_owner.c1266_count_terminal_proof_v1(w.id,w.state='failed');
  IF cp IS NULL OR cp->>'failure_code' IS DISTINCT FROM 'MISSION_INPUT_COUNT_OVERFLOW' THEN RETURN NULL;END IF;
  SELECT (a.details->>'actor_user_id')::uuid INTO owner_id FROM mission_narrative_internal.dispatch_audit a
   WHERE a.receipt_id=w.dispatch_receipt_id AND a.event_code='c1266_async_owner_v1' AND a.details->>'work_id'=w.id::text;
 END IF;
 IF owner_id IS NULL OR owner_id IS DISTINCT FROM p_user THEN RETURN NULL;END IF;
 IF mission_generic_owner.manual_staff_scope_v1(w.master_session_id) IS NULL
 OR NOT EXISTS(SELECT 1 FROM public.master_v2_sessions m JOIN public.locations l ON l.id=m.location_id
   JOIN public.master_v2_participants mp ON mp.session_id=m.id AND mp.user_id_snapshot=p_user AND mp.left_at IS NULL AND mp.engagement_state='attivo'
   JOIN public.profiles pr ON pr.id=p_user AND pr.role IN('admin','master')
   WHERE m.id=w.master_session_id AND m.owner_kind='ai_service' AND m.master_user IS NULL AND m.stato='in_corso'
    AND m.closed_at IS NULL AND m.suspended_at IS NULL AND l.id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND l.is_test AND l.is_active)
 THEN RETURN NULL;END IF;
 IF NOT published THEN
  SELECT * INTO rs FROM public.mission_run_state WHERE master_session_id=w.master_session_id;
  IF rs.current_step_key IS DISTINCT FROM w.step_key OR rs.control_version IS DISTINCT FROM w.run_control_version
   OR rs.run_phase IS DISTINCT FROM 'in_corso' OR b.state IS DISTINCT FROM 'ready' OR b.message_id IS NOT NULL
   OR sw.superseded_at IS NOT NULL OR sw.consumed_message_id IS NOT NULL
   OR mission_generic_owner.role_source_revision_v1(w.master_session_id) IS DISTINCT FROM sw.context->>'source_revision'
   OR (NOT lineage AND b.writer_work_id IS DISTINCT FROM w.id) THEN RETURN NULL;END IF;
 END IF;
 req:=jsonb_build_object('schema_version','mission-generic-request/1','master_session_id',w.master_session_id,
  'event_id',child_event,'request_key',child_key,'expected_revision',w.revision);
 RETURN jsonb_build_object('schema_version','mission-writer-count-reissue-proof/1','master_session_id',w.master_session_id,
  'old_work_id',w.id,'batch_id',b.id,'decision_work_id',dw.id,'source_window_id',sw.id,'payload_sha256',w.payload_sha256,
  'count_terminal_proof',cp,'owner_user_id',owner_id,'successor_work_id',CASE WHEN lineage THEN child_id ELSE NULL END,
  'successor_request',req,'can_reissue',NOT lineage,'published',published,'audit_sha256',CASE WHEN lineage THEN public.combat_v2_sha256(au.details) ELSE NULL END);
END $function$;
