 VALUES(w.dispatch_receipt_id,'staff_writer_count_overflow_reissued_v1',details);
 UPDATE mission_generic_owner.unified_batches SET writer_work_id=child_id
 WHERE id=b.id AND writer_work_id=w.id AND state='ready' AND message_id IS NULL AND payload=w.payload AND payload_sha256=w.payload_sha256
  AND decision_work_id=dw.id AND decision_sha256=b.decision_sha256;
 IF NOT FOUND OR mission_generic_owner.writer_count_reissue_proof_v1(w.id,NULL) IS NULL THEN
