[{"oid":652749,"signature":"mission_generic_owner.writer_count_reissue_proof_v1(uuid,uuid)","owner":"postgres","acl":"{postgres=X/postgres}","config":["search_path="""],"secdef":true,"volatility":"s","language":"plpgsql","source_md5":"bee83eb6b5f164229c942c6bc29c23b0","ddl_md5":"438a1b4ec0b468c666c903cb0f537ff9","ddl":"CREATE OR REPLACE FUNCTION mission_generic_owner.writer_count_reissue_proof_v1(p_work uuid, p_user uuid)
