  OR w.result_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.result)
  OR w.result->>'schema_version' IS DISTINCT FROM 'c1266-count-terminal-failure/1'
  OR w.result->>'failure_code' IS DISTINCT FROM 'MISSION_INPUT_COUNT_OVERFLOW'
