          }
          if(!exact(saved,['schema_version','work_id','dispatch_id','output_receipt_id','raw_sha256'])
            ||saved.schema_version!=='mission-provider-output-receipt/1'||saved.work_id!==work.work_id
            ||saved.dispatch_id!==dispatch.dispatch_id||!uuid(saved.output_receipt_id)||saved.raw_sha256!==rawHash)
            throw Error('MISSION_PROVIDER_OUTPUT_RECEIPT_INVALID');
          outputReceipt=Object.freeze(saved);
        }}:{})});
    });
    if(retainsProviderOutput(work)&&outputReceipt===null)throw Error('MISSION_PROVIDER_OUTPUT_RETENTION_REQUIRED');
    if (received.status !== 'completed') throw Error('MISSION_PROVIDER_INCOMPLETE');
    if (work.kind === 'choice') {
      if(isPeacefulChoice(work)){
        const {peaceful_exit,...choice}=received.realization??{};
        const profile_audit=choiceProfileAudit(choice,context);
        const command=choiceCommand(choice,context,work.limits);
        result={ok:true,command,text:null,profile_audit,
          peaceful_exit:peacefulProposal(peaceful_exit,context,work,command)};
      }else{
        const profile_audit=choiceProfileAudit(received.realization,context);
        result={ok:true,command:choiceCommand(received.realization,context,work.limits),text:null,profile_audit};
      }
    } else if(work.kind==='director'){
      result=await normalizedDirectorResult(work,received.realization);
    } else if(freeNarrative(work)){
      if(!exact(received.realization,['testo'])||!text(received.realization.testo))throw Error('MISSION_FREE_PROSE_FORMAT_INVALID');
      const body=received.realization.testo;
      if([...body].length>work.limits.transport_max_chars)throw Error('MISSION_FREE_PROSE_TRANSPORT_INVALID');
      const inspected=inspectNarrative(body,{providerComplete:true,transportMaxChars:work.limits.transport_max_chars,preserveParagraphs:true});
      const advisories=[...inspected.codes,...inspected.advisories,'profile_audit_not_generated_NOT_QUALIFIED'];
      try{rejectCurrentRoleEcho(body,work);}catch{advisories.push('MISSION_NARRATIVE_ROLE_ECHO');}
      if(copiedOldPassage(body,previousFati(work.payload,work)))advisories.push('MISSION_NARRATIVE_LITERAL_REPETITION');
      // Private diagnostics do not veto prose. The DB carries prior memory and composes canonical mechanics.
      result={ok:true,text:body,segments:null,command:null,profile_audit:null,continuity_draft:null,history_anchor:null,failure_codes:[],advisories};
    } else if(work.payload?.schema_version==='mission-generic-narration/4'){
      const profile_audit=checkedNarrativeAudit(received.realization?.profile_audit,work);
      const checked=validateSegmentedFato(received.realization,work);
      rejectCurrentRoleEcho(checked.proseText,work);
      const ok=checked.failureCodes.length===0;
      let continuity_draft=null,history_anchor=null;
      if(hasContinuity(work)&&ok){
        const mem=received.realization.memoria;
        if(!memoryShape(mem))throw Error('MISSION_CONTINUITY_OUTPUT_INVALID');
        narrativeMemoryFromPayload(work.payload,work);
        if(copiedOldPassage(checked.proseText,previousFati(work.payload,work)))
          throw Error('MISSION_NARRATIVE_LITERAL_REPETITION');
        const history=historyDigestFromPayload(work.payload,work);
        continuity_draft={state:mem.state,known:mem.known,open:mem.open,used:mem.used};
        history_anchor={chain_sha256:history.chain_sha256,count:history.count};
      }
      result={ok,text:null,segments:ok?checked.segments:null,command:null,profile_audit,
        continuity_draft,history_anchor,failure_codes:checked.failureCodes,advisories:checked.advisories};
    } else {
      if (!exact(received.realization,['testo','profile_audit',...(hasContinuity(work)?['memoria']:[])])) throw Error('MISSION_NARRATIVE_FORMAT_INVALID');
      const profile_audit=checkedNarrativeAudit(received.realization.profile_audit,work);
      const checked=inspectNarrative(received.realization.testo,{providerComplete:true,transportMaxChars:work.limits.transport_max_chars,preserveParagraphs:isCinematic(work)});
      const editorialAdvisories=staffNativeStyleDiagnostics(work)?[]:null;
      rejectCurrentRoleEcho(checked.text,work,editorialAdvisories);
      const failureCodes=checked.chars<500?[...checked.codes,'below_required_minimum']:checked.codes;
      const continuity=hasContinuity(work)&&failureCodes.length===0
        ?await sealMemory(received.realization.memoria,work,checked.text,editorialAdvisories):null;
      result={ok:failureCodes.length===0,text:failureCodes.length===0?checked.text:null,command:null,profile_audit,
        ...(hasContinuity(work)?{continuity}:{}),failure_codes:failureCodes,
        advisories:editorialAdvisories===null?checked.advisories:[...checked.advisories,...editorialAdvisories]};
    }
  } catch(error) {
    received=received??error?.provider_result;
    const failure=typeof error?.message==='string' ? error.message : '';
    const terminal=received?.terminal===true&&['completed','incomplete','failed','cancelled'].includes(received.status);
    outcomeUncertain=calls===0
      ?campaignNoHttpProof===null&&(failure==='MISSION_DISPATCH_TIMEOUT'||!received)
      :campaignNoHttpProof===null&&!terminal;
    if(calls===1&&outcomeUncertain)received=undefined;
    const safeStaffCode=isCinematic(work)&&/^(?:MISSION_[A-Z0-9_]+|PROVIDER_(?:HTTP|SCHEMA))$/.test(failure)
      ? failure : 'provider_or_validation_failed';
    result={ok:false,text:null,command:null,profile_audit:null,
      ...(work.payload?.schema_version==='mission-generic-narration/4'
        ?{segments:null,continuity_draft:null,history_anchor:null}:{}),
      failure_codes:[calls===0
        ?failure==='MISSION_DISPATCH_TIMEOUT'?'provider_outcome_unknown':safeStaffCode
        :outcomeUncertain?'provider_outcome_unknown':(['MISSION_PROVIDER_INCOMPLETE','MISSION_PROVIDER_FAILED','MISSION_PROVIDER_CANCELLED','PROVIDER_SCHEMA'].includes(failure)?failure:safeStaffCode)]};
    const providerDiagnostic=calls===1&&campaignNoHttpProof===null?providerDiagnostic43(error?.provider_diagnostic):null;
    if(providerDiagnostic!==null)result.provider_diagnostic=providerDiagnostic;
    const progressBasisDiagnostic=c1266ProgressBasisDiagnostic(error,work);
    if(progressBasisDiagnostic!==null)result.progress_basis_diagnostic=progressBasisDiagnostic;
  }
  if(work.kind==='director'&&!Object.hasOwn(result,'decision'))result.decision=null;
  const usage=usageOf(received);
  // profile_audit remains in the owner-only work result; finalize publishes only text/command/decision.
  const segmentedResult=work.kind==='narration'&&work.payload?.schema_version==='mission-generic-narration/4';
  let delivery={schema_version:segmentedResult?'mission-generic-result/2':'mission-generic-result/1',work_id:work.work_id,master_session_id:work.master_session_id,
    event_id:work.event_id,request_key:request.request_key,revision:work.revision,authority_receipt_id:work.authority_receipt_id,
    definition_sha256:work.definition_sha256,payload_sha256:work.payload_sha256,kind:work.kind,
    runtime_version:segmentedResult?SEGMENTED_RUNTIME_VERSION:RUNTIME_VERSION,editorial_version:isCinematic(work)?STAFF_EDITORIAL_VERSION:EDITORIAL_VERSION,profile_audit_version:PROFILE_AUDIT_VERSION,choice_version:work.kind==='choice'?CHOICE_VERSION:null,
    authorization_id:permission.authorization_id,dispatch_id:dispatch.dispatch_id,provider_calls:calls,model:PROVIDER.model,
    usage,usage_unknown:usage===null,provider_status:received?.status??null,outcome_uncertain:outcomeUncertain,
    raw_sha256:typeof received?.raw_output==='string'?await digest(received.raw_output):null,
    request_sha256:await digest(JSON.stringify(providerRequest.payload)),...result,...(retainsProviderOutput(work)?{output_receipt_id:outputReceipt?.output_receipt_id??null}: {})};
  // Omit optional diagnostics before the unchanged delivery cap/fallback path.
  if(Object.hasOwn(delivery,'provider_diagnostic')&&bytes(delivery)>65536)
    delete delivery.provider_diagnostic;
  if(Object.hasOwn(delivery,'progress_basis_diagnostic')&&bytes(delivery)>65536)
    delete delivery.progress_basis_diagnostic;
  if(bytes(delivery)>65536){
    delivery={...delivery,ok:false,text:null,command:null,decision:null,peaceful_exit:null,profile_audit:null,continuity:null,progression_audit:null,
      ...(segmentedResult?{segments:null,continuity_draft:null,history_anchor:null}:{}),failure_codes:['provider_output_too_large']};
  }
  if(bytes(delivery)>65536)throw Error('MISSION_DELIVERY_OVERFLOW');
  const resultSha=await digest(canonical(delivery));
  // Anche se il provider ha superato il lease, la ricevuta dei costi va depositata;
  // finalize server respinge il comando/testo scaduto ma conserva l'audit del tentativo.
  leaseDeadline=Infinity;
  try {
    const done=await bounded(nativeIntentResolution(work)?35000:10000,signal=>db.finalize(work,delivery,resultSha,{signal}));
    if (done?.schema_version !== 'mission-generic-status/1' || done.work_id !== work.work_id
      || done.master_session_id !== work.master_session_id || done.event_id !== work.event_id
      || done.request_key !== request.request_key || done.revision !== request.expected_revision
      || done.result_sha256 !== resultSha || !uuid(done.receipt_id)
      || !['completed','failed','uncertain'].includes(done.state)) throw Error('MISSION_FINALIZE_INVALID');
    if(done.state==='uncertain')return accountCount({...pending('provider'),receipt_id:done.receipt_id,provider_calls:calls,
      usage,usage_unknown:usage===null});
    return accountCount({status:200,code:done.state==='completed'?'MISSION_EVENT_COMPLETE':'MISSION_EVENT_FAILED',receipt_id:done.receipt_id,
      provider_calls:calls,usage,usage_unknown:usage===null,retry:false,provider_retry_allowed:false});
  } catch { return observe('finalize'); }
}

CREATE OR REPLACE FUNCTION mission_generic_owner.c8_policy_snapshot_v1(p_work uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb; extension_policy jsonb; extroot mission_factory_owner.editor_release_readiness; extwork mission_generic_owner.work_items;
BEGIN
 SELECT q.value INTO result FROM (SELECT snapshot_base || CASE WHEN staff_policy IS NOT NULL THEN jsonb_build_object('schema_version','c1266-staff-scene-count-snapshot/2','scene_policy',staff_policy,'scene_policy_sha256',public.combat_v2_sha256(staff_policy),'scene_policy_contract_sha256','1564720ca33bc961ff26fc15e07bd364ebd41a60b7a5a48c970a9c100038fad6','release_sha256',(SELECT revision_sha256 FROM mission_factory_owner.editor_release_readiness WHERE singleton),'backing_origin','finite_columns_not_effective_staff_ceilings') ELSE '{}'::jsonb END FROM (SELECT CASE WHEN mission_generic_owner.c8_context24_scope_v1(p_work) THEN mission_generic_owner.c8_policy_snapshot_v1()||jsonb_build_object('max_input_tokens',24000,'max_output_tokens',20000) ELSE mission_generic_owner.c8_policy_snapshot_v1() END AS snapshot_base,mission_generic_owner.c1266_staff_scene_policy_v1((SELECT master_session_id FROM mission_generic_owner.work_items WHERE id=p_work)) AS staff_policy) staff_snapshot) AS q(value);
 IF p_work='4fb5ea83-f90a-4b76-a6f5-722641d9da43'::uuid THEN
  SELECT * INTO STRICT extwork FROM mission_generic_owner.work_items WHERE id=p_work;
  SELECT * INTO STRICT extroot FROM mission_factory_owner.editor_release_readiness WHERE singleton;
  extension_policy:=extroot.canonical_preimage::jsonb#>'{config,c1266_director_incomplete_recovery}';
  IF extroot.state IS DISTINCT FROM 'enabled' OR extroot.revision_sha256 IS DISTINCT FROM extroot.observed_revision_sha256
   OR extroot.revision_sha256 IS DISTINCT FROM encode(extensions.digest(convert_to(extroot.canonical_preimage,'UTF8'),'sha256'),'hex')
   OR extension_policy IS DISTINCT FROM '{"schema_version":"c1266-director-incomplete-recovery/1","enabled":true,"master_session_id":"4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4","old_work_id":"48df8786-3b66-4b44-a1bd-c92473ee5e55","old_payload_sha256":"58d06c515d3ea564a71075b69596d9823e4453688e50b64d7c061ca3f7a648ca","raw_sha256":"f2918095e64fabbd6910ec8566b2e2ccb8193be4ac5d6c0fc3fa8b1477d55c88","successor_work_id":"4fb5ea83-f90a-4b76-a6f5-722641d9da43","max_successors":1,"target_output_tokens":32000}'::jsonb
   OR extwork.master_session_id IS DISTINCT FROM '4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4'::uuid OR extwork.kind IS DISTINCT FROM 'director'
   OR extwork.payload->>'schema_version' IS DISTINCT FROM 'mission-director-work/4'
   OR mission_generic_owner.manual_staff_template_policy_v1(extwork.master_session_id) IS NULL
   OR result->>'max_input_tokens' IS DISTINCT FROM '24000' OR result->>'max_output_tokens' IS DISTINCT FROM '20000'
  THEN RAISE EXCEPTION 'C1266_DIRECTOR32_POLICY_BINDING' USING ERRCODE='42501';END IF;
  IF EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 ec WHERE ec.work_id=p_work
    AND (ec.scope IS DISTINCT FROM 'staff_mission' OR ec.contract_sha256 IS DISTINCT FROM public.combat_v2_sha256(ec.contract)
      OR NOT(ec.contract->'features'?'director_output_32k_v1'))) THEN RAISE EXCEPTION 'C1266_DIRECTOR32_SEALED_FEATURE' USING ERRCODE='42501';END IF;
  result:=result||jsonb_build_object('max_output_tokens',32000,'output_extension',jsonb_build_object(
   'schema_version','c1266-director-output-extension/1','feature','director_output_32k_v1','work_id',p_work,
   'base_rate_qualification_sha256','d8da6486b29f5e6b57272eb9d21660518cdcb57f12ed69209e12f32c37e2d5c0',
   'policy_sha256',public.combat_v2_sha256(extension_policy),'input_tokens_limit',24000,'output_tokens_limit',32000,
   'input_usd_million',0.1,'output_usd_million',0.5,'count_upper_cost_usd','0.0184','generation_upper_cost_usd','0.0184',
   'derivation','(24000*0.1+32000*0.5)/1000000;Count conservative same envelope'));
 END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.mission_generic_dispatch_claim_v1(p_user uuid, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare named_clean48 boolean:=false;w mission_generic_owner.work_items;a mission_generic_owner.dispatch_admissions;pol mission_narrative_internal.runtime_policy;
 d mission_narrative_internal.dispatch_receipts;
 dr uuid;env jsonb;fp text;limits jsonb;staff_calls bigint; narrative_contract jsonb;c7_budget jsonb;
c26_proof jsonb;c5_proof jsonb;campaign_scope boolean;observed jsonb;
 rpc_count_policy text;rpc_scene_policy jsonb;
begin
 perform mission_ai_board_owner.service_only();
 -- C1266_AVAILABILITY_COORD: shared before mutation locks; xact lifetime.
 PERFORM pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0));

 -- C9: freeze policy DML through proof, Native reserve and authorization.
 LOCK TABLE mission_narrative_internal.runtime_policy IN SHARE MODE;
 perform mission_generic_owner.dispatch_user((p_request->>'master_session_id')::uuid,p_user);
 -- Event42 server-only initiation for newly rooted sessions. Existing R1/ordinary is unchanged.
 IF EXISTS(SELECT 1 FROM mission_generic_owner.event_outbox_v1 root42
 WHERE root42.master_session_id=(p_request->>'master_session_id')::uuid AND root42.event_domain='start')
 AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.event_outbox_v1 permit42
 WHERE permit42.master_session_id=(p_request->>'master_session_id')::uuid AND permit42.state='running'
 AND permit42.root_principal=p_user AND permit42.claim_id IS NOT NULL
 AND permit42.claim_expires_at>clock_timestamp() AND permit42.claim_txid=txid_current()
 AND permit42.claim_backend=pg_backend_pid() AND permit42.canonical_request=p_request
 AND permit42.work_id IS NOT NULL) THEN
 RAISE EXCEPTION 'EVENT42_SERVER_EVENT_REQUIRED' USING ERRCODE='42501';END IF;

 if (p_request->>'master_session_id')='b70b23cf-bad8-475d-a56a-d9c549e35d84' then
   raise exception 'MRS_STAFF_SUNA_TICK_PAUSED' using errcode='55000';
 end if;
 perform 1 from mission_generic_owner.role_window_cursors
   where master_session_id=(p_request->>'master_session_id')::uuid for update;
 perform 1 from public.master_v2_sessions where id=(p_request->>'master_session_id')::uuid for update;
 select * into strict w from mission_generic_owner.work_items where master_session_id=(p_request->>'master_session_id')::uuid
 and event_id=(p_request->>'event_id')::uuid and request_key=(p_request->>'request_key')::uuid and revision=(p_request->>'expected_revision')::bigint for update;
 if mission_generic_owner.count_overflow_terminal_v1(w.id,p_user) then return jsonb_build_object('state','failed','granted_now',false);end if;
 campaign_scope:=NOT EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 ma WHERE ma.master_session_id=w.master_session_id) AND (EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 sticky_wc
 WHERE sticky_wc.master_session_id=w.master_session_id AND sticky_wc.scope='staff_mission'
 AND sticky_wc.contract_sha256=public.combat_v2_sha256(sticky_wc.contract)
 AND sticky_wc.contract->>'schema_version'='mission-narrative-admission/3'
 AND sticky_wc.contract->'features' ? 'execution_authority_v1'
 AND (sticky_wc.contract#>>'{source_attestation,execution_authority,schema_version}'='c1266-work-execution-attestation/1' OR ((mission_generic_owner.c1266_historical_work_v1(sticky_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND sticky_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(sticky_wc.work_id)))
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,execution_context}'='staff_mission'
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,admission,kind}'='staff_finite'
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,admission,resource_scope}'='staff_simulation'
 AND (sticky_wc.contract#>>'{source_attestation,execution_authority,source_scope,mission_id}'='5878822d-dc03-4ac2-ad0b-1547f0ab3fc0' OR ((mission_generic_owner.c1266_historical_work_v1(sticky_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND sticky_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(sticky_wc.work_id)))
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,release_sha256}'=sticky_wc.release_sha256
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,binding_sha256}'=sticky_wc.definition_sha256) OR EXISTS(SELECT 1 FROM mission_generic_owner.simulation_sources ss21
 JOIN mission_generic_owner.board_starts bs21 ON bs21.request_key=ss21.request_key
 JOIN mission_generic_owner.start_claims sc22 ON sc22.session_id=bs21.master_session_id
 JOIN mission_generic_owner.run_bindings rb21 ON rb21.master_session_id=bs21.master_session_id
 JOIN public.master_v2_sessions ms21 ON ms21.id=bs21.master_session_id
  AND ms21.mission_id=ss21.carrier_mission_id
 WHERE NOT EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 manual_source WHERE manual_source.master_session_id=bs21.master_session_id) AND bs21.master_session_id=w.master_session_id
 AND ms21.owner_kind='ai_service' AND ms21.master_user IS NULL
 AND ms21.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
 AND (ss21.source_mission_id='5878822d-dc03-4ac2-ad0b-1547f0ab3fc0'::uuid OR (mission_generic_owner.c1266_staff_source_scope_v1(bs21.master_session_id) IS NOT NULL AND ss21.source_mission_id::text=mission_generic_owner.c1266_staff_source_scope_v1(bs21.master_session_id)#>>'{source_scope,mission_id}'))
 AND sc22.state='bound' AND sc22.simulation
 AND sc22.mission_id=ms21.mission_id AND sc22.location_id=ms21.location_id
 AND sc22.request_key=bs21.request_key
 AND bs21.simulation AND bs21.snapshot->'simulation'='true'::jsonb
 AND bs21.snapshot_sha256=mission_internal.fingerprint(bs21.snapshot)
 AND bs21.snapshot->>'schema_version'='mission-generic-opening-source/1'
 AND bs21.snapshot->>'mission_id'=ss21.carrier_mission_id::text
 AND bs21.snapshot->>'location_id'='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'
 AND rb21.snapshot_sha256=mission_internal.fingerprint(rb21.snapshot)
 AND rb21.snapshot->>'schema_version'='mission-generic-run/1'));
 IF campaign_scope AND((w.state='claimed' AND w.lease_expires_at<=clock_timestamp()) OR(w.state='ready' AND w.dispatch_receipt_id IS NOT NULL)) THEN
  observed:=public.mission_generic_dispatch_status_v1(p_user,p_request);
  SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=w.id;
  RETURN jsonb_build_object('state',w.state,'granted_now',false,'reason_code',CASE WHEN w.state IN('failed','completed') THEN 'C1266_CAMPAIGN_TERMINAL_NO_REISSUE' ELSE 'C1266_CAMPAIGN_RECOVERY_PENDING' END);
 END IF;
 if w.state='claimed' and w.master_session_id='ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid AND (w.id<>'48e1bdcd-f044-be8c-1923-54d38e7e822c'::uuid OR w.lease_expires_at IS NULL OR w.lease_expires_at>clock_timestamp()) then return jsonb_build_object('state','claimed','granted_now',false);end if;
 IF w.id='48e1bdcd-f044-be8c-1923-54d38e7e822c'::uuid AND (mission_generic_owner.c8_context24_scope_v1(w.id) IS DISTINCT FROM TRUE OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id) IS DISTINCT FROM TRUE) THEN RAISE EXCEPTION 'C889_CONTEXT24_RUNTIME_CLOSED' USING ERRCODE='42501';END IF;
 perform mission_generic_owner.role_dispatch_assert_v4(w.id);
 IF mission_generic_owner.c1266_opening_named_v1(w.master_session_id) THEN
  c5_proof:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);
  IF c5_proof IS NULL OR mission_generic_owner.flow_scope_enabled(w.master_session_id) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'C1266_CLAIM5_CLOSED' USING ERRCODE='42501';END IF;
