 if w.state<>'claimed' or w.lease_id is distinct from p_lease or w.lease_expires_at<=clock_timestamp() or r.status<>'claimed' or r.authority_receipt_id<>w.id or r.master_session_id<>w.master_session_id or r.request_key<>w.request_key or r.event_kind<>'mission_generic_event' or r.renderer_version<>'mission-generic-runtime/1' or r.dispatch_count<>0 or w.authorization_id is not null or w.dispatch_id is not null or exists(select 1 from mission_narrative_internal.dispatch_attempts where receipt_id=r.id) or exists(select 1 from mission_narrative_internal.provider_authorizations where receipt_id=r.id) then raise exception 'C8_COUNT_SCOPE' using ERRCODE='P0001';end if;
 if p_payload_text is null or p_payload_sha !~ '^[0-9a-f]{64}$' or p_payload_sha is distinct from encode(extensions.digest(convert_to(p_payload_text,'UTF8'),'sha256'),'hex') then raise exception 'C8_COUNT_REQUEST_HASH' using errcode='22023';end if;
 payload:=p_payload_text::jsonb;
 request_limit:=case when w.kind='narration' and (mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id)) then 131072 when w.kind='director' and (mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id)) then 65536 else least(65536,(mission_generic_owner.capacity()->>'input_capacity_bytes')::integer) end;
  IF w.kind='director' AND c5_proof->>'runtime_authorized'='true' AND c5_proof->>'execution_context'='staff_mission' AND c5_proof#>>'{admission,kind}'='staff_finite' AND c5_proof#>>'{admission,resource_scope}'='staff_simulation' AND mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 gm WHERE gm.master_session_id=w.master_session_id) AND (mission_public_owner.work_contract_v1(w.id))->>'editorial_profile'='cinematic_master_1' THEN request_limit:=98304;END IF;
