    AND ms.owner_kind='ai_service' AND ms.location_id=(campaign->>'location_id')::uuid
    AND ss.source_mission_id=(clean_policy->>'source_mission_id')::uuid)=1
   AND (EXISTS(WITH historical_proofs AS MATERIALIZED (
 SELECT wc0.*,mission_generic_owner.c1266_historical_work_v1(wc0.work_id) AS historical_proof
 FROM mission_public_owner.work_contracts_v1 wc0
 WHERE wc0.master_session_id=p_session AND wc0.scope='staff_mission'
 AND wc0.contract->>'schema_version'='mission-narrative-admission/3'
 AND wc0.contract->'features' ? 'execution_authority_v1'
 ) SELECT 1 FROM historical_proofs sticky_wc
 WHERE sticky_wc.master_session_id=p_session AND sticky_wc.scope='staff_mission'
 AND sticky_wc.contract_sha256=public.combat_v2_sha256(sticky_wc.contract)
 AND sticky_wc.contract->>'schema_version'='mission-narrative-admission/3'
 AND sticky_wc.contract->'features' ? 'execution_authority_v1'
 AND (sticky_wc.contract#>>'{source_attestation,execution_authority,schema_version}'='c1266-work-execution-attestation/1' OR ((sticky_wc.historical_proof->>'schema_version'='c1266-work-execution-attestation/2') AND sticky_wc.contract#>'{source_attestation,execution_authority}'=sticky_wc.historical_proof))
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,execution_context}'='staff_mission'
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,admission,kind}'='staff_finite'
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,admission,resource_scope}'='staff_simulation'
 AND (sticky_wc.contract#>>'{source_attestation,execution_authority,source_scope,mission_id}'='5878822d-dc03-4ac2-ad0b-1547f0ab3fc0' OR ((sticky_wc.historical_proof->>'schema_version'='c1266-work-execution-attestation/2') AND sticky_wc.contract#>'{source_attestation,execution_authority}'=sticky_wc.historical_proof))
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,release_sha256}'=sticky_wc.release_sha256
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,binding_sha256}'=sticky_wc.definition_sha256) OR EXISTS(SELECT 1 FROM mission_generic_owner.simulation_sources ss21
 JOIN mission_generic_owner.board_starts bs21 ON bs21.request_key=ss21.request_key
 JOIN mission_generic_owner.start_claims sc22 ON sc22.session_id=bs21.master_session_id
 JOIN mission_generic_owner.run_bindings rb21 ON rb21.master_session_id=bs21.master_session_id
 JOIN public.master_v2_sessions ms21 ON ms21.id=bs21.master_session_id
  AND ms21.mission_id=ss21.carrier_mission_id
 WHERE NOT EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 manual_source WHERE manual_source.master_session_id=bs21.master_session_id) AND bs21.master_session_id=p_session
 AND ms21.owner_kind='ai_service' AND ms21.master_user IS NULL
 AND ms21.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
 AND (ss21.source_mission_id='5878822d-dc03-4ac2-ad0b-1547f0ab3fc0'::uuid OR (mission_generic_owner.c1266_staff_source_scope_v1(bs21.master_session_id) IS NOT NULL AND ss21.source_mission_id::text=mission_generic_owner.c1266_staff_source_scope_v1(bs21.master_session_id)#>>'{source_scope,mission_id}'))
 AND sc22.state='bound' AND sc22.simulation
 AND sc22.mission_id=ms21.mission_id AND sc22.location_id=ms21.location_id
 AND sc22.request_key=bs21.request_key
 AND bs21.simulation AND bs21.snapshot->'simulation'='true'::jsonb
 AND bs21.snapshot_sha256=mission_internal.fingerprint(bs21.snapshot)
 AND bs21.snapshot->>'schema_version'='mission-generic-opening-source/1'
 AND bs21.snapshot->>'mission_id'=ss21.carrier_mission_id::text
 AND bs21.snapshot->>'location_id'='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'
 AND rb21.snapshot_sha256=mission_internal.fingerprint(rb21.snapshot)
 AND rb21.snapshot->>'schema_version'='mission-generic-run/1'))
   AND NOT EXISTS(SELECT 1 FROM staff_ai_quota_private.calls q WHERE (q.created_at>=(campaign->>'not_before')::timestamptz OR q.sent_at>=(campaign->>'not_before')::timestamptz)
    AND q.scope_id<>p_session AND NOT(q.scope_id=ANY(history_ids)) AND q.state<>'no_http');
  -- Existing unique (producer,source_id,call_no) is the per-phase ticket.
  -- Every active work holds each phase missing from that ledger. Admission FOR UPDATE
  -- serializes claim/Count/Gen, so concurrent work cannot spend the same free pair.
  SELECT count(*) FILTER(WHERE call_no=2),count(*) FILTER(WHERE call_no=1),count(*),
   coalesce(sum(CASE WHEN state IN('settled','over_cap') THEN charged_usd ELSE reserved_usd END),0)
  INTO actual_c,actual_g,actual_h,actual_usd FROM staff_ai_quota_private.calls
  WHERE producer='mission_generic_ai' AND scope_id=p_session AND state<>'no_http';
  SELECT count(*) FILTER(WHERE NOT EXISTS(SELECT 1 FROM staff_ai_quota_private.calls q
    WHERE q.producer='mission_generic_ai' AND q.source_id=wi.dispatch_receipt_id AND q.scope_id=p_session AND q.call_no=2 AND q.state<>'no_http')),
   count(*) FILTER(WHERE NOT EXISTS(SELECT 1 FROM staff_ai_quota_private.calls q
    WHERE q.producer='mission_generic_ai' AND q.source_id=wi.dispatch_receipt_id AND q.scope_id=p_session AND q.call_no=1 AND q.state<>'no_http'))
  INTO hold_c,hold_g FROM mission_generic_owner.work_items wi
  WHERE wi.master_session_id=p_session AND wi.state IN('claimed','authorized','provider_started');
  new_pair:=CASE WHEN p_next AND p_current_work IS NULL THEN 1 ELSE 0 END;
  IF p_current_work IS NOT NULL THEN
   SELECT * INTO own_work FROM mission_generic_owner.work_items WHERE id=p_current_work;
   campaign_ok:=campaign_ok AND own_work.master_session_id=p_session
    AND own_work.state IN('claimed','authorized','provider_started')
    AND own_work.lease_expires_at>asof+interval '20 seconds'
    AND (named47 OR own_work.lease_expires_at<=provider_deadline);
  ELSE
   -- A non-prospective observation (progress_step with pending work) reserves nothing.
   IF p_next AND NOT named47 THEN campaign_ok:=campaign_ok AND asof+make_interval(secs=>(campaign->>'work_seconds')::integer)<provider_deadline;END IF;
  END IF;
  actual_c:=actual_c+hold_c+new_pair;actual_g:=actual_g+hold_g+new_pair;
  actual_h:=actual_h+hold_c+hold_g+2*new_pair;
  actual_usd:=actual_usd+(hold_c+hold_g+2*new_pair)*0.0124;
  IF hist_c<>(hist31->>'count')::bigint OR hist_g<>(hist31->>'gen')::bigint OR hist_h<>(hist31->>'http')::bigint OR hist_usd<>(hist31->>'usd')::numeric THEN stop_causes:=stop_causes||jsonb_build_array('HISTORICAL_LEDGER_DRIFT');END IF;
  IF asof<(campaign->>'not_before')::timestamptz THEN stop_causes:=stop_causes||jsonb_build_array('CAMPAIGN_NOT_STARTED');END IF;
  IF NOT named47 AND ((p_next OR p_current_work IS NOT NULL) AND asof>=provider_deadline) THEN stop_causes:=stop_causes||jsonb_build_array('PROVIDER_DEADLINE_REACHED');END IF;
  IF NOT named47 AND (NOT p_next AND p_current_work IS NULL AND asof>=(campaign->>'expires_at')::timestamptz) THEN stop_causes:=stop_causes||jsonb_build_array('CAMPAIGN_EXPIRED');END IF;
  IF NOT named47 AND (p_next AND p_current_work IS NULL AND asof+make_interval(secs=>(campaign->>'work_seconds')::integer)>=provider_deadline) THEN stop_causes:=stop_causes||jsonb_build_array('NEW_WORK_WINDOW_CLOSED');END IF;
  IF p_current_work IS NOT NULL AND(own_work.lease_expires_at IS NULL OR own_work.lease_expires_at<=asof+interval '20 seconds') THEN stop_causes:=stop_causes||jsonb_build_array('PHASE_LEASE_MARGIN_CLOSED');END IF;
  IF EXISTS(SELECT 1 FROM staff_ai_quota_private.calls q WHERE(q.created_at>=(campaign->>'not_before')::timestamptz OR q.sent_at>=(campaign->>'not_before')::timestamptz) AND q.scope_id<>p_session AND NOT(q.scope_id=ANY(history_ids)) AND q.state<>'no_http') THEN stop_causes:=stop_causes||jsonb_build_array('FOREIGN_ACTIVITY');END IF;
  IF (SELECT count(*) FROM mission_generic_owner.start_claims sc
    JOIN mission_generic_owner.board_starts bs ON bs.master_session_id=sc.session_id
    JOIN public.master_v2_sessions ms ON ms.id=sc.session_id
    JOIN mission_generic_owner.simulation_sources ss ON ss.carrier_mission_id=ms.mission_id
    WHERE sc.state='bound' AND sc.simulation AND sc.request_key=bs.request_key
    AND bs.created_at>=(campaign->>'not_before')::timestamptz AND (named47 OR bs.created_at<(campaign->>'expires_at')::timestamptz)
    AND ms.owner_kind='ai_service' AND ms.location_id=(campaign->>'location_id')::uuid
    AND ss.source_mission_id=(clean_policy->>'source_mission_id')::uuid)<>1 THEN stop_causes:=stop_causes||jsonb_build_array('CAMPAIGN_START_COUNT_NOT_ONE');END IF;
  IF NOT named47 AND ((campaign->>'expires_at')::timestamptz-(campaign->>'not_before')::timestamptz>(CASE WHEN fourth38 OR fifth40 OR sixth43 OR seventh46 THEN interval '60 minutes' ELSE interval '30 minutes' END)) THEN stop_causes:=stop_causes||jsonb_build_array(CASE WHEN fourth38 OR fifth40 OR sixth43 OR seventh46 THEN 'CAMPAIGN_DURATION_EXCEEDS_60_MIN' ELSE 'CAMPAIGN_DURATION_EXCEEDS_30_MIN' END);END IF;
  IF NOT(NOT EXISTS(SELECT 1 FROM staff_ai_quota_private.calls q WHERE (q.scope_id=p_session OR q.scope_id=ANY(history_ids))
    AND q.state<>'no_http' AND(q.producer<>'mission_generic_ai' OR q.call_no NOT IN(1,2)))) THEN stop_causes:=stop_causes||jsonb_build_array('UNEXPECTED_PRODUCER_OR_CALL_NO');END IF;
  IF (EXISTS(SELECT 1 FROM mission_generic_owner.start_claims sc
    JOIN mission_generic_owner.board_starts bs ON bs.master_session_id=sc.session_id
    WHERE sc.session_id=p_session AND sc.request_key=bs.request_key AND sc.state='bound' AND sc.simulation
    AND sc.actor_user_id IN('b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid,'f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid)
    AND bs.created_at>=(campaign->>'not_before')::timestamptz AND (named47 OR bs.created_at<(campaign->>'expires_at')::timestamptz))) IS DISTINCT FROM TRUE THEN stop_causes:=stop_causes||jsonb_build_array('OWN_START_ACTOR_OR_WINDOW_CLOSED');END IF;
  IF actual_c>cap_c31 OR actual_g>cap_g31 OR actual_h>cap_h31 OR actual_usd>cap_usd31 THEN stop_causes:=stop_causes||jsonb_build_array('CAMPAIGN_BUDGET_EXHAUSTED');END IF;
  campaign_ok:=coalesce(campaign_ok,false) AND actual_c<=cap_c31 AND actual_g<=cap_g31 AND actual_h<=cap_h31
   AND greatest(actual_c,actual_g)<=cap_pairs31 AND actual_usd<=cap_usd31
   AND actual_c<=(res31->>'count')::bigint AND actual_g<=(res31->>'gen')::bigint AND actual_h<=(res31->>'http')::bigint AND actual_usd<=(res31->>'usd')::numeric;
  IF mission_academy_owner.staff_carrier_runtime(p_session) IS DISTINCT FROM TRUE THEN stop_causes:=stop_causes||jsonb_build_array('STAFF_SETTLEMENT_CLASSIFIER_CLOSED');END IF;
  IF NOT campaign_ok AND stop_causes='[]'::jsonb THEN stop_causes:=jsonb_build_array('OWN_SCOPE_OR_SETTLEMENT_BINDING_CLOSED');END IF;
  RETURN jsonb_build_object('enforced',true,'allowed',ok AND campaign_ok,'remaining_calls',greatest(0,least(cap_h31,(res31->>'http')::bigint)-actual_h),
   'spent_usd',spent,'upper_bound_next_usd',bound,'call_limit',NULL,'cost_limit_usd',NULL,
   'qualification_sha256',a.c7_budget_qualification_sha256,'count_upper_cost_usd',a.c8_count_upper_cost_usd,
   'count_qualification_sha256',a.c8_count_qualification_sha256,'http_slots_per_generation',2,
   'scene_policy',scene_policy,'scene_policy_contract_sha256','1564720ca33bc961ff26fc15e07bd364ebd41a60b7a5a48c970a9c100038fad6',
   'scene_policy_sha256',public.combat_v2_sha256(scene_policy),'backing_origin','finite_columns_not_effective_staff_ceilings',
   'campaign_id',campaign->>'campaign_id','campaign_policy_sha256',public.combat_v2_sha256(campaign),
   'campaign_provider_deadline',provider_deadline,'campaign_incomplete',NOT campaign_ok,
   'campaign_reserved_count',actual_c,'campaign_reserved_gen',actual_g,'campaign_reserved_http',actual_h,
   'campaign_reserved_usd',actual_usd,'stop_causes',stop_causes,'reason_code',CASE WHEN campaign_ok THEN NULL ELSE 'C1266_CAMPAIGN_LIMIT_STOP' END) || CASE WHEN named47 THEN jsonb_build_object('campaign_time_mode','budget_or_explicit_stop') ELSE '{}'::jsonb END;
 END IF;

 IF scene_policy IS NOT NULL THEN
  RETURN jsonb_build_object('enforced',true,'allowed',ok,'remaining_calls',NULL,
   'spent_usd',spent,'upper_bound_next_usd',bound,'call_limit',NULL,'cost_limit_usd',NULL,
   'qualification_sha256',a.c7_budget_qualification_sha256,'count_upper_cost_usd',a.c8_count_upper_cost_usd,
   'count_qualification_sha256',a.c8_count_qualification_sha256,'http_slots_per_generation',2,
   'scene_policy',scene_policy,'scene_policy_contract_sha256','1564720ca33bc961ff26fc15e07bd364ebd41a60b7a5a48c970a9c100038fad6',
   'scene_policy_sha256',public.combat_v2_sha256(scene_policy),'backing_origin','finite_columns_not_effective_staff_ceilings');
 END IF;

 return jsonb_build_object('enforced',true,'allowed',ok,'manual_count_limit',mission_generic_owner.manual_staff_count_limit_v1(p_session),'remaining_calls',CASE WHEN mission_generic_owner.manual_staff_count_limit_v1(p_session)='none' THEN NULL ELSE greatest(0,capcalls-calls) END,
 'spent_usd',spent,'upper_bound_next_usd',bound,'call_limit',CASE WHEN mission_generic_owner.manual_staff_count_limit_v1(p_session)='none' THEN NULL ELSE capcalls END,'cost_limit_usd',capcost,
 'qualification_sha256',a.c7_budget_qualification_sha256,'count_upper_cost_usd',a.c8_count_upper_cost_usd,'count_qualification_sha256',a.c8_count_qualification_sha256,'http_slots_per_generation',2);
end $function$
