ted_at>=date_trunc('day',clock_timestamp());select coalesce(sum(case when status in('success','fallback','unknown_billable') or (quest_compile_request is not null and status='failed') then charged_cost_usd else coalesce(upper_bound_cost_usd,0) end),0) into spent_all from mission_narrative_internal.dispatch_receipts;
