 END IF;
 IF staff AND m.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
  AND EXISTS(SELECT 1 FROM public.locations rp37_loc WHERE rp37_loc.id=m.location_id AND rp37_loc.is_test)
