CREATE OR REPLACE FUNCTION mission_generic_owner.director_incomplete_reissue_proof_v1(p_work uuid, p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 rdw mission_generic_owner.work_items;
 rdwc mission_public_owner.work_contracts_v1;
 rdd mission_narrative_internal.dispatch_receipts;
 rdr mission_narrative_internal.provider_outputs_v1;
 rdu mission_generic_owner.unified_source_windows;
 rdb mission_generic_owner.unified_batches;
 rdc mission_generic_owner.work_items;
 rdq jsonb;rdh jsonb;rdf jsonb;rdo jsonb;rdcount_start jsonb;rdcount_success jsonb;rdp jsonb;rda jsonb;rdrequest jsonb;rdpub boolean:=false;rdn integer;cfg jsonb;aud jsonb;prep jsonb;child mission_generic_owner.work_items;cs mission_generic_owner.unified_source_windows;publication jsonb;
BEGIN
 IF p_work IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO rdw FROM mission_generic_owner.work_items WHERE id=p_work;
 IF rdw.id IS NULL OR rdw.kind IS DISTINCT FROM 'director' OR rdw.state IS DISTINCT FROM 'failed'
  OR rdw.message_id IS NOT NULL OR rdw.result->'ok' IS DISTINCT FROM 'false'::jsonb
  OR rdw.result->>'provider_calls' IS DISTINCT FROM '1'
  OR rdw.result->'outcome_uncertain' IS DISTINCT FROM 'false'::jsonb
  OR NOT coalesce(rdw.result->'failure_codes'='["MISSION_PROVIDER_INCOMPLETE"]'::jsonb,false)
  OR rdw.payload->>'schema_version' IS DISTINCT FROM 'mission-director-work/4'
  OR rdw.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(rdw.payload)
 THEN RETURN NULL;END IF;
 rdq:=mission_generic_owner.manual_staff_scope_v1(rdw.master_session_id);
 rdh:=mission_generic_owner.c1266_historical_work_v1(rdw.id);
 IF rdq IS NULL OR rdh IS NULL OR rdh->>'schema_version' IS DISTINCT FROM 'c1266-work-execution-attestation/3'
  OR rdh->>'execution_context' IS DISTINCT FROM 'staff_mission'
 THEN RETURN NULL;END IF;
 SELECT * INTO rdwc FROM mission_public_owner.work_contracts_v1 WHERE work_id=rdw.id;
 IF rdwc.work_id IS NULL OR rdwc.master_session_id IS DISTINCT FROM rdw.master_session_id
  OR rdwc.contract_sha256 IS DISTINCT FROM public.combat_v2_sha256(rdwc.contract)
  OR rdwc.contract->>'payload_sha256' IS DISTINCT FROM rdw.payload_sha256
  OR rdwc.contract->>'scope' IS DISTINCT FROM 'staff_mission'
  OR NOT coalesce(rdwc.contract->'features' ? 'provider_output_retention_v1',false)
 THEN RETURN NULL;END IF;
 SELECT * INTO rdd FROM mission_narrative_internal.dispatch_receipts WHERE id=rdw.dispatch_receipt_id;
 rdrequest:=jsonb_build_object('schema_version','mission-generic-request/1','master_session_id',rdw.master_session_id,
  'event_id',rdw.event_id,'request_key',rdw.request_key,'expected_revision',rdw.revision);
 IF rdd.id IS NULL OR rdd.master_session_id IS DISTINCT FROM rdw.master_session_id
  OR rdd.authority_receipt_id IS DISTINCT FROM rdw.id OR rdd.request_key IS DISTINCT FROM rdw.request_key
  OR rdd.request_fingerprint IS DISTINCT FROM mission_internal.fingerprint(rdrequest)
  OR rdd.envelope_sha256 IS DISTINCT FROM public.combat_v2_sha256(rdd.envelope)
  OR rdd.authority_sha256 IS DISTINCT FROM rdd.envelope_sha256
  OR rdd.envelope->'narrative_admission' IS DISTINCT FROM rdwc.contract
  OR rdd.status IS DISTINCT FROM 'success' OR rdd.dispatch_count IS DISTINCT FROM 1
  OR rdd.finalized_at IS NULL
  OR NOT EXISTS(SELECT 1 FROM mission_narrative_internal.provider_authorizations rdz
    WHERE rdz.id=rdw.authorization_id AND rdz.receipt_id=rdd.id)
  OR NOT EXISTS(SELECT 1 FROM staff_ai_quota_private.calls rdcall
    WHERE rdcall.source_id=rdd.id AND rdcall.producer='mission_generic_ai'
     AND rdcall.scope_id=rdw.master_session_id AND rdcall.call_no=1 AND rdcall.state='settled'
     AND rdcall.charged_usd=rdd.charged_cost_usd)
 THEN RETURN NULL;END IF;
 SELECT count(*),jsonb_agg(rdfinal.details)->0 INTO rdn,rdf
 FROM mission_narrative_internal.dispatch_audit rdfinal WHERE rdfinal.receipt_id=rdd.id AND rdfinal.event_code='generic_finalized';
 IF rdn<>1 OR rdf->>'work_id' IS DISTINCT FROM rdw.id::text
  OR rdf->>'receipt_id' IS DISTINCT FROM rdw.receipt_id::text
  OR rdf->>'result_sha256' IS DISTINCT FROM rdw.result_sha256
  OR rdf->>'result_jsonb_sha256' IS DISTINCT FROM public.combat_v2_sha256(rdw.result)
  OR rdf->'stale' IS DISTINCT FROM 'false'::jsonb
  OR rdf->'outcome_uncertain' IS DISTINCT FROM 'false'::jsonb
  OR rdf->'command_receipt' IS DISTINCT FROM 'null'::jsonb
 THEN RETURN NULL;END IF;
 SELECT count(*),jsonb_agg(rdowner.details)->0 INTO rdn,rdo
 FROM mission_narrative_internal.dispatch_audit rdowner WHERE rdowner.receipt_id=rdd.id AND rdowner.event_code='c1266_async_owner_v1';
 IF rdn<>1 OR NOT mission_factory_owner.keys_exact_v2(rdo,ARRAY['schema_version','actor_user_id','work_id','request_sha256','envelope_sha256','provider_timeout_ms'])
  OR rdo->>'schema_version' IS DISTINCT FROM 'mission-generic-async-owner/1'
  OR rdo->>'work_id' IS DISTINCT FROM rdw.id::text
  OR rdo->>'request_sha256' IS DISTINCT FROM public.combat_v2_sha256(rdrequest)
  OR rdo->>'envelope_sha256' IS DISTINCT FROM rdd.envelope_sha256
  OR NOT coalesce(rdq->'actor_user_ids' ? (rdo->>'actor_user_id'),false)
 THEN RETURN NULL;END IF;
 SELECT count(*) INTO rdn FROM mission_narrative_internal.provider_outputs_v1 rdout
 WHERE rdout.work_id=rdw.id AND rdout.authorization_id=rdw.authorization_id AND rdout.dispatch_id=rdw.dispatch_id;
 IF rdn<>1 THEN RETURN NULL;END IF;
 SELECT * INTO rdr FROM mission_narrative_internal.provider_outputs_v1 rdout
 WHERE rdout.work_id=rdw.id AND rdout.authorization_id=rdw.authorization_id AND rdout.dispatch_id=rdw.dispatch_id;
 IF rdr.dispatch_receipt_id IS DISTINCT FROM rdd.id OR rdr.provider_status IS DISTINCT FROM 'incomplete'
  OR rdr.raw_sha256 IS DISTINCT FROM rdw.result->>'raw_sha256'
  OR rdw.result->>'provider_status' IS DISTINCT FROM 'incomplete'
  OR rdr.raw_sha256 IS DISTINCT FROM encode(extensions.digest(convert_to(rdr.raw_output,'UTF8'),'sha256'),'hex')
  OR octet_length(rdr.raw_output) NOT BETWEEN 1 AND 262144
  OR rdr.usage IS DISTINCT FROM rdw.result->'usage'
 THEN RETURN NULL;END IF;
 SELECT count(*),jsonb_agg(rdcount.details)->0 INTO rdn,rdcount_start
 FROM mission_narrative_internal.dispatch_audit rdcount WHERE rdcount.receipt_id=rdd.id AND rdcount.event_code='c8_count_started';
 IF rdn<>1 THEN RETURN NULL;END IF;
 SELECT count(*),jsonb_agg(rdcount.details)->0 INTO rdn,rdcount_success
 FROM mission_narrative_internal.dispatch_audit rdcount WHERE rdcount.receipt_id=rdd.id AND rdcount.event_code='c8_count_success';
 IF rdn<>1 OR rdcount_start->>'work_id' IS DISTINCT FROM rdw.id::text
  OR rdcount_success->>'work_id' IS DISTINCT FROM rdw.id::text
  OR rdcount_start->>'measurement_id' IS DISTINCT FROM rdcount_success->>'measurement_id'
  OR rdcount_start->>'generation_request_sha256' IS DISTINCT FROM rdw.result->>'request_sha256'
  OR rdcount_start->>'generation_request_sha256' IS DISTINCT FROM rdcount_success->>'generation_request_sha256'
  OR rdcount_start->>'policy_snapshot_sha256' IS DISTINCT FROM public.combat_v2_sha256(rdcount_start->'policy_snapshot')
  OR rdcount_success->>'policy_snapshot_sha256' IS DISTINCT FROM rdcount_start->>'policy_snapshot_sha256'
  OR (rdcount_start->>'provider_input_contract_version' IN('mission-generic-provider-input/5','mission-generic-provider-input/6')) IS DISTINCT FROM TRUE
  OR rdcount_success->>'state' IS DISTINCT FROM 'success' OR rdcount_success->'generation_allowed' IS DISTINCT FROM 'true'::jsonb
  OR EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit rdunknown
    WHERE rdunknown.receipt_id=rdd.id AND rdunknown.event_code='c8_count_unknown')
 THEN RETURN NULL;END IF;
 SELECT * INTO rdu FROM mission_generic_owner.unified_source_windows WHERE id=rdw.authority_receipt_id AND work_id=rdw.id;
 IF rdu.id IS NULL OR rdu.master_session_id IS DISTINCT FROM rdw.master_session_id
  OR rdu.step_key IS DISTINCT FROM rdw.step_key OR rdu.run_control_version IS DISTINCT FROM rdw.run_control_version
  OR rdu.definition_sha256 IS DISTINCT FROM rdw.definition_sha256 OR rdu.source_sha256 IS DISTINCT FROM rdw.payload_sha256
  OR rdu.context IS DISTINCT FROM rdw.payload->'context' OR rdu.opportunities IS DISTINCT FROM rdw.payload->'opportunities'
 THEN RETURN NULL;END IF;

 IF rdw.result#>>'{provider_diagnostic,incomplete_reason}' IS DISTINCT FROM 'max_output_tokens'
 OR rdw.result#>'{provider_diagnostic,http_status}' IS DISTINCT FROM '200'::jsonb
 OR rdw.result#>'{usage,output_tokens}' IS DISTINCT FROM '20000'::jsonb
 OR rdw.result#>'{usage,reasoning_tokens}' IS DISTINCT FROM '11394'::jsonb
 OR rdr.raw_output::jsonb->>'status' IS DISTINCT FROM 'incomplete'
 OR rdr.raw_output::jsonb#>>'{incomplete_details,reason}' IS DISTINCT FROM 'max_output_tokens'
 THEN RETURN NULL;END IF;
 SELECT count(*),jsonb_agg(a.details)->0 INTO rdn,prep FROM mission_narrative_internal.dispatch_audit a
 WHERE a.receipt_id=rdd.id AND a.event_code='staff_director_incomplete_prepared_v1';
 IF rdn>1 THEN RETURN NULL;END IF;
 IF rdn=1 THEN
  IF prep->>'schema_version' IS DISTINCT FROM 'mission-director-incomplete-prepared/1'
  OR prep->>'old_work_id' IS DISTINCT FROM rdw.id::text OR prep->>'old_result_sha256' IS DISTINCT FROM rdw.result_sha256
  OR prep->>'old_result_jsonb_sha256' IS DISTINCT FROM public.combat_v2_sha256(rdw.result)
  OR prep->>'old_payload_sha256' IS DISTINCT FROM rdw.payload_sha256
  OR prep->>'raw_sha256' IS DISTINCT FROM rdr.raw_sha256 OR prep->>'raw_output_receipt_id' IS DISTINCT FROM rdr.id::text
  OR prep->>'source_window_id' IS DISTINCT FROM rdu.id::text OR prep->>'source_revision' IS DISTINCT FROM rdu.context->>'source_revision'
  OR prep->>'role_ids_sha256' IS DISTINCT FROM public.combat_v2_sha256(to_jsonb(rdu.role_ids))
  OR prep->>'source_before_sha256' IS DISTINCT FROM public.combat_v2_sha256(to_jsonb(rdu)-'superseded_at'-'superseded_reason')
  OR rdu.superseded_reason IS DISTINCT FROM 'staff_failed_director_incomplete_retry' OR rdu.superseded_at IS NULL OR rdu.consumed_message_id IS NOT NULL
  THEN RETURN NULL;END IF;
  SELECT count(*),jsonb_agg(a.details)->0 INTO rdn,aud FROM mission_narrative_internal.dispatch_audit a
   WHERE a.receipt_id=rdd.id AND a.event_code='staff_director_incomplete_reissued_v1';
  IF rdn>1 THEN RETURN NULL;END IF;
  IF rdn=1 THEN
   SELECT * INTO child FROM mission_generic_owner.work_items WHERE id=(prep->>'successor_work_id')::uuid;
   SELECT * INTO cs FROM mission_generic_owner.unified_source_windows WHERE id=child.authority_receipt_id AND work_id=child.id;
   IF child.id IS NULL OR child.kind IS DISTINCT FROM 'director' OR child.master_session_id IS DISTINCT FROM rdw.master_session_id
   OR child.step_key IS DISTINCT FROM rdw.step_key OR child.run_control_version IS DISTINCT FROM rdw.run_control_version
   OR child.definition_sha256 IS DISTINCT FROM rdw.definition_sha256 OR child.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(child.payload)
   OR cs.role_ids IS DISTINCT FROM rdu.role_ids OR cs.context->>'source_revision' IS DISTINCT FROM rdu.context->>'source_revision'
   OR cs.source_sha256 IS DISTINCT FROM child.payload_sha256 OR cs.context IS DISTINCT FROM child.payload->'context'
   OR aud->>'prepared_sha256' IS DISTINCT FROM public.combat_v2_sha256(prep)
   OR aud->>'successor_work_id' IS DISTINCT FROM child.id::text OR aud->>'successor_payload_sha256' IS DISTINCT FROM child.payload_sha256
   OR aud->>'successor_source_sha256' IS DISTINCT FROM public.combat_v2_sha256(to_jsonb(cs)-'consumed_message_id')
   THEN RETURN NULL;END IF;
   SELECT jsonb_build_object('writer_work_id',wr.id,'message_id',wr.message_id,'receipt_id',wr.receipt_id,'result_sha256',wr.result_sha256)
    INTO publication FROM mission_generic_owner.unified_batches b JOIN mission_generic_owner.work_items wr ON wr.id=b.writer_work_id
    JOIN public.messages msg ON msg.id=b.message_id AND msg.kind='fato' AND msg.recipient_user IS NULL AND msg.body=wr.result->>'text'
    JOIN mission_generic_owner.unified_segment_publications_v4 pub ON pub.work_id=wr.id AND pub.message_id=msg.id
    WHERE b.decision_work_id=child.id AND b.source_window_id=cs.id AND b.master_session_id=rdw.master_session_id
     AND b.state='published' AND b.published_at IS NOT NULL AND wr.state='completed' AND wr.message_id=b.message_id
     AND cs.consumed_message_id=b.message_id AND child.state='completed';
  END IF;
  RETURN jsonb_build_object('schema_version','mission-director-incomplete-reissue-proof/1','old_work_id',rdw.id,
   'master_session_id',rdw.master_session_id,'owner_user_id',prep->>'owner_user_id','can_reissue',false,'source_released',true,
   'successor_work_id',prep->>'successor_work_id','issued',aud IS NOT NULL,'published',publication IS NOT NULL,'publication',publication,
   'prepared_sha256',public.combat_v2_sha256(prep),'audit_sha256',CASE WHEN aud IS NOT NULL THEN public.combat_v2_sha256(aud) ELSE NULL END);
 END IF;
 -- Current authority only participates before the single explicit reissue, never in historical lineage.
 IF p_user IS NULL OR p_user::text IS DISTINCT FROM rdo->>'actor_user_id' OR mission_generic_owner.manual_staff_template_policy_v1(rdw.master_session_id) IS NULL THEN RETURN NULL;END IF;
 SELECT rr.canonical_preimage::jsonb#>'{config,c1266_director_incomplete_recovery}' INTO cfg
 FROM mission_factory_owner.editor_release_readiness rr WHERE rr.singleton AND rr.scope='staff' AND rr.state='enabled'
  AND rr.revision_sha256=rr.observed_revision_sha256 AND rr.revision_sha256=encode(extensions.digest(convert_to(rr.canonical_preimage,'UTF8'),'sha256'),'hex');
 IF cfg->>'schema_version' IS DISTINCT FROM 'c1266-director-incomplete-recovery/1' OR cfg->'enabled' IS DISTINCT FROM 'true'::jsonb
 OR cfg->>'old_work_id' IS DISTINCT FROM rdw.id::text OR cfg->>'master_session_id' IS DISTINCT FROM rdw.master_session_id::text
 OR cfg->>'old_payload_sha256' IS DISTINCT FROM rdw.payload_sha256 OR cfg->>'raw_sha256' IS DISTINCT FROM rdr.raw_sha256
 OR cfg->'max_successors' IS DISTINCT FROM '1'::jsonb OR cfg->'target_output_tokens' IS DISTINCT FROM '32000'::jsonb
 OR (cfg->>'successor_work_id'~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$') IS DISTINCT FROM true
 OR rdu.superseded_at IS NOT NULL OR rdu.consumed_message_id IS NOT NULL
 OR NOT EXISTS(SELECT 1 FROM public.master_v2_sessions m JOIN public.locations l ON l.id=m.location_id
  JOIN public.mission_run_state r ON r.master_session_id=m.id WHERE m.id=rdw.master_session_id AND m.closed_at IS NULL AND m.suspended_at IS NULL
  AND m.owner_kind='ai_service' AND l.id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND l.is_test AND l.is_active
  AND r.run_phase='in_corso' AND r.current_step_key=rdw.step_key AND r.control_version=rdw.run_control_version)
 OR rdu.context->>'source_revision' IS DISTINCT FROM mission_generic_owner.role_source_revision_v1(rdw.master_session_id)
 OR EXISTS(SELECT 1 FROM unnest(rdu.role_ids) rid WHERE NOT EXISTS(SELECT 1 FROM mission_generic_owner.role_latest_v1(rdw.master_session_id) lr WHERE lr.message_id=rid AND lr.valid))
 OR EXISTS(SELECT 1 FROM mission_generic_owner.work_items newer WHERE newer.master_session_id=rdw.master_session_id AND (newer.created_at>rdw.created_at OR newer.state NOT IN('completed','failed')))
 OR EXISTS(SELECT 1 FROM mission_generic_owner.unified_batches b WHERE b.decision_work_id=rdw.id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_sessions c WHERE c.master_session_id=rdw.master_session_id AND c.closed_at IS NULL)
 OR EXISTS(SELECT 1 FROM mission_generic_owner.work_items collision WHERE collision.id=(cfg->>'successor_work_id')::uuid)
 THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('schema_version','mission-director-incomplete-reissue-proof/1','old_work_id',rdw.id,
  'master_session_id',rdw.master_session_id,'owner_user_id',p_user,'can_reissue',true,'source_released',false,
  'successor_work_id',cfg->>'successor_work_id','issued',false,'published',false,
  'raw_output_receipt_id',rdr.id,'raw_sha256',rdr.raw_sha256,'source_window_id',rdu.id,'source_revision',rdu.context->>'source_revision');
END $function$;
REVOKE ALL ON FUNCTION mission_generic_owner.director_incomplete_reissue_proof_v1(uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION mission_generic_owner.director_incomplete_reissue_v1(p_work uuid,p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE w mission_generic_owner.work_items;sw mission_generic_owner.unified_source_windows;ch mission_generic_owner.work_items;cs mission_generic_owner.unified_source_windows;
 p jsonb;prep jsonb;issued jsonb;res jsonb;rootsha text;
BEGIN
 PERFORM mission_ai_board_owner.service_only();
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0));
 SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work;
 PERFORM mission_generic_owner.dispatch_user(w.master_session_id,p_user);
 PERFORM 1 FROM mission_generic_owner.role_window_cursors WHERE master_session_id=w.master_session_id FOR UPDATE NOWAIT;
 PERFORM public.master_v2_lock_scope(w.master_session_id);
 SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work FOR UPDATE NOWAIT;
 SELECT * INTO STRICT sw FROM mission_generic_owner.unified_source_windows WHERE id=w.authority_receipt_id AND work_id=w.id FOR UPDATE NOWAIT;
 p:=mission_generic_owner.director_incomplete_reissue_proof_v1(w.id,p_user);
 IF p IS NULL OR p->>'owner_user_id' IS DISTINCT FROM p_user::text THEN RAISE EXCEPTION 'DIRECTOR50_PROOF_REJECTED' USING ERRCODE='42501';END IF;
 IF p->'issued'='true'::jsonb THEN
  SELECT * INTO STRICT ch FROM mission_generic_owner.work_items WHERE id=(p->>'successor_work_id')::uuid;
 ELSE
  IF p->'can_reissue' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'DIRECTOR50_NOT_REISSUABLE' USING ERRCODE='42501';END IF;
  SELECT revision_sha256 INTO STRICT rootsha FROM mission_factory_owner.editor_release_readiness WHERE singleton;
  prep:=jsonb_build_object('schema_version','mission-director-incomplete-prepared/1','master_session_id',w.master_session_id,
   'old_work_id',w.id,'old_result_sha256',w.result_sha256,'old_result_jsonb_sha256',public.combat_v2_sha256(w.result),
   'old_payload_sha256',w.payload_sha256,'raw_output_receipt_id',p->>'raw_output_receipt_id','raw_sha256',p->>'raw_sha256',
   'source_window_id',sw.id,'source_before_sha256',public.combat_v2_sha256(to_jsonb(sw)-'superseded_at'-'superseded_reason'),
   'source_revision',sw.context->>'source_revision','role_ids_sha256',public.combat_v2_sha256(to_jsonb(sw.role_ids)),
   'owner_user_id',p_user,'successor_work_id',p->>'successor_work_id','fixed_release_sha256',rootsha);
  INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
   VALUES(w.dispatch_receipt_id,'staff_director_incomplete_prepared_v1',prep);
  UPDATE mission_generic_owner.unified_source_windows SET superseded_at=clock_timestamp(),superseded_reason='staff_failed_director_incomplete_retry'
   WHERE id=sw.id AND work_id=w.id AND superseded_at IS NULL AND consumed_message_id IS NULL AND source_sha256=w.payload_sha256;
  IF NOT FOUND OR mission_generic_owner.role_source_released_v4(sw.id) IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'DIRECTOR50_SOURCE_RELEASE_CAS' USING ERRCODE='40001';END IF;
  res:=mission_generic_owner.unified_enqueue_director(w.master_session_id);
  IF res->>'work_id' IS DISTINCT FROM p->>'successor_work_id' OR res->>'state' IS DISTINCT FROM 'director_ready' THEN
   RAISE EXCEPTION 'DIRECTOR50_ENQUEUE_REJECTED' USING ERRCODE='40001';END IF;
  SELECT * INTO STRICT ch FROM mission_generic_owner.work_items WHERE id=(p->>'successor_work_id')::uuid;
  SELECT * INTO STRICT cs FROM mission_generic_owner.unified_source_windows WHERE id=ch.authority_receipt_id AND work_id=ch.id;
  IF cs.role_ids IS DISTINCT FROM sw.role_ids OR cs.context->>'source_revision' IS DISTINCT FROM sw.context->>'source_revision'
   OR ch.step_key IS DISTINCT FROM w.step_key OR ch.run_control_version IS DISTINCT FROM w.run_control_version
   OR ch.definition_sha256 IS DISTINCT FROM w.definition_sha256 OR ch.kind IS DISTINCT FROM 'director' OR ch.state IS DISTINCT FROM 'ready'
   OR ch.master_session_id IS DISTINCT FROM w.master_session_id OR ch.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(ch.payload)
  THEN RAISE EXCEPTION 'DIRECTOR50_COHORT_DRIFT' USING ERRCODE='40001';END IF;
  issued:=jsonb_build_object('schema_version','mission-director-incomplete-reissued/1','old_work_id',w.id,
   'prepared_sha256',public.combat_v2_sha256(prep),'successor_work_id',ch.id,'successor_payload_sha256',ch.payload_sha256,
   'successor_source_sha256',public.combat_v2_sha256(to_jsonb(cs)-'consumed_message_id'));
  INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
   VALUES(w.dispatch_receipt_id,'staff_director_incomplete_reissued_v1',issued);
  p:=mission_generic_owner.director_incomplete_reissue_proof_v1(w.id,p_user);
  IF p->'issued' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'DIRECTOR50_LINEAGE_INVALID' USING ERRCODE='40001';END IF;
 END IF;
 RETURN jsonb_build_object('schema_version','mission-director-incomplete-reissue-result/1','old_work_id',w.id,'successor_work_id',ch.id,
  'request',jsonb_build_object('schema_version','mission-generic-request/1','master_session_id',ch.master_session_id,
   'event_id',ch.event_id,'request_key',ch.request_key,'expected_revision',ch.revision),'audit_sha256',p->>'audit_sha256');
END $function$;
REVOKE ALL ON FUNCTION mission_generic_owner.director_incomplete_reissue_v1(uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;

COMMIT;

CREATE OR REPLACE FUNCTION mission_generic_owner.unified_advance(p_session uuid, p_user uuid, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ub mission_generic_owner.unified_batches;ee mission_generic_owner.encounters;rr public.combat_v2_rounds;rw mission_generic_owner.unified_round_windows;
ca uuid;res jsonb;bid uuid;newreport uuid;newround uuid;oldround public.combat_v2_rounds;terminal_route jsonb;nextctx jsonb;
begin

select candidate.* into ub from mission_generic_owner.unified_batches candidate
where candidate.master_session_id=p_session and candidate.state<>'published'
  and not mission_generic_owner.role_source_released_v4(candidate.source_window_id)
for update of candidate;

 if ub.state='needs_review' then return mission_generic_owner.progress_result(p_session,p_user,'needs_review');end if;
 if ub.id is not null then
  -- Only native protected Staff or admitted public mission authority may prepare a private successor.
  -- The round-init trigger binds the PNG cohort to this same batch; player
  -- commands and projections remain behind unified_round_windows.publication_id.
  if ub.state='preparing' and ub.entry_side='png' and ub.next_round_id is null
    and ub.source_window_id is null and ub.source_report_id is not null
    and ub.route is null and (exists(
      select 1 from mission_generic_owner.flow_staff_sessions fs
      join public.master_v2_sessions ms on ms.id=fs.master_session_id
      join public.locations loc on loc.id=ms.location_id
      where fs.master_session_id=p_session and fs.enabled
        and ms.owner_kind='ai_service' and ms.closed_at is null and loc.is_test) OR mission_public_owner.ai_resource_scope_v1(p_session,ub.encounter_id))
  then
    select * into strict oldround from public.combat_v2_rounds
      where id=ub.source_round_id and session_id=ub.encounter_id
        and state='risolto' for update;
    if not exists(select 1 from public.combat_v2_round_reports rep
        where rep.id=ub.source_report_id and rep.round_id=oldround.id
          and rep.narration_state='attesa')
      or exists(select 1 from public.combat_v2_rounds successor
        where successor.session_id=oldround.session_id
          and successor.round_no=oldround.round_no+1)
    then raise exception 'MUF_PRIVATE_SUCCESSOR_DRIFT' using errcode='40001';end if;
    update public.combat_v2_rounds
      set staff_private_successor_source=true
      where id=oldround.id and state='risolto'
        and staff_private_successor_source=false;
    if not found then raise exception 'MUF_PRIVATE_SOURCE_MARKER_DRIFT' using errcode='40001';end if;
    insert into public.combat_v2_rounds(session_id,round_no,evaluation_mode)
      values(oldround.session_id,oldround.round_no+1,oldround.evaluation_mode)
      returning id into newround;
    update mission_generic_owner.unified_batches
      set next_round_id=newround where id=ub.id and next_round_id is null;
    if not found or not exists(select 1 from mission_generic_owner.unified_round_windows private_window
        where private_window.round_id=newround and private_window.batch_id=ub.id and private_window.side='png'
          and private_window.publication_id is null)
    then raise exception 'MUF_PRIVATE_SUCCESSOR_BINDING' using errcode='40001';end if;
    select * into strict ub from mission_generic_owner.unified_batches where id=ub.id;
  end if;
  if ub.next_round_id is not null and ub.entry_side='png' then
   select aa into ca from mission_generic_owner.unified_round_windows ww cross join unnest(ww.expected_actor_ids) aa
   where ww.round_id=ub.next_round_id and not exists(select 1 from public.combat_v2_declarations dd where dd.round_id=ww.round_id
   and dd.actor_id=aa and exists(select 1 from combat_panel_private.actor_turns mt where mt.round_id=ww.round_id and mt.actor_id=aa and mt.main_declaration_id=dd.id)) order by aa limit 1;
   if ca is not null then res:=mission_generic_owner.enqueue_choice(p_session,ub.encounter_id,ca);return mission_generic_owner.progress_result(p_session,p_user,'choice_ready');end if;
  end if;
  if ub.next_round_id is not null and ub.entry_side='png' and not exists(select 1 from public.combat_v2_attack_targets at where at.round_id=ub.next_round_id) then
   if ub.source_window_id is not null and ub.composition_kind='entry_png' and ub.decision->>'schema_version'='mission-director-proposal/2'
   then raise exception 'MNE_ENTRY_OFFENSE_MISSING' using errcode='55000';end if;
   select * into strict oldround from public.combat_v2_rounds where id=ub.next_round_id;
   insert into mission_generic_owner.unified_preparation_permits(round_id,batch_id,transaction_id,backend_pid) values(oldround.id,ub.id,txid_current(),pg_backend_pid());
   res:=public.combat_v2_round_resolve(oldround.id,mission_ai_service_owner.uuid5(oldround.id,'generic-resolve'));
   newreport:=(res#>>'{data,report_id}')::uuid;
   if newreport is null then raise exception 'MUF_NONOFFENSIVE_REPORT_MISSING';end if;
   if ub.source_report_id is null then
    update mission_generic_owner.unified_batches set source_report_id=newreport,source_round_id=oldround.id,entry_side='pg',composition_kind='combat_resolved_no_pending' where id=ub.id;
   else
    update mission_generic_owner.unified_batches set secondary_report_id=newreport,entry_side='pg',composition_kind='combat_resolved_no_pending' where id=ub.id;
   end if;
   perform mission_generic_owner.apply_surrender_if_due(p_session,oldround.id);
   terminal_route:=mission_generic_owner.unified_terminal_route(p_session,oldround.session_id);
   if terminal_route is not null then
    nextctx:=mission_generic_owner.narrative_context(p_session,terminal_route->>'to_step_key',ub.id,clock_timestamp(),
      jsonb_build_object('passaggio_preparato',terminal_route->>'label',
       'accordo_pacifico_attestato',case when terminal_route->>'outcome'='peaceful'
         then terminal_route->>'agreement_summary' else null end,'nota_autorita','La rotta segue gli esiti del server; nessuna azione ulteriore dei PG è attestata.'));
    update mission_generic_owner.unified_batches set route=terminal_route,context=nextctx,composition_kind='combat_exit',entry_side=null,next_round_id=null where id=ub.id;
   else
    update mission_generic_owner.unified_batches set next_round_id=null where id=ub.id;
   end if;
  end if;
  if ub.entry_side='png' and ub.next_round_id is not null
    and ub.source_report_id is not null and ub.source_window_id is null
    and exists(select 1 from public.combat_v2_attack_targets target
      where target.round_id=ub.next_round_id)
  then
    update mission_generic_owner.unified_batches
      set composition_kind='combat_resolved_then_png_offensive'
      where id=ub.id and state='preparing';
    if not found then raise exception 'MUF_OFFENSE_BATCH_STATE' using errcode='40001';end if;
  end if;
  res:=mission_generic_owner.unified_enqueue_writer(ub.id);return mission_generic_owner.progress_result(p_session,p_user,'narration_ready');
 end if;
 select ge.* into ee from mission_generic_owner.encounters ge join public.combat_v2_sessions cs on cs.id=ge.encounter_id
 where ge.master_session_id=p_session and cs.closed_at is null;
 if ee.encounter_id is null then
  res:=mission_generic_owner.unified_enqueue_director(p_session);return mission_generic_owner.progress_result(p_session,p_user,res->>'state');
 end if;
 select * into strict rr from public.combat_v2_rounds where session_id=ee.encounter_id order by round_no desc limit 1 for update;
 select * into rw from mission_generic_owner.unified_round_windows where round_id=rr.id;
 if rw.round_id is null then return null;end if; -- Existing Generic encounters keep their already opened cadence.
 if rr.state='risolto' then bid:=mission_generic_owner.unified_prepare_resolved(p_session,rr.id);return mission_generic_owner.unified_advance(p_session,p_user,p_request);end if;
 if rw.publication_id is null then raise exception 'MUF_WINDOW_WITHOUT_PUBLICATION_BATCH';end if;
 if rr.phase='raccolta_azioni' then
  if exists(select 1 from unnest(rw.expected_actor_ids) ai join public.combat_v2_actors aa on aa.id=ai where aa.actor_kind='pg'
   and not exists(select 1 from public.combat_v2_declarations dd where dd.round_id=rr.id and dd.actor_id=ai and exists(select 1 from combat_panel_private.actor_turns mt where mt.round_id=rr.id and mt.actor_id=ai and mt.main_declaration_id=dd.id)))
  then return mission_generic_owner.progress_result(p_session,p_user,'waiting_player');end if;
  select ai into ca from unnest(rw.expected_actor_ids) ai join public.combat_v2_actors aa on aa.id=ai where aa.actor_kind='png'
   and not exists(select 1 from public.combat_v2_declarations dd where dd.round_id=rr.id and dd.actor_id=ai and exists(select 1 from combat_panel_private.actor_turns mt where mt.round_id=rr.id and mt.actor_id=ai and mt.main_declaration_id=dd.id)) order by ai limit 1;
  if ca is not null then res:=mission_generic_owner.enqueue_choice(p_session,ee.encounter_id,ca);return mission_generic_owner.progress_result(p_session,p_user,'choice_ready');end if;
 end if;
 if rr.phase='raccolta_difese' then
  select aa.id into ca from public.combat_v2_actors aa where aa.session_id=ee.encounter_id and aa.actor_kind='png' and aa.state='attivo'
   and exists(select 1 from public.combat_v2_attack_targets tt where tt.round_id=rr.id and tt.target_actor_id=aa.id
    and not exists(select 1 from public.combat_v2_defense_coverages cc where cc.attack_target_id=tt.id)) order by aa.id limit 1;
  if ca is not null then res:=mission_generic_owner.enqueue_choice(p_session,ee.encounter_id,ca);return mission_generic_owner.progress_result(p_session,p_user,'choice_ready');end if;
 end if;
 if (select count(*) from combat_panel_private.actor_turns mt where mt.round_id=rr.id and mt.actor_id=any(rw.expected_actor_ids) and mt.main_declaration_id is not null)<>cardinality(rw.expected_actor_ids)
 then return mission_generic_owner.progress_result(p_session,p_user,'waiting_player');end if;
 if not combat_v2_multitarget_internal.round_complete(rr.id) then return mission_generic_owner.progress_result(p_session,p_user,'waiting_defense');end if;
 if rr.evaluation_mode<>'neutra' and exists(select 1 from public.combat_v2_declarations dd join public.combat_v2_actors aa on aa.id=dd.actor_id
 where dd.round_id=rr.id and aa.actor_kind='pg' and dd.kind in('attacco','difesa') and not exists(select 1 from public.combat_v2_ratings rt where rt.declaration_id=dd.id and rt.is_active))
 then return mission_generic_owner.progress_result(p_session,p_user,'waiting_quality');end if;
 if (select ll.is_test from public.locations ll join public.master_v2_sessions mm on mm.location_id=ll.id where mm.id=p_session)
 and (public.combat_v2_values_written(ee.encounter_id) or not combat_panel_private.uses_simulated_pools(ee.encounter_id)) then raise exception 'MUF_SIMULATION_SCOPE' using errcode='42501';end if;
 res:=public.combat_v2_round_resolve(rr.id,mission_ai_service_owner.uuid5(rr.id,'generic-resolve'));
 bid:=mission_generic_owner.unified_prepare_resolved(p_session,rr.id);
 return mission_generic_owner.unified_advance(p_session,p_user,p_request);
end $function$

CREATE OR REPLACE FUNCTION public.mission_generic_event_next_v1(p_event_key uuid, p_event_version bigint, p_claim_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '20s'
AS $function$
DECLARE e mission_generic_owner.event_outbox_v1;cfg jsonb;progress jsonb;candidate jsonb;flow jsonb;writer46 jsonb;
 event43_observed_work uuid:=NULL;event43_observed_request jsonb:=NULL;
 writer48_source_work mission_generic_owner.work_items;writer48_terminal_event mission_generic_owner.event_outbox_v1;
 writer48_source_request jsonb;writer48_event_after jsonb;writer48_child_request jsonb:=NULL;writer48_child_id uuid:=NULL;
 w mission_generic_owner.work_items;req uuid;outcome text;native_claim jsonb;role_source_user uuid;native_mode text;paid_action boolean:=false;
BEGIN
 PERFORM mission_ai_board_owner.service_only();
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0));
 SELECT * INTO e FROM mission_generic_owner.event_outbox_v1 WHERE event_key=p_event_key AND event_version=p_event_version FOR UPDATE;
 IF NOT FOUND OR e.claim_id IS DISTINCT FROM p_claim_id OR p_claim_id IS NULL OR e.claimed_at IS NULL
 THEN RAISE EXCEPTION 'EVENT42_CLAIM_REJECTED' USING ERRCODE='42501'; END IF;
 IF e.next_result IS NOT NULL THEN RETURN jsonb_set(jsonb_set(jsonb_set(e.next_result,'{state}','"uncertain"'::jsonb),'{request}','null'::jsonb),'{native_claim}','null'::jsonb); END IF;
 IF e.state<>'running' OR e.claim_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'EVENT42_CLAIM_EXPIRED' USING ERRCODE='42501';END IF;
 SELECT rr.canonical_preimage::jsonb#>'{config,c1266_server_events}' INTO cfg
 FROM mission_factory_owner.editor_release_readiness rr
 WHERE rr.singleton AND rr.state='enabled' AND rr.scope='staff'
 AND rr.revision_sha256=rr.observed_revision_sha256;
 IF cfg->>'schema_version' IS DISTINCT FROM 'c1266-server-events/1'
 OR cfg->'enabled' IS DISTINCT FROM 'true'::jsonb THEN
 RAISE EXCEPTION 'EVENT42_MODE_DISABLED' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.master_v2_sessions m JOIN public.locations l ON l.id=m.location_id
 WHERE m.id=e.master_session_id AND m.owner_kind='ai_service' AND m.master_user IS NULL
 AND m.closed_at IS NULL AND m.suspended_at IS NULL AND m.stato IN('preparazione','in_corso')
