 RETURN jsonb_build_object('schema_version','mission-generic-provider-input/6','input_tokens_limit',24000,'policy_version',2,'http_calls_per_generation',2,'scope',scope,'pricing',jsonb_build_object('model','gpt-6-luna','reasoning_effort','high','store',false,'max_output_tokens',extension_output,'input_usd_million',0.1,'output_usd_million',0.5,'count_upper_cost_usd',extension_upper,'generation_upper_cost_usd',extension_upper),'byte_bounds',jsonb_build_object('max_input_bytes',max_input,'max_request_bytes',max_request));END IF;
 RETURN jsonb_build_object('schema_version','mission-generic-provider-input/5','input_tokens_limit',24000,'policy_version',2,'http_calls_per_generation',2,
  'scope',scope,'pricing',jsonb_build_object('model','gpt-6-luna','reasoning_effort','high','store',false,'max_output_tokens',extension_output,
   'input_usd_million',0.1,'output_usd_million',0.5,'count_upper_cost_usd',extension_upper,'generation_upper_cost_usd',extension_upper),
  'byte_bounds',jsonb_build_object('max_input_bytes',max_input,'max_request_bytes',max_request));
END $function$

CREATE OR REPLACE FUNCTION mission_generic_owner.c7_run_budget_v1(p_session uuid, p_next boolean, p_current_work uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare named47 boolean:=false;a mission_generic_owner.dispatch_admissions;g mission_generic_owner.provider_policy;
 pol mission_narrative_internal.runtime_policy;spent numeric;calls bigint;bound numeric;capcost numeric;capcalls integer;ok boolean;scene_policy jsonb;
