                            (2,CASE WHEN iw.id='4fb5ea83-f90a-4b76-a6f5-722641d9da43'::uuid THEN 0.0184::numeric ELSE 0.0124::numeric END)) phase(call_no,bound)
   WHERE iw.master_session_id IN(p_session,'1fb789a2-0319-435f-9f6d-dd517cac7cd3'::uuid) AND iw.state IN('claimed','authorized','provider_started')
    AND NOT EXISTS(SELECT 1 FROM staff_ai_quota_private.calls q WHERE q.producer='mission_generic_ai' AND q.scope_id=iw.master_session_id
      AND q.source_id=iw.dispatch_receipt_id AND q.call_no=phase.call_no AND q.state<>'no_http');
   b50_new:=CASE WHEN p_next AND p_current_work IS NULL THEN 0.0368 ELSE 0 END;
   IF (p_next AND clock_timestamp()>='2026-10-27 20:47:00Z'::timestamptz)
