 AND sticky_wc.contract_sha256=public.combat_v2_sha256(sticky_wc.contract)
 AND sticky_wc.contract->>'schema_version'='mission-narrative-admission/3'
 AND sticky_wc.contract->'features' ? 'execution_authority_v1'
 AND (sticky_wc.contract#>>'{source_attestation,execution_authority,schema_version}'='c1266-work-execution-attestation/1' OR ((sticky_wc.historical_proof->>'schema_version'='c1266-work-execution-attestation/2') AND sticky_wc.contract#>'{source_attestation,execution_authority}'=sticky_wc.historical_proof))
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,execution_context}'='staff_mission'
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,admission,kind}'='staff_finite'
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,admission,resource_scope}'='staff_simulation'
 AND (sticky_wc.contract#>>'{source_attestation,execution_authority,source_scope,mission_id}'='5878822d-dc03-4ac2-ad0b-1547f0ab3fc0' OR ((sticky_wc.historical_proof->>'schema_version'='c1266-work-execution-attestation/2') AND sticky_wc.contract#>'{source_attestation,execution_authority}'=sticky_wc.historical_proof))
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,release_sha256}'=sticky_wc.release_sha256
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,binding_sha256}'=sticky_wc.definition_sha256) OR EXISTS(SELECT 1 FROM mission_generic_owner.simulation_sources ss21
 JOIN mission_generic_owner.board_starts bs21 ON bs21.request_key=ss21.request_key
 JOIN mission_generic_owner.start_claims sc22 ON sc22.session_id=bs21.master_session_id
 JOIN mission_generic_owner.run_bindings rb21 ON rb21.master_session_id=bs21.master_session_id
 JOIN public.master_v2_sessions ms21 ON ms21.id=bs21.master_session_id
  AND ms21.mission_id=ss21.carrier_mission_id
 WHERE NOT EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 manual_source WHERE manual_source.master_session_id=bs21.master_session_id) AND bs21.master_session_id=p_session
 AND ms21.owner_kind='ai_service' AND ms21.master_user IS NULL
 AND ms21.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
 AND (ss21.source_mission_id='5878822d-dc03-4ac2-ad0b-1547f0ab3fc0'::uuid OR (mission_generic_owner.c1266_staff_source_scope_v1(bs21.master_session_id) IS NOT NULL AND ss21.source_mission_id::text=mission_generic_owner.c1266_staff_source_scope_v1(bs21.master_session_id)#>>'{source_scope,mission_id}'))
 AND sc22.state='bound' AND sc22.simulation
 AND sc22.mission_id=ms21.mission_id AND sc22.location_id=ms21.location_id
 AND sc22.request_key=bs21.request_key
 AND bs21.simulation AND bs21.snapshot->'simulation'='true'::jsonb
 AND bs21.snapshot_sha256=mission_internal.fingerprint(bs21.snapshot)
 AND bs21.snapshot->>'schema_version'='mission-generic-opening-source/1'
 AND bs21.snapshot->>'mission_id'=ss21.carrier_mission_id::text
 AND bs21.snapshot->>'location_id'='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'
 AND rb21.snapshot_sha256=mission_internal.fingerprint(rb21.snapshot)
 AND rb21.snapshot->>'schema_version'='mission-generic-run/1'));
 IF campaign_scope THEN
 SELECT canonical_preimage INTO root_text FROM mission_factory_owner.editor_release_readiness WHERE singleton;
 campaign:=root_text::jsonb#>'{config,c1266_staff_campaign}';clean_policy:=root_text::jsonb#>'{config,c1266_clean_staff}';
 named47:=coalesce((campaign='{"maxGen":17,"maxUSD":"0.4216","maxHTTP":34,"grant_id":"b925043a-c1b3-434b-8fb4-f335903b2af0","maxCount":17,"residual":{"gen":17,"usd":"0.4395760","http":34,"count":17},"max_pairs":17,"expires_at":"2026-10-20T15:12:18.393948+00:00","not_before":"2026-10-20T14:12:18.393948+00:00","campaign_id":"b2fc5e28-072b-41f2-8dd8-cb5a35a13092","location_id":"0b85f354-9cdb-47e1-baf9-3d266bb7e06b","work_seconds":360,"schema_version":"c1266-staff-campaign/2","cleanup_seconds":360,"history_baseline":{"gen":33,"usd":"0.5524240","http":69,"count":36},"history_scope_ids":["0b1fa6b5-d9c4-4ea3-9ec8-76b1b21e0a0a","21fb8bf3-1df9-4bbf-b2d6-cf7b003b8f30","a853d33f-eecf-484b-b85c-5dc12c25d080","d25d886e-e4f8-4cfe-b8f2-729e96f355d7","c21baa1a-cdac-4401-9131-493eef208a21","780bc131-229e-4142-b1f9-4c6a39b6d070","ef12969b-0958-473c-9016-53052af9d579","2067ace7-c975-4e6c-a621-f82ac23ed18d","6c8d9647-b0de-4c2c-a7e0-6c4a6239ee86","41ec7f9e-9c2c-4476-be14-3ba57a573bc5","8b814fa7-fcdb-4035-9ddb-5bea247aeb36"],"time_policy":{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}}'::jsonb AND clean_policy='{"grant_id":"b925043a-c1b3-434b-8fb4-f335903b2af0","expires_at":"2026-10-20T15:12:18.393948+00:00","not_before":"2026-10-20T14:12:18.393948+00:00","location_id":"0b85f354-9cdb-47e1-baf9-3d266bb7e06b","source_sha256":"eca0639f48346ed0c1fac786c136f557920b61310c38d85f22a5e6a7837231bd","schema_version":"c1266-clean-staff-admission-policy/2","source_mission_id":"5878822d-dc03-4ac2-ad0b-1547f0ab3fc0","source_plan_version_id":"24b1e44a-5597-4fb0-95bd-fb13647764b2","c7_budget_qualification":{"model":"gpt-6-luna","store":false,"http_limit":28,"schema_version":"c1266-clean-staff-budget-qualification/1","generation_limit":14,"reasoning_effort":"high","input_usd_million":0.1,"input_tokens_limit":24000,"output_usd_million":0.5,"output_tokens_limit":20000,"count_upper_cost_usd":"0.0124","scene_cost_budget_usd":"0.3136","generation_upper_cost_usd":"0.0124","count_qualification_sha256":"d8da6486b29f5e6b57272eb9d21660518cdcb57f12ed69209e12f32c37e2d5c0","count_reserve_contract_sha256":"13421de48d6dddbb8c6628fd6a294b90746b3d2b79e56bf617456a5d3cc8e090"},"c7_budget_qualification_sha256":"39af421ce9035831c695f0c8d8bc8157cdfd09918b8b81072433e9031b248959","campaign_id":"b2fc5e28-072b-41f2-8dd8-cb5a35a13092","time_policy":{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}}'::jsonb),false);
 clean_policy:=coalesce(mission_generic_owner.c1266_staff_clean_policy_v1(p_session,clean_policy),clean_policy);
 END IF;
 IF EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 ma WHERE ma.master_session_id=p_session) AND (a.c7_budget_enforced IS DISTINCT FROM TRUE OR mission_generic_owner.manual_staff_scope_v1(p_session) IS NULL) THEN RAISE EXCEPTION 'MANUAL_STAFF_C7_UNQUALIFIED' USING ERRCODE='42501';END IF;
 if NOT campaign_scope AND not a.c7_budget_enforced then return jsonb_build_object('enforced',false,'allowed',true,'remaining_calls',a.call_limit-a.calls_authorized);end if;
 if NOT campaign_scope AND (a.c7_budget_qualification_sha256 is null or a.call_limit<1 or a.cost_budget_usd<=0)
 then raise exception 'MGPG_C7_BUDGET_UNQUALIFIED' using errcode='55000';end if;
 IF p_session='ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid AND mission_generic_owner.c8_context24_scope_v1('48e1bdcd-f044-be8c-1923-54d38e7e822c'::uuid) THEN pol.max_input_tokens:=24000;pol.max_output_tokens:=20000;END IF;
 IF NOT campaign_scope AND mission_generic_owner.c1266_opening_named_v1(p_session) THEN
  IF mission_generic_owner.c1266_execution_authority_v1(p_session,false,true) IS NULL THEN RAISE EXCEPTION 'C1266_C7_AUTHORITY_CLOSED' USING ERRCODE='42501';END IF;
  pol.max_input_tokens:=24000;pol.max_output_tokens:=20000;
 ELSIF NOT campaign_scope AND mission_generic_owner.c1266_clean_staff_admission_v1(p_session,true,true) IS NOT NULL THEN pol.max_input_tokens:=24000;pol.max_output_tokens:=20000;END IF;
 IF campaign_scope THEN pol.max_input_tokens:=24000;pol.max_output_tokens:=20000;END IF;
 scene_policy:=mission_generic_owner.c1266_staff_scene_policy_v1(p_session);
 bound:=(pol.max_input_tokens*pol.input_usd_million+pol.max_output_tokens*pol.output_usd_million)/1000000;
 budget1_effective:=mission_generic_owner.effective_admission_usd_cap_v1(p_session);
 budget1_policy:=CASE WHEN p_session='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND a.cost_budget_usd=0.3136::numeric AND budget1_effective=1.00::numeric THEN greatest(g.run_budget_usd,budget1_effective) ELSE g.run_budget_usd END;
 capcost:=least(budget1_policy,budget1_effective,coalesce(pol.run_budget_usd,budget1_policy));
 capcalls:=2*least(g.max_run_calls,a.call_limit);
 -- A claimed Native work is already a logical reservation, even before reserve HTTP.
 -- Its bound is represented by existing work state; a receipt/attempt is not counted twice.
 select coalesce(sum(case when d.status in('success','fallback','unknown_billable')
   then coalesce(d.charged_cost_usd,d.upper_bound_cost_usd,0)
   when wi.state in('claimed','authorized','provider_started') then greatest(coalesce(d.upper_bound_cost_usd,0),bound)
   else coalesce(d.upper_bound_cost_usd,0) end + case when ca.details is not null then (ca.details->>'count_upper_cost_usd')::numeric when wi.state in('claimed','authorized','provider_started') then coalesce(a.c8_count_upper_cost_usd,0) else 0 end),0),
 coalesce(sum(case when wi.state in('claimed','authorized','provider_started') then 2 else (case when ca.details is not null then 1 else 0 end)+(case when d.upper_bound_cost_usd is not null or exists(select 1 from mission_narrative_internal.dispatch_attempts da where da.receipt_id=d.id) then 1 else 0 end) end),0)
 into spent,calls from mission_generic_owner.work_items wi
 left join mission_narrative_internal.dispatch_receipts d on d.id=wi.dispatch_receipt_id
 left join mission_narrative_internal.dispatch_audit ca on ca.receipt_id=d.id and ca.event_code='c8_count_started'
 where wi.master_session_id=p_session and (p_current_work is null or wi.id<>p_current_work)
 and (wi.dispatch_receipt_id is not null or wi.state in('claimed','authorized','provider_started'));
 calls:=greatest(calls,a.calls_authorized-case when p_current_work is not null and exists(
  select 1 from mission_generic_owner.work_items wi where wi.id=p_current_work and wi.authorization_id is not null) then 1 else 0 end);
 ok:=a.enabled and g.enabled and a.c8_count_qualification_sha256 is not null and a.c8_count_upper_cost_usd is not null and bound>=0 and bound<'Infinity'::numeric and (scene_policy IS NOT NULL OR (capcost>0 and (mission_generic_owner.manual_staff_count_limit_v1(p_session)='none' OR capcalls>0)
