 and (mission_generic_owner.manual_staff_count_limit_v1(p_session)='none' OR calls+case when p_next then 2 else 0 end<=capcalls)));
 IF EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 ma WHERE ma.master_session_id=p_session) THEN
  IF p_current_work IS NOT NULL THEN
   SELECT * INTO own_work FROM mission_generic_owner.work_items WHERE id=p_current_work;
   IF own_work.master_session_id IS DISTINCT FROM p_session OR own_work.state NOT IN('claimed','authorized','provider_started')
    OR own_work.lease_id IS NULL OR own_work.lease_expires_at IS NULL OR own_work.lease_expires_at<=clock_timestamp()+interval '20 seconds'
   THEN RETURN jsonb_build_object('enforced',true,'allowed',false,'remaining_calls',0,'reason_code','MANUAL_STAFF_LEASE_CLOSED');END IF;
  END IF;
  ok:=coalesce(ok,false) AND mission_academy_owner.staff_carrier_runtime(p_session)
   AND (scene_policy IS NOT NULL OR (capcost>0 AND (mission_generic_owner.manual_staff_count_limit_v1(p_session)='none' OR capcalls>0)
   AND spent+CASE WHEN p_next OR p_current_work IS NOT NULL THEN bound+a.c8_count_upper_cost_usd ELSE 0 END<=capcost
   AND (mission_generic_owner.manual_staff_count_limit_v1(p_session)='none' OR calls+CASE WHEN p_next OR p_current_work IS NOT NULL THEN 2 ELSE 0 END<=capcalls)));
 END IF;
 IF campaign_scope THEN
  -- Staff campaign is an additional finite authority, never an ordinary policy rewrite.
  -- Existing admission row is already locked; all three boundaries use work/session
  -- then admission, and Gen takes quota runtime only AFTER this check.
  SELECT * INTO STRICT rr FROM mission_factory_owner.editor_release_readiness WHERE singleton;
  campaign:=rr.canonical_preimage::jsonb#>'{config,c1266_staff_campaign}';
