    WHERE q.producer='mission_generic_ai' AND q.source_id=wi.dispatch_receipt_id AND q.scope_id=p_session AND q.call_no=1 AND q.state<>'no_http'))
  INTO hold_c,hold_g FROM mission_generic_owner.work_items wi
  WHERE wi.master_session_id=p_session AND wi.state IN('claimed','authorized','provider_started');
  new_pair:=CASE WHEN p_next AND p_current_work IS NULL THEN 1 ELSE 0 END;
  IF p_current_work IS NOT NULL THEN
   SELECT * INTO own_work FROM mission_generic_owner.work_items WHERE id=p_current_work;
   campaign_ok:=campaign_ok AND own_work.master_session_id=p_session
    AND own_work.state IN('claimed','authorized','provider_started')
    AND own_work.lease_expires_at>asof+interval '20 seconds'
    AND (named47 OR own_work.lease_expires_at<=provider_deadline);
  ELSE
   -- A non-prospective observation (progress_step with pending work) reserves nothing.
   IF p_next AND NOT named47 THEN campaign_ok:=campaign_ok AND asof+make_interval(secs=>(campaign->>'work_seconds')::integer)<provider_deadline;END IF;
  END IF;
  actual_c:=actual_c+hold_c+new_pair;actual_g:=actual_g+hold_g+new_pair;
  actual_h:=actual_h+hold_c+hold_g+2*new_pair;
  actual_usd:=actual_usd+(hold_c+hold_g+2*new_pair)*0.0124;
  IF hist_c<>(hist31->>'count')::bigint OR hist_g<>(hist31->>'gen')::bigint OR hist_h<>(hist31->>'http')::bigint OR hist_usd<>(hist31->>'usd')::numeric THEN stop_causes:=stop_causes||jsonb_build_array('HISTORICAL_LEDGER_DRIFT');END IF;
  IF asof<(campaign->>'not_before')::timestamptz THEN stop_causes:=stop_causes||jsonb_build_array('CAMPAIGN_NOT_STARTED');END IF;
  IF NOT named47 AND ((p_next OR p_current_work IS NOT NULL) AND asof>=provider_deadline) THEN stop_causes:=stop_causes||jsonb_build_array('PROVIDER_DEADLINE_REACHED');END IF;
  IF NOT named47 AND (NOT p_next AND p_current_work IS NULL AND asof>=(campaign->>'expires_at')::timestamptz) THEN stop_causes:=stop_causes||jsonb_build_array('CAMPAIGN_EXPIRED');END IF;
  IF NOT named47 AND (p_next AND p_current_work IS NULL AND asof+make_interval(secs=>(campaign->>'work_seconds')::integer)>=provider_deadline) THEN stop_causes:=stop_causes||jsonb_build_array('NEW_WORK_WINDOW_CLOSED');END IF;
  IF p_current_work IS NOT NULL AND(own_work.lease_expires_at IS NULL OR own_work.lease_expires_at<=asof+interval '20 seconds') THEN stop_causes:=stop_causes||jsonb_build_array('PHASE_LEASE_MARGIN_CLOSED');END IF;
  IF EXISTS(SELECT 1 FROM staff_ai_quota_private.calls q WHERE(q.created_at>=(campaign->>'not_before')::timestamptz OR q.sent_at>=(campaign->>'not_before')::timestamptz) AND q.scope_id<>p_session AND NOT(q.scope_id=ANY(history_ids)) AND q.state<>'no_http') THEN stop_causes:=stop_causes||jsonb_build_array('FOREIGN_ACTIVITY');END IF;
  IF (SELECT count(*) FROM mission_generic_owner.start_claims sc
    JOIN mission_generic_owner.board_starts bs ON bs.master_session_id=sc.session_id
    JOIN public.master_v2_sessions ms ON ms.id=sc.session_id
    JOIN mission_generic_owner.simulation_sources ss ON ss.carrier_mission_id=ms.mission_id
    WHERE sc.state='bound' AND sc.simulation AND sc.request_key=bs.request_key
    AND bs.created_at>=(campaign->>'not_before')::timestamptz AND (named47 OR bs.created_at<(campaign->>'expires_at')::timestamptz)
    AND ms.owner_kind='ai_service' AND ms.location_id=(campaign->>'location_id')::uuid
    AND ss.source_mission_id=(clean_policy->>'source_mission_id')::uuid)<>1 THEN stop_causes:=stop_causes||jsonb_build_array('CAMPAIGN_START_COUNT_NOT_ONE');END IF;
  IF NOT named47 AND ((campaign->>'expires_at')::timestamptz-(campaign->>'not_before')::timestamptz>(CASE WHEN fourth38 OR fifth40 OR sixth43 OR seventh46 THEN interval '60 minutes' ELSE interval '30 minutes' END)) THEN stop_causes:=stop_causes||jsonb_build_array(CASE WHEN fourth38 OR fifth40 OR sixth43 OR seventh46 THEN 'CAMPAIGN_DURATION_EXCEEDS_60_MIN' ELSE 'CAMPAIGN_DURATION_EXCEEDS_30_MIN' END);END IF;
  IF NOT(NOT EXISTS(SELECT 1 FROM staff_ai_quota_private.calls q WHERE (q.scope_id=p_session OR q.scope_id=ANY(history_ids))
    AND q.state<>'no_http' AND(q.producer<>'mission_generic_ai' OR q.call_no NOT IN(1,2)))) THEN stop_causes:=stop_causes||jsonb_build_array('UNEXPECTED_PRODUCER_OR_CALL_NO');END IF;
  IF (EXISTS(SELECT 1 FROM mission_generic_owner.start_claims sc
    JOIN mission_generic_owner.board_starts bs ON bs.master_session_id=sc.session_id
    WHERE sc.session_id=p_session AND sc.request_key=bs.request_key AND sc.state='bound' AND sc.simulation
    AND sc.actor_user_id IN('b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid,'f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid)
    AND bs.created_at>=(campaign->>'not_before')::timestamptz AND (named47 OR bs.created_at<(campaign->>'expires_at')::timestamptz))) IS DISTINCT FROM TRUE THEN stop_causes:=stop_causes||jsonb_build_array('OWN_START_ACTOR_OR_WINDOW_CLOSED');END IF;
  IF actual_c>cap_c31 OR actual_g>cap_g31 OR actual_h>cap_h31 OR actual_usd>cap_usd31 THEN stop_causes:=stop_causes||jsonb_build_array('CAMPAIGN_BUDGET_EXHAUSTED');END IF;
  campaign_ok:=coalesce(campaign_ok,false) AND actual_c<=cap_c31 AND actual_g<=cap_g31 AND actual_h<=cap_h31
   AND greatest(actual_c,actual_g)<=cap_pairs31 AND actual_usd<=cap_usd31
   AND actual_c<=(res31->>'count')::bigint AND actual_g<=(res31->>'gen')::bigint AND actual_h<=(res31->>'http')::bigint AND actual_usd<=(res31->>'usd')::numeric;
  IF mission_academy_owner.staff_carrier_runtime(p_session) IS DISTINCT FROM TRUE THEN stop_causes:=stop_causes||jsonb_build_array('STAFF_SETTLEMENT_CLASSIFIER_CLOSED');END IF;
  IF NOT campaign_ok AND stop_causes='[]'::jsonb THEN stop_causes:=jsonb_build_array('OWN_SCOPE_OR_SETTLEMENT_BINDING_CLOSED');END IF;
  RETURN jsonb_build_object('enforced',true,'allowed',ok AND campaign_ok,'remaining_calls',greatest(0,least(cap_h31,(res31->>'http')::bigint)-actual_h),
   'spent_usd',spent,'upper_bound_next_usd',bound,'call_limit',NULL,'cost_limit_usd',NULL,
   'qualification_sha256',a.c7_budget_qualification_sha256,'count_upper_cost_usd',a.c8_count_upper_cost_usd,
   'count_qualification_sha256',a.c8_count_qualification_sha256,'http_slots_per_generation',2,
   'scene_policy',scene_policy,'scene_policy_contract_sha256','1564720ca33bc961ff26fc15e07bd364ebd41a60b7a5a48c970a9c100038fad6',
   'scene_policy_sha256',public.combat_v2_sha256(scene_policy),'backing_origin','finite_columns_not_effective_staff_ceilings',
   'campaign_id',campaign->>'campaign_id','campaign_policy_sha256',public.combat_v2_sha256(campaign),
   'campaign_provider_deadline',provider_deadline,'campaign_incomplete',NOT campaign_ok,
   'campaign_reserved_count',actual_c,'campaign_reserved_gen',actual_g,'campaign_reserved_http',actual_h,
   'campaign_reserved_usd',actual_usd,'stop_causes',stop_causes,'reason_code',CASE WHEN campaign_ok THEN NULL ELSE 'C1266_CAMPAIGN_LIMIT_STOP' END) || CASE WHEN named47 THEN jsonb_build_object('campaign_time_mode','budget_or_explicit_stop') ELSE '{}'::jsonb END;
 END IF;

 IF scene_policy IS NOT NULL THEN
  RETURN jsonb_build_object('enforced',true,'allowed',ok,'remaining_calls',NULL,
   'spent_usd',spent,'upper_bound_next_usd',bound,'call_limit',NULL,'cost_limit_usd',NULL,
   'qualification_sha256',a.c7_budget_qualification_sha256,'count_upper_cost_usd',a.c8_count_upper_cost_usd,
   'count_qualification_sha256',a.c8_count_qualification_sha256,'http_slots_per_generation',2,
   'scene_policy',scene_policy,'scene_policy_contract_sha256','1564720ca33bc961ff26fc15e07bd364ebd41a60b7a5a48c970a9c100038fad6',
   'scene_policy_sha256',public.combat_v2_sha256(scene_policy),'backing_origin','finite_columns_not_effective_staff_ceilings');
 END IF;

 return jsonb_build_object('enforced',true,'allowed',ok,'manual_count_limit',mission_generic_owner.manual_staff_count_limit_v1(p_session),'remaining_calls',CASE WHEN mission_generic_owner.manual_staff_count_limit_v1(p_session)='none' THEN NULL ELSE greatest(0,capcalls-calls) END,
 'spent_usd',spent,'upper_bound_next_usd',bound,'call_limit',CASE WHEN mission_generic_owner.manual_staff_count_limit_v1(p_session)='none' THEN NULL ELSE capcalls END,'cost_limit_usd',capcost,
 'qualification_sha256',a.c7_budget_qualification_sha256,'count_upper_cost_usd',a.c8_count_upper_cost_usd,'count_qualification_sha256',a.c8_count_qualification_sha256,'http_slots_per_generation',2);
end $function$

CREATE OR REPLACE FUNCTION mission_generic_owner.c8_policy_snapshot_v1(p_work uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb; extension_policy jsonb; extroot mission_factory_owner.editor_release_readiness; extwork mission_generic_owner.work_items;
BEGIN
 SELECT q.value INTO result FROM (SELECT snapshot_base || CASE WHEN staff_policy IS NOT NULL THEN jsonb_build_object('schema_version','c1266-staff-scene-count-snapshot/2','scene_policy',staff_policy,'scene_policy_sha256',public.combat_v2_sha256(staff_policy),'scene_policy_contract_sha256','1564720ca33bc961ff26fc15e07bd364ebd41a60b7a5a48c970a9c100038fad6','release_sha256',(SELECT revision_sha256 FROM mission_factory_owner.editor_release_readiness WHERE singleton),'backing_origin','finite_columns_not_effective_staff_ceilings') ELSE '{}'::jsonb END FROM (SELECT CASE WHEN mission_generic_owner.c8_context24_scope_v1(p_work) THEN mission_generic_owner.c8_policy_snapshot_v1()||jsonb_build_object('max_input_tokens',24000,'max_output_tokens',20000) ELSE mission_generic_owner.c8_policy_snapshot_v1() END AS snapshot_base,mission_generic_owner.c1266_staff_scene_policy_v1((SELECT master_session_id FROM mission_generic_owner.work_items WHERE id=p_work)) AS staff_policy) staff_snapshot) AS q(value);
 IF p_work='4fb5ea83-f90a-4b76-a6f5-722641d9da43'::uuid THEN
  SELECT * INTO STRICT extwork FROM mission_generic_owner.work_items WHERE id=p_work;
  SELECT * INTO STRICT extroot FROM mission_factory_owner.editor_release_readiness WHERE singleton;
  extension_policy:=extroot.canonical_preimage::jsonb#>'{config,c1266_director_incomplete_recovery}';
  IF extroot.state IS DISTINCT FROM 'enabled' OR extroot.revision_sha256 IS DISTINCT FROM extroot.observed_revision_sha256
   OR extroot.revision_sha256 IS DISTINCT FROM encode(extensions.digest(convert_to(extroot.canonical_preimage,'UTF8'),'sha256'),'hex')
   OR extension_policy IS DISTINCT FROM '{"schema_version":"c1266-director-incomplete-recovery/1","enabled":true,"master_session_id":"4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4","old_work_id":"48df8786-3b66-4b44-a1bd-c92473ee5e55","old_payload_sha256":"58d06c515d3ea564a71075b69596d9823e4453688e50b64d7c061ca3f7a648ca","raw_sha256":"f2918095e64fabbd6910ec8566b2e2ccb8193be4ac5d6c0fc3fa8b1477d55c88","successor_work_id":"4fb5ea83-f90a-4b76-a6f5-722641d9da43","max_successors":1,"target_output_tokens":32000}'::jsonb
   OR extwork.master_session_id IS DISTINCT FROM '4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4'::uuid OR extwork.kind IS DISTINCT FROM 'director'
   OR extwork.payload->>'schema_version' IS DISTINCT FROM 'mission-director-work/4'
   OR mission_generic_owner.manual_staff_template_policy_v1(extwork.master_session_id) IS NULL
   OR result->>'max_input_tokens' IS DISTINCT FROM '24000' OR result->>'max_output_tokens' IS DISTINCT FROM '20000'
  THEN RAISE EXCEPTION 'C1266_DIRECTOR32_POLICY_BINDING' USING ERRCODE='42501';END IF;
  IF EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 ec WHERE ec.work_id=p_work
    AND (ec.scope IS DISTINCT FROM 'staff_mission' OR ec.contract_sha256 IS DISTINCT FROM public.combat_v2_sha256(ec.contract)
      OR NOT(ec.contract->'features'?'director_output_32k_v1'))) THEN RAISE EXCEPTION 'C1266_DIRECTOR32_SEALED_FEATURE' USING ERRCODE='42501';END IF;
  result:=result||jsonb_build_object('max_output_tokens',32000,'output_extension',jsonb_build_object(
   'schema_version','c1266-director-output-extension/1','feature','director_output_32k_v1','work_id',p_work,
   'base_rate_qualification_sha256','d8da6486b29f5e6b57272eb9d21660518cdcb57f12ed69209e12f32c37e2d5c0',
   'policy_sha256',public.combat_v2_sha256(extension_policy),'input_tokens_limit',24000,'output_tokens_limit',32000,
   'input_usd_million',0.1,'output_usd_million',0.5,'count_upper_cost_usd','0.0184','generation_upper_cost_usd','0.0184',
   'derivation','(24000*0.1+32000*0.5)/1000000;Count conservative same envelope'));
 END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION mission_generic_owner.effective_admission_usd_cap_v1(p_session uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE backing numeric;q jsonb;h text;root mission_factory_owner.editor_release_readiness;
BEGIN
 SELECT cost_budget_usd INTO backing FROM mission_generic_owner.dispatch_admissions WHERE master_session_id=p_session;
 IF p_session='4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4'::uuid AND backing=0.3136 AND mission_generic_owner.manual_staff_template_policy_v1(p_session) IS NOT NULL
 AND EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness br WHERE br.singleton AND br.state='enabled'
  AND br.revision_sha256=br.observed_revision_sha256 AND br.revision_sha256=encode(extensions.digest(convert_to(br.canonical_preimage,'UTF8'),'sha256'),'hex')
  AND br.canonical_preimage::jsonb#>'{config,c1266_director_incomplete_recovery}'='{"schema_version":"c1266-director-incomplete-recovery/1","enabled":true,"master_session_id":"4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4","old_work_id":"48df8786-3b66-4b44-a1bd-c92473ee5e55","old_payload_sha256":"58d06c515d3ea564a71075b69596d9823e4453688e50b64d7c061ca3f7a648ca","raw_sha256":"f2918095e64fabbd6910ec8566b2e2ccb8193be4ac5d6c0fc3fa8b1477d55c88","successor_work_id":"4fb5ea83-f90a-4b76-a6f5-722641d9da43","max_successors":1,"target_output_tokens":32000}'::jsonb) THEN RETURN 0.40::numeric;END IF;

 IF p_session IS DISTINCT FROM '44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid OR backing IS DISTINCT FROM 0.3136::numeric THEN RETURN backing;END IF;
 SELECT * INTO root FROM mission_factory_owner.editor_release_readiness WHERE singleton;
 IF root.state IS DISTINCT FROM 'enabled' OR root.revision_sha256 IS DISTINCT FROM root.observed_revision_sha256
 OR root.revision_sha256 IS DISTINCT FROM encode(extensions.digest(convert_to(root.canonical_preimage,'UTF8'),'sha256'),'hex')
 OR (root.canonical_preimage::jsonb#>'{config,c1266_manual_staff_usd_amendment}') IS DISTINCT FROM '{"schema_version":"c1266-manual-staff-usd-amendment/1","session_id":"44078c5f-7001-4129-9506-e2f34e68c8ac","location_id":"0b85f354-9cdb-47e1-baf9-3d266bb7e06b","admission_sha256":"e25a356c70fcb49e7e6261056b7d6ab54ed37caa277756addf2f7681a64fe728","previous_total_usd":"0.50","effective_total_usd":"1.00","approval_id":"ANTONELLO-C1266-SAME-SCENE-USD100-20261024","scope":"same_admission_only","history_policy":"preserve_all_costs_and_counters"}'::jsonb THEN RETURN backing;END IF;
 SELECT admission_sha256 INTO h FROM mission_generic_owner.manual_staff_admissions_v1 WHERE master_session_id=p_session;
 q:=mission_generic_owner.manual_staff_scope_v1(p_session);
 IF h IS DISTINCT FROM 'e25a356c70fcb49e7e6261056b7d6ab54ed37caa277756addf2f7681a64fe728'
 OR q IS NULL OR public.combat_v2_sha256(q) IS DISTINCT FROM h
 OR q->>'schema_version' IS DISTINCT FROM 'c1266-manual-staff-admission/1'
 OR q->>'location_id' IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'
 OR mission_generic_owner.manual_staff_count_limit_v1(p_session) IS DISTINCT FROM 'none'
 THEN RETURN backing;END IF;
 RETURN 1.00::numeric;
END;
$function$

CREATE OR REPLACE FUNCTION mission_generic_owner.provider_native_assert(p_receipt uuid, p_stage text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r mission_narrative_internal.dispatch_receipts;w mission_generic_owner.work_items;
 k mission_generic_owner.provider_permits;g mission_generic_owner.provider_policy;
 a mission_generic_owner.dispatch_admissions;pol mission_narrative_internal.runtime_policy;
 run_spent numeric;day_spent numeric;all_spent numeric;run_calls bigint;day_calls bigint;all_calls bigint;
 ub numeric;extra numeric;extra_call integer;env jsonb;narrative_contract jsonb;
 ordinary_qualified boolean:=false;staff_root_budget boolean:=false;staff_mode boolean;staff_spent numeric;staff_calls bigint;
 shared_on boolean;shared_paused boolean;shared_bound numeric;shared_price staff_ai_quota_private.prices%rowtype;shared_ticket jsonb;
 budget1_effective numeric;budget1_policy numeric;goal_financial_exempt boolean:=false;
begin
 if p_stage not in('reserve','authorize','consume') then raise exception 'MGPG_STAGE';end if;
 select * into strict r from mission_narrative_internal.dispatch_receipts where id=p_receipt;
 select * into strict w from mission_generic_owner.work_items where id=r.authority_receipt_id and dispatch_receipt_id=r.id;


 select * into strict k from mission_generic_owner.provider_permits where work_id=w.id and receipt_id=r.id;
 if k.transaction_id<>txid_current() or k.backend_pid<>pg_backend_pid()
 or k.stage<>(case p_stage when 'consume' then 'consume' else 'authorize' end)
 or k.lease_id<>w.lease_id or k.payload_sha256<>w.payload_sha256 or w.lease_expires_at<=clock_timestamp()
 or w.state<>(case p_stage when 'consume' then 'authorized' else 'claimed' end)
 or r.status<>(case p_stage when 'reserve' then 'claimed' when 'authorize' then 'reserved' else 'authorized' end)
 or r.event_kind<>'mission_generic_event' or r.renderer_version<>'mission-generic-runtime/1'
 or r.master_session_id<>w.master_session_id or r.request_key<>w.request_key
 then raise exception 'MGPG_PERMIT_INVALID';end if;
 perform mission_generic_owner.provider_ready(w.id);
 -- C9: only the verified Native same-TX permit may enter admission budget locks.
 if p_stage='reserve' and (mission_generic_owner.c7_run_budget_v1(w.master_session_id,true,w.id)->>'allowed')='false'
 then raise exception 'MGPG_C7_RUN_BUDGET_STOP' using errcode='55000';end if;
 env:=jsonb_build_object('work_id',w.id,'master_session_id',w.master_session_id,'event_id',w.event_id,
 'authority_receipt_id',w.authority_receipt_id,'payload_sha256',w.payload_sha256,'definition_sha256',w.definition_sha256,'revision',w.revision);
 narrative_contract:=mission_public_owner.work_contract_v1(w.id);
 if narrative_contract is not null then env:=env||jsonb_build_object('narrative_admission',narrative_contract);end if;
 if r.envelope<>env or r.envelope_sha256<>public.combat_v2_sha256(env) or r.authority_sha256<>public.combat_v2_sha256(env)
 then raise exception 'MGPG_ENVELOPE_INVALID';end if;
 select * into strict g from mission_generic_owner.provider_policy where singleton;
 select * into strict a from mission_generic_owner.dispatch_admissions where master_session_id=w.master_session_id;
 select * into strict pol from mission_narrative_internal.runtime_policy where singleton;
 staff_mode:=mission_academy_owner.staff_carrier_runtime(w.master_session_id);
 IF EXISTS(SELECT 1 FROM public.master_v2_sessions s726 WHERE s726.id=w.master_session_id AND s726.owner_kind='ai_service' AND s726.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND (EXISTS(SELECT 1 FROM mission_generic_owner.flow_staff_sessions f726 WHERE f726.master_session_id=s726.id AND f726.enabled) OR EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources q726 WHERE q726.session_id=s726.id AND q726.availability_scope='staff' AND q726.execution_context='staff_simulation'))) AND NOT mission_academy_owner.staff_carrier_runtime(w.master_session_id) AND NOT mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id) THEN RAISE EXCEPTION 'C726_FACTORY_STAFF_SCOPE_CLOSED' USING ERRCODE='42501';END IF;
 staff_root_budget:=mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id);staff_mode:=staff_mode OR staff_root_budget;

 IF mission_generic_owner.c1266_opening_named_v1(w.master_session_id) AND mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true) IS NULL THEN RAISE EXCEPTION 'C1266_NATIVE5_CLOSED' USING ERRCODE='42501';END IF;
 goal_financial_exempt:=EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 gm WHERE gm.master_session_id=w.master_session_id) AND mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NOT NULL;
 ordinary_qualified:=mission_generic_owner.c758_admission_proof_v1(w.master_session_id);
 IF ordinary_qualified AND p_stage='reserve' THEN PERFORM mission_generic_owner.c758_ordinary_budget_assert_v1(w.master_session_id,w.id);END IF;
 if pol.model<>'gpt-6-luna' or pol.reasoning_effort<>'high' or pol.store
 or pol.max_input_tokens<=0 or pol.max_output_tokens<=0
 or not(pol.input_usd_million>=0 and pol.input_usd_million<'Infinity'::numeric)
 or not(pol.output_usd_million>=0 and pol.output_usd_million<'Infinity'::numeric)
 then raise exception 'MGPG_NATIVE_PRICING_POLICY';end if;
 pol.max_input_tokens:=mission_generic_owner.receipt_input_cap(r.id,pol.max_input_tokens);
 IF w.id='4fb5ea83-f90a-4b76-a6f5-722641d9da43'::uuid THEN pol.max_output_tokens:=(mission_generic_owner.c8_policy_snapshot_v1(w.id)->>'max_output_tokens')::integer;END IF;
 ub:=(pol.max_input_tokens*pol.input_usd_million+pol.max_output_tokens*pol.output_usd_million)/1000000;
 if ub>0.20::numeric then raise exception 'MGPG_CALL_BUDGET_EXHAUSTED';end if;
 -- Native reserve holds runtime_policy FOR UPDATE before this sum. Other phases
 -- only validate an already charged reservation; no second reservation is added.
 select coalesce(sum(cost)filter(where d.master_session_id=w.master_session_id),0),
 coalesce(sum(cost)filter(where d.created_at>=date_trunc('day',clock_timestamp())),0),coalesce(sum(cost),0),
 coalesce(sum(http_calls)filter(where d.master_session_id=w.master_session_id),0),
 coalesce(sum(http_calls)filter(where d.created_at>=date_trunc('day',clock_timestamp())),0),coalesce(sum(http_calls),0)
 into run_spent,day_spent,all_spent,run_calls,day_calls,all_calls
 from (select d.*,mission_factory_owner.qc2_dispatch_cost_v1(d.id,case when d.status in('success','fallback','unknown_billable') or (d.quest_compile_request is not null and d.status='failed') then coalesce(d.charged_cost_usd,d.upper_bound_cost_usd,0)
 else coalesce(d.upper_bound_cost_usd,0) end) cost,
 mission_factory_owner.qc2_dispatch_calls_v1(d.id,exists(select 1 from mission_narrative_internal.dispatch_attempts t where t.receipt_id=d.id)) http_calls
 from mission_narrative_internal.dispatch_receipts d where (d.event_kind='mission_generic_event' and d.renderer_version='mission-generic-runtime/1') or d.quest_compile_request is not null) d;
 extra:=case when p_stage='reserve' then ub else 0 end;extra_call:=case when p_stage='reserve' then 1 else 0 end;
 budget1_effective:=mission_generic_owner.effective_admission_usd_cap_v1(w.master_session_id);
 budget1_policy:=CASE WHEN w.master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND a.cost_budget_usd=0.3136::numeric AND budget1_effective=1.00::numeric THEN greatest(g.run_budget_usd,budget1_effective) ELSE g.run_budget_usd END;
 if mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NULL and (not staff_mode or (a.c7_budget_enforced and p_stage='reserve')) and (run_spent+extra>least(budget1_policy,budget1_effective)
 or (NOT (mission_generic_owner.manual_staff_count_limit_v1(w.master_session_id)='none') AND run_calls+extra_call>CASE WHEN staff_root_budget OR (ordinary_qualified AND mission_generic_owner.c1266_opening_named_v1(w.master_session_id)) THEN 2*least(g.max_run_calls,a.call_limit) ELSE least(g.max_run_calls,a.call_limit) END))
 then raise exception 'MGPG_BUDGET_EXHAUSTED';end if;
 IF ordinary_qualified AND NOT goal_financial_exempt AND (day_spent+extra>g.daily_budget_usd OR all_spent+extra>g.global_budget_usd OR (NOT (mission_generic_owner.manual_staff_count_limit_v1(w.master_session_id)='none') AND(day_calls+extra_call>g.max_daily_calls OR all_calls+extra_call>g.max_global_calls))) THEN RAISE EXCEPTION 'MGPG_BUDGET_EXHAUSTED';END IF;
 if staff_mode OR ordinary_qualified then
   select enabled,admissions_paused into strict shared_on,shared_paused
     from staff_ai_quota_private.runtime where singleton for update;
   if shared_paused then raise exception 'STAFF_QUOTA_ADMISSIONS_PAUSED' using errcode='55000';end if;
   IF ordinary_qualified AND NOT shared_on THEN RAISE EXCEPTION 'C758_ORDINARY_SHARED_QUOTA_CLOSED' USING ERRCODE='55000';END IF;
   if shared_on then
     select * into strict shared_price from staff_ai_quota_private.prices where model=pol.model;
     shared_bound:=greatest(ub,(pol.max_input_tokens*shared_price.input_usd_million+
       pol.max_output_tokens*shared_price.output_usd_million)/1000000);
     if p_stage='reserve' then
       shared_ticket:=staff_ai_quota_private.reserve('mission_generic_ai',r.id,1,
         w.master_session_id,pol.model,shared_bound);
       if shared_ticket->>'granted_now'<>'true' then
         raise exception 'STAFF_GENERIC_RESERVE_REPLAY' using errcode='40001';
       end if;
     elsif not exists(select 1 from staff_ai_quota_private.calls c where
       c.producer='mission_generic_ai' and c.source_id=r.id and c.call_no=1
       and c.scope_id=w.master_session_id and c.state='reserved') then
       raise exception 'STAFF_GENERIC_RESERVE_MISSING' using errcode='40001';
     end if;
   else
   -- Budget Staff Test Room: 1000 chiamate e 5 USD nella finestra mobile di 30 giorni.
   -- La classificazione storica non dipende dallo stato aperto della sessione.
   select coalesce(sum(cost),0),count(*) filter(where used)
     into staff_spent,staff_calls
   from (
     select d.id,d.master_session_id,d.created_at,
       case when d.status in('success','fallback','unknown_billable')
         then coalesce(d.charged_cost_usd,d.upper_bound_cost_usd,0)
         else coalesce(d.upper_bound_cost_usd,0) end as cost,
       exists(select 1 from mission_narrative_internal.dispatch_attempts t where t.receipt_id=d.id) as used
     from mission_narrative_internal.dispatch_receipts d
     join public.master_v2_sessions s on s.id=d.master_session_id
     where d.event_kind='mission_generic_event'
       and d.renderer_version='mission-generic-runtime/1'
       and d.created_at>=clock_timestamp()-interval '30 days'
       and s.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
       and s.owner_kind='ai_service'
   ) staff_receipts;
   if NOT goal_financial_exempt AND (staff_spent+extra>5::numeric or (NOT (mission_generic_owner.manual_staff_count_limit_v1(w.master_session_id)='none') AND staff_calls+extra_call>1000))
   then raise exception 'MGPG_STAFF_ROLLING_BUDGET_EXHAUSTED';end if;
   end if;
 else
   if day_spent+extra>g.daily_budget_usd or all_spent+extra>g.global_budget_usd
     or (NOT (mission_generic_owner.manual_staff_count_limit_v1(w.master_session_id)='none') AND(day_calls+extra_call>g.max_daily_calls or all_calls+extra_call>g.max_global_calls))
   then raise exception 'MGPG_BUDGET_EXHAUSTED';end if;
 end if;
end;
$function$

CREATE OR REPLACE FUNCTION mission_public_owner.work_contract_issue_v1(p_work uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w mission_generic_owner.work_items;b mission_generic_owner.run_bindings;
 a mission_public_owner.session_admissions_v1;q mission_factory_owner.quest_run_sources;
 pub mission_factory_owner.publications;source_scope text;release_sha text;profile text;
 q49 jsonb;source_attestation jsonb;payload_version text;features jsonb:='[]'::jsonb;doc jsonb;old jsonb;ignored jsonb;c5_proof jsonb;c5_native jsonb;c5_stamp jsonb;template_policy jsonb;
begin
 select * into strict w from mission_generic_owner.work_items where id=p_work for update;
 old:=mission_public_owner.work_contract_v1(w.id);
 if old is not null then return old;end if;
  template_policy:=mission_generic_owner.manual_staff_template_policy_v1(w.master_session_id);
 IF mission_generic_owner.c1266_opening_named_v1(w.master_session_id) THEN
  c5_proof:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);
  c5_native:=mission_generic_owner.c1266_native_start_v1(w.master_session_id,false,true);
  IF c5_proof IS NULL OR c5_native IS NULL THEN RAISE EXCEPTION 'C1266_NARRATIVE5_ISSUE_CLOSED' USING ERRCODE='42501';END IF;
  release_sha:=c5_proof->>'release_sha256';source_scope:=CASE WHEN c5_proof#>>'{admission,resource_scope}'='world' THEN 'public_mission' ELSE 'staff_mission' END;
  c5_stamp:=jsonb_build_object('schema_version','c1266-work-execution-attestation/1','execution_context',c5_proof->>'execution_context',
   'admission',c5_proof->'admission','release_sha256',release_sha,'binding_sha256',c5_proof->>'binding_sha256',
   'financial_qualification_sha256',c5_proof->>'financial_qualification_sha256','c7_budget_qualification_sha256',c5_proof->>'c7_budget_qualification_sha256',
   'start_receipt_id',c5_native->>'start_receipt_id','start_snapshot_sha256',c5_native#>>'{eligibility,board_snapshot_sha256}',
   'source_scope',(SELECT canonical_preimage::jsonb#>'{config,c1266_opening,source_scope}' FROM mission_factory_owner.editor_release_readiness WHERE singleton));
 q49:=mission_generic_owner.c1266_staff_source_scope_v1(w.master_session_id);
 IF q49 IS NOT NULL THEN
 c5_stamp:=c5_stamp||jsonb_build_object('schema_version','c1266-work-execution-attestation/2','source_scope',q49->'source_scope','source_qualification',q49,'source_qualification_sha256',public.combat_v2_sha256(q49));
 END IF;
 q49:=mission_generic_owner.manual_staff_scope_v1(w.master_session_id);
 IF q49 IS NOT NULL THEN
  c5_stamp:=c5_stamp||jsonb_build_object('schema_version','c1266-work-execution-attestation/3','source_scope',q49->'source_scope','source_qualification',q49,'source_qualification_sha256',public.combat_v2_sha256(q49));
 END IF;
 ELSIF mission_generic_owner.c1266_role_scope_v1(w.master_session_id,true) THEN
  ignored:=mission_generic_owner.c1266_clean_staff_admission_v1(w.master_session_id,true,true);
  release_sha:=ignored->>'release_sha256';source_scope:='staff_mission';
 ELSIF exists(select 1 from mission_factory_owner.quest_run_sources qs where qs.session_id=w.master_session_id and qs.availability_scope='public' and qs.state in('prepared','opening_pending','uncertain','started')) then
  ignored:=mission_factory_owner.quest_run_source_assert_v1(w.master_session_id);
  select * into strict q from mission_factory_owner.quest_run_sources where session_id=w.master_session_id;
  release_sha:=q.public_release_sha256;source_scope:='public_quest';
 elsif mission_public_owner.role_session_allowed_v1(w.master_session_id) then
  select * into strict a from mission_public_owner.session_admissions_v1 where master_session_id=w.master_session_id;
  release_sha:=a.release_sha256;source_scope:='public_mission';
 elsif exists(select 1 from mission_launch_owner.dual_decisions d
  join mission_launch_owner.dual_scopes s on s.mission_id=d.mission_id and s.activation_id=d.activation_id
  where d.master_session_id=w.master_session_id) then
  ignored:=mission_public_owner.launch_provenance_v1(w.master_session_id);
  if ignored->>'availability_scope' is distinct from 'staff'
  then raise exception 'NARRATIVE_STAFF_LAUNCH_PROVENANCE' using errcode='42501';end if;
  release_sha:=ignored->>'release_sha256';source_scope:='staff_mission';
 elsif exists(select 1 from mission_factory_owner.quest_run_sources qs
  join public.master_v2_sessions ms on ms.id=qs.session_id
  join public.locations l on l.id=ms.location_id
  where qs.session_id=w.master_session_id and l.id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
   and l.is_active and l.is_test and ms.owner_kind='ai_service' and ms.mission_id is null
   and ms.closed_at is null and ms.suspended_at is null
   and qs.state in('prepared','opening_pending','uncertain','started')) then
  -- Same authoritative Factory assertion, not a second Quest engine.
  ignored:=mission_factory_owner.quest_run_source_assert_v1(w.master_session_id);
  select * into strict q from mission_factory_owner.quest_run_sources where session_id=w.master_session_id;
  select p.* into strict pub from mission_public_owner.publications_v2 p
   join mission_factory_owner.quest_arcs arc on arc.publication_request=p.request_key where arc.id=q.arc_id;
  if pub.target<>'staff' or pub.state<>'staff' or pub.quest_arc_id is distinct from q.arc_id
  then raise exception 'NARRATIVE_QUEST_PUBLICATION_SCOPE' using errcode='42501';end if;
  release_sha:=pub.release_revision_sha256;source_scope:='staff_quest';
 else return null;end if;
 if w.state<>'ready' or w.kind not in('director','narration','choice')
 or w.payload_sha256 is distinct from public.combat_v2_sha256(w.payload)
 then raise exception 'NARRATIVE_WORK_CONTRACT_SOURCE' using errcode='40001';end if;
 select * into strict b from mission_generic_owner.run_bindings where master_session_id=w.master_session_id;
 if b.snapshot_sha256 is distinct from w.definition_sha256
 or b.snapshot_sha256 is distinct from mission_internal.fingerprint(b.snapshot)
 then raise exception 'NARRATIVE_WORK_CONTRACT_BINDING' using errcode='40001';end if;
 payload_version:=w.payload->>'schema_version';
 profile:=case when w.kind in('narration','director') then 'cinematic_master_1' else 'legacy' end;
 if w.kind='director' and (payload_version in('mission-director-work/1','mission-director-work/2','mission-director-work/3') OR(payload_version='mission-director-work/4' AND mission_generic_owner.c1266_role_scope_v2(w.master_session_id,true) AND mission_generic_owner.c1266_role_work_attest_v2(w.id) IS NOT NULL)) then
  if not exists(select 1 from mission_generic_owner.unified_source_windows sw
   where sw.id=w.authority_receipt_id and sw.master_session_id=w.master_session_id
    and sw.work_id=w.id and sw.definition_sha256=w.definition_sha256
    and sw.step_key=w.step_key and sw.run_control_version=w.run_control_version)
  then raise exception 'NARRATIVE_DIRECTOR_SOURCE_RECEIPT' using errcode='40001';end if;
  features:=jsonb_build_array('director_progression','speech_intent');
 elsif w.kind='narration' and payload_version in('mission-generic-narration/3','mission-generic-narration/4') then
  if not exists(select 1 from mission_generic_owner.unified_batches ub
   where ub.id=w.authority_receipt_id and ub.master_session_id=w.master_session_id
    and ub.writer_work_id=w.id and ub.payload_sha256=w.payload_sha256
    and ub.state='ready')
  then raise exception 'NARRATIVE_WRITER_BATCH_RECEIPT' using errcode='40001';end if;
  features:=jsonb_build_array(case payload_version when 'mission-generic-narration/3'
    then 'unified_narration_v3' else 'segmented_narration_v4' end);
 elsif w.kind='narration' and payload_version in('mission-generic-narration/1','mission-generic-narration/2') then
  if jsonb_array_length(coalesce(w.payload->'roleless_declarations','[]'::jsonb))>0 then
   raise exception 'NARRATIVE_ROLELESS_REQUIRES_NATIVE_UNIFIED_ROUTE' using errcode='55000';end if;
 elsif w.kind<>'choice' then
  raise exception 'NARRATIVE_WORK_PROFILE_UNSUPPORTED' using errcode='55000';
 end if;
 source_attestation:=mission_public_owner.narrative_source_attest_v1(w.id)||jsonb_build_object('master_session_id',w.master_session_id,'definition_sha256',w.definition_sha256,'release_sha256',release_sha);
 IF source_attestation#>>'{role_intents,schema_version}' IN('mission-role-intent-attestation/2','mission-role-intent-attestation/3','mission-role-intent-attestation/4') THEN
  IF source_attestation#>>'{role_intents,schema_version}'='mission-role-intent-attestation/4' AND(source_scope IS DISTINCT FROM 'staff_mission' OR source_attestation#>>'{role_intents,temporal_contract_sha256}' IS DISTINCT FROM '0603ab23e76750b5babeb41421bc84b551b959945f21267ffd7169140732f1e8' OR source_attestation#>>'{role_intents,peer_confirmation,schema_version}' IS DISTINCT FROM 'mission-peer-confirmation-contract/2') THEN RAISE EXCEPTION 'C1266_PEER_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  IF source_attestation#>>'{role_intents,schema_version}'='mission-role-intent-attestation/3' AND (source_scope IS DISTINCT FROM 'staff_mission' OR source_attestation#>>'{role_intents,temporal_contract_sha256}' IS DISTINCT FROM '3fdeaa942bcf3ba217a976f7b0896f4594721fa45cde9ff8ed7bddf15391feda' OR source_attestation#>>'{role_intents,peer_confirmation,schema_version}' IS DISTINCT FROM 'mission-peer-confirmation-contract/1') THEN RAISE EXCEPTION 'C1266_PEER_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  IF NOT mission_generic_owner.c1266_role_scope_v2(w.master_session_id,true) OR (source_scope IS DISTINCT FROM 'staff_mission' AND c5_proof IS NULL) THEN RAISE EXCEPTION 'C1266_TEMPORAL_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  features:=features||jsonb_build_array('role_intents_v2');
 ELSIF source_attestation->'role_intents' IS NOT NULL THEN
  IF NOT mission_generic_owner.c1266_role_scope_v1(w.master_session_id,true)
   OR (source_scope IS DISTINCT FROM 'staff_mission' AND c5_proof IS NULL)
  THEN RAISE EXCEPTION 'C1266_ROLE_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  features:=features||jsonb_build_array('role_intents_v1');
 END IF;
 if jsonb_typeof(source_attestation->'peaceful_exit')='object' then features:=features||jsonb_build_array('peaceful_exit_v1');end if;
 if jsonb_array_length(source_attestation->'continuity_sources')>0 then
  features:=features||jsonb_build_array('continuity_sources_v1');
 end if;
 -- peaceful_exit is not inferred from the profile, caller or an arbitrary UUID.
 -- It requires a separate native legal capability; none is minted here.
 IF c5_stamp IS NOT NULL THEN source_attestation:=source_attestation||jsonb_build_object('execution_authority',c5_stamp);features:=features||jsonb_build_array('execution_authority_v1');END IF;
 IF source_scope='staff_mission' AND c5_stamp IS NOT NULL
  AND mission_generic_owner.manual_staff_scope_v1(w.master_session_id) IS NOT NULL
  AND EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness r WHERE r.singleton AND r.state='enabled'
    AND r.revision_sha256=r.observed_revision_sha256
    AND r.canonical_preimage::jsonb#>>'{config,c1266_free_narrative,enabled}'='true'
    AND (r.canonical_preimage::jsonb#>>'{config,c1266_free_narrative,master_session_id}'=w.master_session_id::text OR template_policy IS NOT NULL))
  AND (w.kind='director' OR(w.kind='narration' AND payload_version='mission-generic-narration/4')) THEN
  features:=features||jsonb_build_array('provider_output_retention_v1');
  IF w.kind='narration' THEN features:=features||jsonb_build_array('free_narrative_v1');END IF;
 END IF;
 IF source_scope='staff_mission' AND c5_stamp IS NOT NULL AND mission_generic_owner.native_intent_policy_v1(w.master_session_id) IS NOT NULL
  AND ((w.kind='director' AND payload_version IN('mission-director-work/3','mission-director-work/4'))
   OR(w.kind='narration' AND payload_version='mission-generic-narration/4' AND features?'free_narrative_v1' AND features?'provider_output_retention_v1')) THEN
  features:=features||jsonb_build_array('native_intent_resolution_v1');
 END IF;
 IF source_scope='staff_mission' AND c5_stamp IS NOT NULL AND w.kind='narration' AND payload_version='mission-generic-narration/3'
  AND w.payload->>'composition_kind' IN('combat_defense_resolved','combat_resolved_no_pending','combat_resolved_then_png_offensive','combat_exit')
  AND mission_generic_owner.manual_staff_scope_v1(w.master_session_id) IS NOT NULL
  AND (template_policy IS NOT NULL OR EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness rr WHERE rr.singleton AND rr.state='enabled' AND rr.revision_sha256=rr.observed_revision_sha256
   AND rr.canonical_preimage::jsonb#>>'{config,c1266_combat_snapshot_recovery,enabled}'='true' AND rr.canonical_preimage::jsonb#>>'{config,c1266_combat_snapshot_recovery,master_session_id}'=w.master_session_id::text
   AND rr.canonical_preimage::jsonb#>>'{config,c1266_combat_snapshot_recovery,ordinary_public_enabled}'='false')) THEN
  features:=features||jsonb_build_array('combat_snapshot_origin_budget_v1');
 END IF;
 -- Independently scoped speech is a frozen future-work capability, never a reinterpretation of old contracts.
 IF source_scope='staff_mission' AND c5_stamp IS NOT NULL AND template_policy IS NOT NULL
  AND source_attestation#>>'{role_intents,schema_version}'='mission-role-intent-attestation/4'
  AND source_attestation#>>'{role_intents,peer_confirmation,schema_version}'='mission-peer-confirmation-contract/2'
  AND EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness sp27_root WHERE sp27_root.singleton AND sp27_root.state='enabled'
   AND sp27_root.revision_sha256=sp27_root.observed_revision_sha256 AND sp27_root.revision_sha256=release_sha
   AND sp27_root.canonical_preimage::jsonb#>>'{config,c1266_npc_speech_context,schema_version}'='c1266-npc-speech-context-policy/1'
   AND sp27_root.canonical_preimage::jsonb#>'{config,c1266_npc_speech_context,enabled}'='true'::jsonb)
  AND ((w.kind='director' AND payload_version='mission-director-work/4')
   OR(w.kind='narration' AND payload_version='mission-generic-narration/4' AND features?'free_narrative_v1'
    AND EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 sp27_parent_contract
     JOIN mission_generic_owner.work_items sp27_parent ON sp27_parent.id=sp27_parent_contract.work_id
     WHERE sp27_parent.id=(source_attestation#>>'{role_intents,decision_work_id}')::uuid
      AND sp27_parent.master_session_id=w.master_session_id AND sp27_parent.kind='director'
      AND sp27_parent_contract.scope='staff_mission' AND sp27_parent_contract.payload_sha256=sp27_parent.payload_sha256
      AND sp27_parent_contract.contract_sha256=public.combat_v2_sha256(sp27_parent_contract.contract)
      AND sp27_parent_contract.contract->'features'?'npc_speech_context_v1'))) THEN
  features:=features||jsonb_build_array('npc_speech_context_v1');
 END IF;
 -- Wire opt-in is frozen ONLY in new contracts; existing contracts return above unchanged.
 IF w.kind='director' AND payload_version='mission-director-work/4' AND source_scope='staff_mission'
  AND c5_stamp IS NOT NULL AND template_policy IS NOT NULL
  AND source_attestation#>>'{role_intents,schema_version}'='mission-role-intent-attestation/4'
  AND EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness np39_root
   WHERE np39_root.singleton AND np39_root.state='enabled'
   AND np39_root.revision_sha256=np39_root.observed_revision_sha256 AND np39_root.revision_sha256=release_sha
   AND np39_root.canonical_preimage::jsonb#>>'{config,c1266_numeric_peer_wire,schema_version}'='c1266-numeric-peer-wire-policy/1'
   AND np39_root.canonical_preimage::jsonb#>'{config,c1266_numeric_peer_wire,enabled}'='true'::jsonb
   AND np39_root.canonical_preimage::jsonb#>>'{config,c1266_numeric_peer_wire,wire_version}'='mission-director-peer-confirmation/3') THEN
  features:=features||jsonb_build_array('numeric_peer3_wire_v1');
 END IF;
 -- A distinct provider-output capability for the one approved paid incomplete successor.
 -- Source financial attestation remains sealed and unchanged; no proof getter is called while issuing this contract.
 IF w.id='4fb5ea83-f90a-4b76-a6f5-722641d9da43'::uuid AND w.master_session_id='4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4'::uuid
 AND w.kind='director' AND payload_version='mission-director-work/4' AND source_scope='staff_mission'
 AND template_policy IS NOT NULL AND source_attestation#>>'{execution_authority,schema_version}'='c1266-work-execution-attestation/3'
 AND EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness rr50
 WHERE rr50.singleton AND rr50.scope='staff' AND rr50.state='enabled'
 AND rr50.revision_sha256=rr50.observed_revision_sha256 AND rr50.revision_sha256=release_sha
 AND rr50.revision_sha256=encode(extensions.digest(convert_to(rr50.canonical_preimage,'UTF8'),'sha256'),'hex')
 AND rr50.canonical_preimage::jsonb#>'{config,c1266_director_incomplete_recovery}'='{"schema_version":"c1266-director-incomplete-recovery/1","enabled":true,"master_session_id":"4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4","old_work_id":"48df8786-3b66-4b44-a1bd-c92473ee5e55","old_payload_sha256":"58d06c515d3ea564a71075b69596d9823e4453688e50b64d7c061ca3f7a648ca","raw_sha256":"f2918095e64fabbd6910ec8566b2e2ccb8193be4ac5d6c0fc3fa8b1477d55c88","successor_work_id":"4fb5ea83-f90a-4b76-a6f5-722641d9da43","max_successors":1,"target_output_tokens":32000}'::jsonb)
 AND EXISTS(SELECT 1 FROM mission_generic_owner.work_items parent50
 JOIN mission_generic_owner.unified_source_windows src50 ON src50.id=parent50.authority_receipt_id AND src50.work_id=parent50.id
 JOIN mission_generic_owner.unified_source_windows child50 ON child50.id=w.authority_receipt_id AND child50.work_id=w.id
 JOIN mission_narrative_internal.dispatch_audit prepared50 ON prepared50.receipt_id=parent50.dispatch_receipt_id AND prepared50.event_code='staff_director_incomplete_prepared_v1'
 JOIN mission_narrative_internal.dispatch_audit issued50 ON issued50.receipt_id=parent50.dispatch_receipt_id AND issued50.event_code='staff_director_incomplete_reissued_v1'
 WHERE parent50.id='48df8786-3b66-4b44-a1bd-c92473ee5e55'::uuid AND parent50.master_session_id=w.master_session_id
 AND parent50.kind='director' AND parent50.state='failed' AND parent50.result->'failure_codes'='["MISSION_PROVIDER_INCOMPLETE"]'::jsonb
 AND parent50.payload_sha256='58d06c515d3ea564a71075b69596d9823e4453688e50b64d7c061ca3f7a648ca'
 AND src50.superseded_at IS NOT NULL AND src50.superseded_reason='staff_failed_director_incomplete_retry' AND src50.consumed_message_id IS NULL
 AND child50.role_ids=src50.role_ids AND child50.context->>'source_revision'=src50.context->>'source_revision'
 AND child50.master_session_id=w.master_session_id AND child50.step_key=src50.step_key AND child50.run_control_version=src50.run_control_version
 AND child50.source_sha256=w.payload_sha256 AND child50.context=w.payload->'context'
 AND prepared50.details->>'old_work_id'=parent50.id::text AND prepared50.details->>'successor_work_id'=w.id::text
 AND issued50.details->>'prepared_sha256'=public.combat_v2_sha256(prepared50.details)
 AND issued50.details->>'successor_work_id'=w.id::text AND issued50.details->>'successor_payload_sha256'=w.payload_sha256)
 THEN features:=features||jsonb_build_array('director_output_32k_v1');END IF;
 doc:=jsonb_build_object('schema_version',case when c5_proof IS NOT NULL OR source_scope='public_quest' then 'mission-narrative-admission/3' else 'mission-narrative-admission/2' end,'scope',source_scope,
  'release_sha256',release_sha,'work_id',w.id,'master_session_id',w.master_session_id,
  'definition_sha256',w.definition_sha256,'payload_sha256',w.payload_sha256,
  'payload_schema_version',payload_version,'editorial_profile',profile,'features',features,'source_attestation',source_attestation);
 insert into mission_public_owner.work_contracts_v1(work_id,master_session_id,scope,release_sha256,
 definition_sha256,payload_sha256,contract,contract_sha256)
 values(w.id,w.master_session_id,source_scope,release_sha,w.definition_sha256,w.payload_sha256,doc,public.combat_v2_sha256(doc));
 return doc;
end $function$

CREATE OR REPLACE FUNCTION public.mission_generic_dispatch_authorize_v1(p_work uuid, p_lease uuid, p_worker_token text, p_policy jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w mission_generic_owner.work_items;a mission_generic_owner.dispatch_admissions;pol mission_narrative_internal.runtime_policy;
 rr jsonb;z jsonb;spent numeric;ub numeric;c8_proof jsonb;
begin
 perform mission_ai_board_owner.service_only();
 -- C1266_AVAILABILITY_COORD: shared before mutation locks; xact lifetime.
 PERFORM pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0));

 -- C9: freeze policy DML through proof, Native reserve and authorization.
 LOCK TABLE mission_narrative_internal.runtime_policy IN SHARE MODE;
 perform 1 from mission_generic_owner.role_window_cursors
   where master_session_id=(select master_session_id from mission_generic_owner.work_items where id=p_work)
   for update;
 if (select master_session_id from mission_generic_owner.work_items where id=p_work)
   ='b70b23cf-bad8-475d-a56a-d9c549e35d84'::uuid and not found
 then raise exception 'MRS_V4_CURSOR_REQUIRED' using errcode='40001';end if;
 perform 1 from public.master_v2_sessions where id=(select master_session_id from mission_generic_owner.work_items where id=p_work) for update;
 select * into strict w from mission_generic_owner.work_items where id=p_work for update; perform mission_generic_owner.role_dispatch_assert_v4(w.id);
 perform mission_generic_owner.work_assert(w);
 perform mission_generic_owner.assert_runtime(w.master_session_id);
 IF mission_generic_owner.c1266_opening_named_v1(w.master_session_id) AND mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true) IS NULL THEN RAISE EXCEPTION 'C1266_AUTHORIZE5_CLOSED' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM public.master_v2_sessions s726 WHERE s726.id=w.master_session_id AND s726.owner_kind='ai_service' AND s726.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND (EXISTS(SELECT 1 FROM mission_generic_owner.flow_staff_sessions f726 WHERE f726.master_session_id=s726.id AND f726.enabled) OR EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources q726 WHERE q726.session_id=s726.id AND q726.availability_scope='staff' AND q726.execution_context='staff_simulation'))) AND NOT mission_academy_owner.staff_carrier_runtime(w.master_session_id) AND NOT mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id) THEN RAISE EXCEPTION 'C726_FACTORY_STAFF_SCOPE_CLOSED' USING ERRCODE='42501';END IF;

 if w.state<>'claimed' or w.lease_id<>p_lease or w.lease_expires_at<=clock_timestamp()
 or p_policy->>'payload_sha256' is distinct from w.payload_sha256 then raise exception 'MGD_AUTHORIZE_STALE';end if;
 select * into strict a from mission_generic_owner.dispatch_admissions where master_session_id=w.master_session_id for update;
 select * into strict pol from mission_narrative_internal.runtime_policy where singleton;
 IF w.id='4fb5ea83-f90a-4b76-a6f5-722641d9da43'::uuid THEN pol.max_output_tokens:=(mission_generic_owner.c8_policy_snapshot_v1(w.id)->>'max_output_tokens')::integer;END IF;
 if not a.enabled or (not mission_academy_owner.staff_carrier_runtime(w.master_session_id) and mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NULL and NOT (mission_generic_owner.manual_staff_count_limit_v1(w.master_session_id)='none') and a.calls_authorized>=a.call_limit) or p_policy->>'model' is distinct from pol.model
 or p_policy->>'reasoning_effort' is distinct from pol.reasoning_effort or p_policy->>'store' is distinct from 'false'
 or (p_policy->>'max_output_tokens')::integer is distinct from pol.max_output_tokens then raise exception 'MGD_ADMISSION_INVALID';end if;
 if a.c7_budget_enforced then c8_proof:=mission_generic_owner.c8_input_proof_assert_v1(w.id,p_lease,p_policy);end if;
 pol.max_input_tokens:=mission_generic_owner.receipt_input_cap(w.dispatch_receipt_id,pol.max_input_tokens);
 ub:=(pol.max_input_tokens*pol.input_usd_million+pol.max_output_tokens*pol.output_usd_million)/1000000;
 select coalesce(sum(case when d.status in('success','fallback','unknown_billable') then coalesce(d.charged_cost_usd,0)
  else coalesce(d.upper_bound_cost_usd,0) end),0) into spent
 from mission_narrative_internal.dispatch_receipts d where d.master_session_id=w.master_session_id;
 if not mission_academy_owner.staff_carrier_runtime(w.master_session_id) and mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NULL and spent+ub>mission_generic_owner.effective_admission_usd_cap_v1(w.master_session_id)
 then raise exception 'MGD_RUN_BUDGET_EXHAUSTED';end if;
 perform mission_generic_owner.provider_permit(w.id,'authorize');
 -- Count and Gen have independent budgets. Native Gen lease stays within the work lease.
 if mission_generic_owner.c1266_clean_staff_admission_v1(w.master_session_id,true,true) IS NOT NULL
 OR (mission_generic_owner.c1266_opening_named_v1(w.master_session_id) AND mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true) IS NOT NULL) then
  if extract(epoch from(w.lease_expires_at-clock_timestamp()))<30 then
   raise exception 'C1266_BACKGROUND_GENERATION_DEADLINE_CLOSED' using errcode='55000';end if;
  rr:=public.mission_narrative_attempt_reserve_internal(p_worker_token,w.dispatch_receipt_id,
   least(CASE WHEN w.id='4fb5ea83-f90a-4b76-a6f5-722641d9da43'::uuid AND pol.max_output_tokens=32000 THEN 380 ELSE 260 END,floor(extract(epoch from(w.lease_expires_at-clock_timestamp())))::integer),null,null);
 else
  rr:=public.mission_narrative_attempt_reserve_internal(p_worker_token,w.dispatch_receipt_id,180,null,null);
 end if;
 if rr->>'status'<>'reserved' then raise exception 'MGD_NATIVE_RESERVE_REJECTED';end if;
 z:=public.mission_narrative_provider_authorize_internal(p_worker_token,w.dispatch_receipt_id,(rr->>'attempt_id')::uuid,rr->>'lease_token');
 if not mission_academy_owner.staff_carrier_runtime(w.master_session_id) then
   update mission_generic_owner.dispatch_admissions set calls_authorized=calls_authorized+1,manual_count_limit=CASE WHEN mission_generic_owner.manual_staff_count_limit_v1(w.master_session_id)='none' THEN 'none' ELSE manual_count_limit END where master_session_id=w.master_session_id;
 end if;
 update mission_generic_owner.work_items set state='authorized',authorization_id=(z->>'authorization_id')::uuid where id=w.id;
 return z||jsonb_build_object('work_id',w.id,'granted_now',true)||case when c8_proof is not null then jsonb_build_object('input_measurement_id',c8_proof->>'measurement_id','provider_request_sha256',c8_proof->>'generation_request_sha256','policy_snapshot_sha256',c8_proof->>'policy_snapshot_sha256') else '{}'::jsonb end;
end;
$function$

