   IF NOT ((mission_factory_owner.keys_exact_v2(c5_proof->'admission',ARRAY['schema_version','kind','resource_scope','finite_admission_sha256','grant_id','not_before','expires_at','location_id','campaign_id','time_policy']) AND c5_proof->'admission'->>'schema_version'='c1266-staff-admission-authority/2' AND c5_proof->'admission'->>'kind'='staff_finite' AND c5_proof->'admission'->>'resource_scope'='staff_simulation' AND c5_proof->'admission'->>'campaign_id'='b2fc5e28-072b-41f2-8dd8-cb5a35a13092' AND c5_proof->'admission'->>'grant_id'='b925043a-c1b3-434b-8fb4-f335903b2af0' AND c5_proof->'admission'->>'not_before'='2026-10-20T14:12:18.393948+00:00' AND c5_proof->'admission'->>'expires_at'='2026-10-20T15:12:18.393948+00:00' AND c5_proof->'admission'->>'location_id'='0b85f354-9cdb-47e1-baf9-3d266bb7e06b' AND c5_proof->'admission'->'time_policy'='{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}'::jsonb AND (c5_proof->'admission'->>'finite_admission_sha256' ~ '^[a-f0-9]{64}$') IS TRUE) IS TRUE) OR c7_budget->'campaign_provider_deadline' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'C1266_NAMED47_LEASE_POLICY_CLOSED' USING ERRCODE='42501';END IF;
  ELSIF c7_budget ? 'campaign_provider_deadline' THEN
  UPDATE mission_generic_owner.work_items SET lease_expires_at=least(lease_expires_at,(c7_budget->>'campaign_provider_deadline')::timestamptz) WHERE id=w.id RETURNING * INTO w;
 END IF;
 return jsonb_build_object('state','claimed','granted_now',true,'work',jsonb_build_object('schema_version','mission-generic-work/1',
  'work_id',w.id,'master_session_id',w.master_session_id,'event_id',w.event_id,'request_key',w.request_key,'revision',w.revision,
  'step_key',w.step_key,'run_control_version',w.run_control_version,'definition_sha256',w.definition_sha256,
  'encounter_id',w.encounter_id,'authority_receipt_id',w.authority_receipt_id,'kind',w.kind,'lease_id',w.lease_id,
  'server_now',clock_timestamp(),'lease_expires_at',w.lease_expires_at,'payload_sha256',w.payload_sha256,'payload',w.payload,'limits',limits,
  'narrative_admission',narrative_contract,'narrative_admission_sha256',case when narrative_contract is not null then public.combat_v2_sha256(narrative_contract) end,
   'provider_input_contract',case when c5_proof IS NOT NULL THEN mission_generic_owner.c1266_provider_input_v1(w.id,limits) ELSE case when c26_proof IS NOT NULL then jsonb_build_object(
 'schema_version','mission-generic-provider-input/4','input_tokens_limit',24000,'policy_version',pol.policy_version,'http_calls_per_generation',2,
 'scope',jsonb_build_object('schema_version','c1266-clean-staff-work-scope/1','execution_context','staff_mission',
 'master_session_id',w.master_session_id,'work_id',w.id,'event_id',w.event_id,'request_key',w.request_key,'revision',w.revision,
 'authority_receipt_id',w.authority_receipt_id,'definition_sha256',w.definition_sha256,'payload_sha256',w.payload_sha256,
 'payload_schema_version',w.payload->>'schema_version','run_control_version',w.run_control_version,
 'narrative_admission_sha256',case when narrative_contract is not null then public.combat_v2_sha256(narrative_contract) end,
 'release_sha256',c26_proof->>'release_sha256','finite_admission_sha256',c26_proof->>'finite_admission_sha256',
 'policy_snapshot_sha256',public.combat_v2_sha256(mission_generic_owner.c8_policy_snapshot_v1(w.id)),
 'financial_qualification_sha256',a.c8_count_qualification_sha256),
 'pricing',jsonb_build_object('model',pol.model,'reasoning_effort',pol.reasoning_effort,'store',pol.store,
 'max_output_tokens',limits->'max_output_tokens','input_usd_million',pol.input_usd_million,'output_usd_million',pol.output_usd_million,
 'count_upper_cost_usd','0.0124','generation_upper_cost_usd','0.0124'),
 'byte_bounds',jsonb_build_object('max_input_bytes',limits->'max_input_bytes','max_request_bytes',limits->'max_request_bytes')) else case when a.c7_budget_enforced then case when mission_generic_owner.c8_context24_scope_v1(w.id) then jsonb_build_object('schema_version','mission-generic-provider-input/3','input_tokens_limit',24000,'policy_version',pol.policy_version,'http_calls_per_generation',2,'scope',jsonb_build_object('schema_version','c889-context24-work-scope/1','session_id',w.master_session_id,'work_id',w.id,'batch_id',w.authority_receipt_id,'old_work_id','c88958e7-8983-4332-a14e-095076f967f4','financial_qualification_sha256',a.c8_count_qualification_sha256,'count_reserve_usd','0.0124','generation_reserve_usd','0.0124'),'pricing',jsonb_build_object('model',pol.model,'reasoning_effort',pol.reasoning_effort,'store',pol.store,'max_output_tokens',20000,'input_usd_million',pol.input_usd_million,'output_usd_million',pol.output_usd_million,'count_upper_cost_usd','0.0124','generation_upper_cost_usd','0.0124'),'byte_bounds',jsonb_build_object('max_input_bytes',limits->'max_input_bytes','max_request_bytes',limits->'max_request_bytes')) else jsonb_build_object('schema_version','mission-generic-provider-input/1','input_tokens_limit',(select max_input_tokens from mission_narrative_internal.runtime_policy where singleton),'policy_version',pol.policy_version,'http_calls_per_generation',2)  end else null end end end,
  'narrative_profile',case when narrative_contract is not null then narrative_contract->>'editorial_profile' when w.kind in('narration','director') and (mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id))
    then 'cinematic_master_1' else 'legacy' end) - case when not a.c7_budget_enforced then 'provider_input_contract' else '__no_key__' end);
end $function$

CREATE OR REPLACE FUNCTION public.mission_generic_input_count_start_v1(p_work uuid, p_lease uuid, p_payload_text text, p_payload_sha text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w mission_generic_owner.work_items;r mission_narrative_internal.dispatch_receipts;a mission_generic_owner.dispatch_admissions;pol mission_narrative_internal.runtime_policy;payload jsonb;projection jsonb;snap jsonb;details jsonb;old_details jsonb;measurement uuid:=gen_random_uuid();request_limit integer;count_quota jsonb;count_ticket uuid;count_staff boolean;c5_proof jsonb;campaign_budget jsonb;campaign_proof jsonb;
BEGIN
 perform mission_ai_board_owner.service_only();
 -- C1266_AVAILABILITY_COORD: shared before mutation locks; xact lifetime.
 PERFORM pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0));

 -- C9: freeze policy DML through proof, Native reserve and authorization.
 LOCK TABLE mission_narrative_internal.runtime_policy IN SHARE MODE;
 select * into strict pol from mission_narrative_internal.runtime_policy where singleton;

 -- Same scene-before-work order as Native claim/authorize.
 perform 1 from mission_generic_owner.role_window_cursors where master_session_id=(select master_session_id from mission_generic_owner.work_items where id=p_work) for update;
 perform 1 from public.master_v2_sessions where id=(select master_session_id from mission_generic_owner.work_items where id=p_work) for update; select * into strict w from mission_generic_owner.work_items where id=p_work for update;
 select * into strict a from mission_generic_owner.dispatch_admissions where master_session_id=w.master_session_id for update;
 select * into strict r from mission_narrative_internal.dispatch_receipts where id=w.dispatch_receipt_id for update;
 IF w.id='4fb5ea83-f90a-4b76-a6f5-722641d9da43'::uuid THEN pol.max_output_tokens:=(mission_generic_owner.c8_policy_snapshot_v1(w.id)->>'max_output_tokens')::integer;END IF;
 IF w.id='48e1bdcd-f044-be8c-1923-54d38e7e822c'::uuid AND (mission_generic_owner.c8_context24_scope_v1(w.id) IS DISTINCT FROM TRUE OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id) IS DISTINCT FROM TRUE) THEN RAISE EXCEPTION 'C889_CONTEXT24_RUNTIME_CLOSED' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 ma WHERE ma.master_session_id=w.master_session_id) THEN
  DECLARE manual_q jsonb:=mission_generic_owner.manual_staff_scope_v1(w.master_session_id);
          manual_sealed jsonb:=mission_generic_owner.c1266_historical_work_v1(w.id);
          manual_retained_continuation boolean:=false;
  BEGIN
   c5_proof:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);
   -- Same exact retained Writer4 continuation as provider input; no Count is reused.
   IF manual_sealed->>'release_sha256' IS DISTINCT FROM c5_proof->>'release_sha256'
    AND c5_proof#>>'{admission,schema_version}'='c1266-staff-admission-authority/3'
    AND w.kind='narration' AND w.payload->>'schema_version'='mission-generic-narration/4' AND w.payload->>'mode'='unified'
    AND mission_generic_owner.manual_staff_template_policy_v1(w.master_session_id) IS NOT NULL THEN
   DECLARE r32_parent uuid;r32_narrative jsonb;r32_proof jsonb;r32_history jsonb;r32_owner jsonb;r32_request jsonb;r32_receipt record;r32_count integer;
   BEGIN
    r32_narrative:=mission_public_owner.work_contract_v1(w.id);
    SELECT r32_batch.decision_work_id INTO r32_parent FROM mission_generic_owner.unified_batches r32_batch
     WHERE r32_batch.id=w.authority_receipt_id AND r32_batch.writer_work_id=w.id AND r32_batch.master_session_id=w.master_session_id;
    IF r32_parent IS NOT NULL THEN
     r32_proof:=mission_generic_owner.retained_director_adoption_v1(r32_parent,false);
     r32_history:=mission_generic_owner.c1266_historical_work_v1(w.id);
     r32_request:=jsonb_build_object('schema_version','mission-generic-request/1','master_session_id',w.master_session_id,
      'event_id',w.event_id,'request_key',w.request_key,'expected_revision',w.revision);
     SELECT * INTO r32_receipt FROM mission_narrative_internal.dispatch_receipts r32_dr WHERE r32_dr.id=w.dispatch_receipt_id;
     SELECT count(*),jsonb_agg(r32_marker.details)->0 INTO r32_count,r32_owner
      FROM mission_narrative_internal.dispatch_audit r32_marker
      WHERE r32_marker.receipt_id=w.dispatch_receipt_id AND r32_marker.event_code='c1266_async_owner_v1';
     IF r32_proof IS NOT NULL AND r32_proof->'published'='false'::jsonb
      AND r32_proof#>>'{applied,child_work_id}'=w.id::text
      AND r32_proof#>>'{applied,child_contract_sha256}'=public.combat_v2_sha256(r32_narrative)
      AND r32_proof#>>'{applied,child_payload_sha256}'=w.payload_sha256
      AND r32_proof#>'{applied,child_request}'=r32_request
      AND r32_proof#>>'{applied,adoption_release_sha256}'=r32_narrative->>'release_sha256'
      AND r32_history=r32_narrative#>'{source_attestation,execution_authority}'
      AND r32_history->>'schema_version'='c1266-work-execution-attestation/3'
      AND r32_history->>'release_sha256'=r32_narrative->>'release_sha256'
      AND r32_history->>'execution_context'=c5_proof->>'execution_context'
      AND r32_history->'admission'=c5_proof->'admission'
      AND r32_history->>'binding_sha256'=c5_proof->>'binding_sha256'
      AND r32_history->>'financial_qualification_sha256'=c5_proof->>'financial_qualification_sha256'
      AND r32_history->>'c7_budget_qualification_sha256'=c5_proof->>'c7_budget_qualification_sha256'
      AND r32_count=1 AND mission_factory_owner.keys_exact_v2(r32_owner,
       ARRAY['schema_version','actor_user_id','work_id','request_sha256','envelope_sha256','provider_timeout_ms'])
      AND r32_owner->>'schema_version'='mission-generic-async-owner/1'
      AND r32_owner->>'actor_user_id'=r32_proof->>'owner_user_id'
      AND r32_owner->>'work_id'=w.id::text
      AND r32_owner->>'request_sha256'=public.combat_v2_sha256(r32_request)
      AND r32_owner->>'envelope_sha256'=r32_receipt.envelope_sha256
      AND r32_receipt.master_session_id=w.master_session_id AND r32_receipt.authority_receipt_id=w.id
      AND r32_receipt.request_key=w.request_key
      AND r32_receipt.request_fingerprint=mission_internal.fingerprint(r32_request)
      AND r32_receipt.authority_sha256=r32_receipt.envelope_sha256
      AND r32_receipt.envelope_sha256=public.combat_v2_sha256(r32_receipt.envelope)
      AND r32_receipt.envelope->'narrative_admission'=r32_narrative
     THEN
      manual_retained_continuation:=true;
     END IF;
    END IF;
   END;
   END IF;
   IF manual_q IS NULL OR c5_proof IS NULL OR c5_proof->>'runtime_authorized' IS DISTINCT FROM 'true'
    OR c5_proof->>'execution_context' IS DISTINCT FROM 'staff_mission'
    OR c5_proof->'admission' IS DISTINCT FROM jsonb_build_object('schema_version','c1266-staff-admission-authority/3','kind','staff_finite','resource_scope','staff_simulation','finite_admission_sha256',public.combat_v2_sha256(manual_q),'admission_id',manual_q->>'start_receipt_id','location_id',manual_q->>'location_id')
    OR a.c7_budget_qualification_sha256 IS DISTINCT FROM manual_q->>'budget_qualification_sha256'
    OR manual_sealed IS NULL OR manual_sealed->>'schema_version' IS DISTINCT FROM 'c1266-work-execution-attestation/3'
    OR manual_sealed->'admission' IS DISTINCT FROM c5_proof->'admission'
    OR (manual_sealed->>'release_sha256' IS DISTINCT FROM c5_proof->>'release_sha256' AND (
     mission_generic_owner.native_reissue_continuation_v1(w.id)->>'current_release_sha256' IS DISTINCT FROM c5_proof->>'release_sha256' AND NOT manual_retained_continuation))
    OR manual_sealed->>'binding_sha256' IS DISTINCT FROM c5_proof->>'binding_sha256'
    OR manual_sealed->>'financial_qualification_sha256' IS DISTINCT FROM c5_proof->>'financial_qualification_sha256'
    OR manual_sealed->>'c7_budget_qualification_sha256' IS DISTINCT FROM c5_proof->>'c7_budget_qualification_sha256'
   THEN RAISE EXCEPTION 'MANUAL_STAFF_COUNT_INPUT_PROOF_REQUIRED' USING ERRCODE='42501';END IF;
  END;
 ELSIF EXISTS(SELECT 1 FROM mission_generic_owner.dispatch_admissions ad JOIN mission_factory_owner.editor_release_readiness rr ON rr.singleton
 WHERE ad.master_session_id=w.master_session_id
 AND ad.c7_budget_qualification_sha256=rr.canonical_preimage::jsonb#>>'{config,c1266_clean_staff,c7_budget_qualification_sha256}')
 AND (mission_generic_owner.c8_context24_scope_v1(w.id) IS DISTINCT FROM TRUE
 OR mission_generic_owner.c1266_clean_staff_admission_v1(w.master_session_id,true,true) IS NULL)
 THEN RAISE EXCEPTION 'C1266_CLEAN_INPUT_PROOF_REQUIRED' USING ERRCODE='42501';END IF;
 IF mission_generic_owner.c1266_opening_named_v1(w.master_session_id) THEN
  IF c5_proof IS NULL THEN c5_proof:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);END IF;
  IF c5_proof IS NULL OR mission_generic_owner.flow_scope_enabled(w.master_session_id) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'C1266_COUNT5_CLOSED' USING ERRCODE='42501';END IF;
 END IF;
 pol.max_input_tokens:=(mission_generic_owner.c8_policy_snapshot_v1(w.id)->>'max_input_tokens')::integer;
 perform mission_generic_owner.work_assert(w);perform mission_generic_owner.role_dispatch_assert_v4(w.id);perform mission_generic_owner.assert_runtime(w.master_session_id);perform mission_generic_owner.provider_ready(w.id);
 IF EXISTS(SELECT 1 FROM public.master_v2_sessions s726 WHERE s726.id=w.master_session_id AND s726.owner_kind='ai_service' AND s726.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND (EXISTS(SELECT 1 FROM mission_generic_owner.flow_staff_sessions f726 WHERE f726.master_session_id=s726.id AND f726.enabled) OR EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources q726 WHERE q726.session_id=s726.id AND q726.availability_scope='staff' AND q726.execution_context='staff_simulation'))) AND NOT mission_academy_owner.staff_carrier_runtime(w.master_session_id) AND NOT mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id) THEN RAISE EXCEPTION 'C726_FACTORY_STAFF_SCOPE_CLOSED' USING ERRCODE='42501';END IF;

 if not a.c7_budget_enforced or a.c8_count_upper_cost_usd is null or a.c8_count_qualification_sha256 is null then raise exception 'C8_COUNT_TARIFF_UNQUALIFIED' using errcode='55000';end if;
 IF pol.max_output_tokens=32000 THEN a.c8_count_upper_cost_usd:=0.0184;END IF; -- Work-local prudent extension, old admission and rate proof stay immutable.
 if w.state<>'claimed' or w.lease_id is distinct from p_lease or w.lease_expires_at<=clock_timestamp() or r.status<>'claimed' or r.authority_receipt_id<>w.id or r.master_session_id<>w.master_session_id or r.request_key<>w.request_key or r.event_kind<>'mission_generic_event' or r.renderer_version<>'mission-generic-runtime/1' or r.dispatch_count<>0 or w.authorization_id is not null or w.dispatch_id is not null or exists(select 1 from mission_narrative_internal.dispatch_attempts where receipt_id=r.id) or exists(select 1 from mission_narrative_internal.provider_authorizations where receipt_id=r.id) then raise exception 'C8_COUNT_SCOPE' using ERRCODE='P0001';end if;
 if p_payload_text is null or p_payload_sha !~ '^[0-9a-f]{64}$' or p_payload_sha is distinct from encode(extensions.digest(convert_to(p_payload_text,'UTF8'),'sha256'),'hex') then raise exception 'C8_COUNT_REQUEST_HASH' using errcode='22023';end if;
 payload:=p_payload_text::jsonb;
 request_limit:=case when w.kind='narration' and (mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id)) then 131072 when w.kind='director' and (mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id)) then 65536 else least(65536,(mission_generic_owner.capacity()->>'input_capacity_bytes')::integer) end;
  IF w.kind='director' AND c5_proof->>'runtime_authorized'='true' AND c5_proof->>'execution_context'='staff_mission' AND c5_proof#>>'{admission,kind}'='staff_finite' AND c5_proof#>>'{admission,resource_scope}'='staff_simulation' AND mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 gm WHERE gm.master_session_id=w.master_session_id) AND (mission_public_owner.work_contract_v1(w.id))->>'editorial_profile'='cinematic_master_1' THEN request_limit:=98304;END IF;
 -- Count validates the same tenfold full-request byte bound; token snapshot unchanged.
 request_limit:=request_limit*10;
 if octet_length(p_payload_text)>request_limit or not(payload ?& array['model','input','reasoning','text','store','max_output_tokens']) or payload-'model'-'input'-'reasoning'-'text'-'store'-'max_output_tokens'<>'{}'::jsonb or payload->>'model' is distinct from pol.model or payload->'reasoning' is distinct from jsonb_build_object('effort',pol.reasoning_effort) or payload->'store' is distinct from 'false'::jsonb or payload->'max_output_tokens' is distinct from to_jsonb(pol.max_output_tokens) or jsonb_typeof(payload->'input')<>'array' or jsonb_typeof(payload->'text')<>'object' then raise exception 'C8_COUNT_REQUEST_POLICY' using errcode='22023';end if;
 snap:=mission_generic_owner.c8_policy_snapshot_v1(w.id);projection:=payload-'store'-'max_output_tokens';
 select da.details into old_details from mission_narrative_internal.dispatch_audit da where da.receipt_id=r.id and da.event_code='c8_count_started';
 if found then
  if old_details->>'generation_request_sha256' is distinct from p_payload_sha or old_details->>'lease_id' is distinct from p_lease::text then raise exception 'C8_COUNT_REPLAY_CONFLICT' using ERRCODE='P0001';end if;
  return jsonb_build_object('schema_version','mission-generic-count-start/1','work_id',w.id,'measurement_id',old_details->>'measurement_id','granted_now',false,'generation_request_sha256',p_payload_sha,'count_request_sha256',old_details->>'count_request_sha256','model',old_details#>>'{policy_snapshot,model}','policy_version',(old_details#>>'{policy_snapshot,policy_version}')::integer,'max_input_tokens',(old_details#>>'{policy_snapshot,max_input_tokens}')::integer,'max_output_tokens',(old_details#>>'{policy_snapshot,max_output_tokens}')::integer,'policy_snapshot_sha256',old_details->>'policy_snapshot_sha256','count_http_calls',1,'generation_http_calls',0);
 end if;
 campaign_budget:=mission_generic_owner.c7_run_budget_v1(w.master_session_id,true,w.id);
 IF campaign_budget ? 'campaign_provider_deadline' THEN
  PERFORM 1 FROM staff_ai_quota_private.runtime WHERE singleton FOR UPDATE;
  campaign_budget:=mission_generic_owner.c7_run_budget_v1(w.master_session_id,true,w.id);
 END IF;
